// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import { IMocAdapter } from "../interfaces/IMocAdapter.sol";
import { IMocStateV1 } from "../interfaces/IMocV1.sol";
import { C } from "../lib/Constants.sol";
import { FixedPoint } from "../lib/FixedPoint.sol";
import { IPriceProvider } from "@moc/moc-main/contracts/interfaces/IPriceProvider.sol";

/// @title MocAdapterV1 to interact with MoC V1 contracts (single collateral, single pegged token)
/// @author Money On Chain
/// @notice This adapter connects the lending and borrowing system with MoC V1 contracts to get necessary data.
contract MocAdapterV1 is IMocAdapter {
    using FixedPoint for uint256;

    // -----------------
    // Storage
    // -----------------

    /// @notice Moc V1 contract
    address public immutable MOC_V1;
    /// @notice Moc State V1 contract
    IMocStateV1 public immutable MOC_STATE_V1;
    /// @notice Address of the TP token
    address public immutable TP_TOKEN;

    /// @notice Constructor
    /// @param mocV1_ The address of the MOC V1 contract
    /// @param mocStateV1_ The address of the MOC State V1 contract
    /// @param tpToken_ The address of the TP token
    constructor(address mocV1_, IMocStateV1 mocStateV1_, address tpToken_) {
        MOC_V1 = mocV1_;
        MOC_STATE_V1 = mocStateV1_;
        TP_TOKEN = tpToken_;
    }

    /// @inheritdoc IMocAdapter
    function validateAndGetPACtp(address mocBucket_, address tpToken_) external view returns (uint256, address) {
        if (mocBucket_ != MOC_V1 || tpToken_ != TP_TOKEN) revert InvalidBucket();

        IPriceProvider btcPriceProvider = IPriceProvider(MOC_STATE_V1.getBtcPriceProvider());
        (bytes32 priceBytes, bool valid) = btcPriceProvider.peek();
        if (!valid) revert InvalidPrice();

        return (uint256(priceBytes), C.COINBASE);
    }

    /// @inheritdoc IMocAdapter
    function isValidTP(address tpToken_) external view returns (bool) {
        return tpToken_ == TP_TOKEN;
    }

    /// @inheritdoc IMocAdapter
    function validateAndGetACToken(address mocBucket_) external view returns (address, bool) {
        if (mocBucket_ != MOC_V1) revert InvalidBucket();
        return (C.COINBASE, MOC_STATE_V1.state() == IMocStateV1.States.Liquidated);
    }

    /// @inheritdoc IMocAdapter
    function getLastPublicationBlock() external view returns (uint256) {
        IPriceProvider btcPriceProvider = IPriceProvider(MOC_STATE_V1.getBtcPriceProvider());
        return btcPriceProvider.getLastPublicationBlock();
    }

    /// @inheritdoc IMocAdapter
    function getEmissionRateByBucket(address mocBucket_, address tpToken_) external view returns (uint256) {
        if (mocBucket_ != MOC_V1 || tpToken_ != TP_TOKEN) revert InvalidBucket();
        uint256 tpTotalSupply = MOC_STATE_V1.docTotalSupply();
        uint256 tpAvailableToMint = MOC_STATE_V1.absoluteMaxDoc();
        // [PREC] = [N] * [PREC] / [N] + [N]
        return tpTotalSupply.divPrec(tpTotalSupply + tpAvailableToMint);
    }

    /// @inheritdoc IMocAdapter
    function getTPSupplyByBucket(address /*mocBucket_*/, address /*tpToken_*/) external pure returns (uint256) {
        // It is the only bucket, so return full supply rate
        return C.ONE;
    }

    /// @inheritdoc IMocAdapter
    function getMocBuckets() external view returns (address[] memory mocBuckets) {
        mocBuckets = new address[](1);
        mocBuckets[0] = MOC_V1;
        return mocBuckets;
    }

    /// @inheritdoc IMocAdapter
    /// @dev MoC V1 can be liquidated at the system level via state() == Liquidated
    function isLiquidatedBucket(address /*mocBucket_*/) external view returns (bool) {
        return MOC_STATE_V1.state() == IMocStateV1.States.Liquidated;
    }

    /// @inheritdoc IMocAdapter
    /// @dev MoC V1 can be liquidated at the system level; isLiquidated reflects the global liquidation state
    function validateAndGetPACtpAndLiquidated(
        address mocBucket_,
        address tpToken_
    ) external view returns (uint256 price, address acToken, bool isLiquidated) {
        if (mocBucket_ != MOC_V1 || tpToken_ != TP_TOKEN) revert InvalidBucket();

        bool liquidated = MOC_STATE_V1.state() == IMocStateV1.States.Liquidated;

        IPriceProvider btcPriceProvider = IPriceProvider(MOC_STATE_V1.getBtcPriceProvider());
        (bytes32 priceBytes, bool valid) = btcPriceProvider.peek();
        if (!valid) revert InvalidPrice();

        return (uint256(priceBytes), C.COINBASE, liquidated);
    }
}

