/**
 * @title IMocAdapter
 * @author Money On Chain
 * @notice Interface for MoC protocol adapters that provide price feeds and protocol information
 */
interface IMocAdapter {
    // -----------------
    // Custom Errors
    // -----------------

    /// @notice Thrown when the Moc Bucket is not part of the MoC system
    error InvalidBucket();

    /// @notice Thrown when the AC / TP price is invalid
    error InvalidPrice();

    /**
     * @notice Validates a bucket/TP pair and returns the price and AC token
     * @param mocBucket The MoC bucket address
     * @param tpToken The TP token address
     * @return price The current price of the TP token in AC
     * @return acToken The address of the AC token
     */
    function validateAndGetPACtp(
        address mocBucket,
        address tpToken
    ) external view returns (uint256 price, address acToken);

    /**
     * @notice Validates a bucket and returns its AC token address and liquidation status
     * @param mocBucket The MoC bucket address
     * @return acToken The address of the AC token for this bucket
     * @return isLiquidated True if the bucket has been liquidated
     */
    function validateAndGetACToken(address mocBucket) external view returns (address acToken, bool isLiquidated);

    /**
     * @notice Checks if a TP token is valid in the MoC system
     * @param tpToken The TP token address to validate
     * @return True if the TP token is valid, false otherwise
     */
    function isValidTP(address tpToken) external view returns (bool);

    /**
     * @notice Gets the last block number when oracle prices were published
     * @return The block number of the last publication
     */
    function getLastPublicationBlock() external view returns (uint256);

    /**
     * @notice Gets the emission rate for a specific bucket/TP pair
     * @param mocBucket The MoC bucket address
     * @param tpToken The TP token address
     * @return The emission rate
     */
    function getEmissionRateByBucket(address mocBucket, address tpToken) external view returns (uint256);

    /**
     * @notice Gets the total TP supply for a specific bucket/TP pair
     * @param mocBucket The MoC bucket address
     * @param tpToken The TP token address
     * @return The total TP supply
     */
    function getTPSupplyByBucket(address mocBucket, address tpToken) external view returns (uint256);

    /**
     * @notice Gets all registered MoC bucket addresses
     * @return An array of MoC bucket addresses
     */
    function getMocBuckets() external view returns (address[] memory);

    /**
     * @notice Checks if a bucket has been liquidated
     * @dev Returns false for adapters on protocols that do not support bucket liquidation (V1, V2)
     * @param mocBucket The MoC bucket address
     * @return True if the bucket has been liquidated, false otherwise
     */
    function isLiquidatedBucket(address mocBucket) external view returns (bool);

    /**
     * @notice Validates a bucket/TP pair and returns price, AC token, and liquidation status in one call.
     * @param mocBucket The MoC bucket address
     * @param tpToken The TP token address
     * @return price The current price of the TP token in AC
     * @return acToken The address of the AC token
     * @return isLiquidated True if the bucket has been liquidated
     */
    function validateAndGetPACtpAndLiquidated(
        address mocBucket,
        address tpToken
    ) external view returns (uint256 price, address acToken, bool isLiquidated);
}

