pragma solidity 0.8.24;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IMocSwapper } from "@moc/moc-main/contracts/interfaces/IMocSwapper.sol";
import { FixedPoint } from "./FixedPoint.sol";

/// @title A library to handle both ERC20 tokens and coinbase
/// @notice Coinbase is represented by the zero address (address(0))
/// @author Money On Chain
library Coin {
    using SafeERC20 for IERC20;
    using FixedPoint for uint256;

    // -----------------
    // Custom Errors
    // -----------------

    /// @notice Thrown when a coinbase transfer fails
    error CoinbaseTransferFailed();

    /// @notice Thrown when msg.value does not match the expected amount
    error WrongMsgValue();

    /// @notice Thrown when a swap operation fails
    error SwapFailed();

    IERC20 internal constant COINBASE = IERC20(address(0));

    /// @notice Returns the balance of an account for a given token or coinbase.
    /// @param self The token to query (use COINBASE for native coin).
    /// @param owner The address whose balance will be queried.
    /// @return The balance of the owner for the given token or coinbase.
    function coinBalanceOf(IERC20 self, address owner) internal view returns (uint256) {
        if (self == COINBASE) {
            return owner.balance;
        } else {
            return self.balanceOf(owner);
        }
    }

    /// @notice Transfers tokens or coinbase to a specified address.
    /// @param self The token to transfer (use COINBASE for native coin).
    /// @param to The address to receive the tokens or coinbase.
    /// @param amount The amount of tokens or coinbase to transfer.
    function coinTransfer(IERC20 self, address to, uint256 amount) internal {
        if (amount > 0) {
            if (self == COINBASE) {
                (bool success, ) = to.call{ value: amount }("");
                if (!success) revert CoinbaseTransferFailed();
            } else {
                self.safeTransfer(to, amount);
            }
        }
    }

    /// @notice Verifies that the msg.value matches the expected amount for coinbase transfers.
    /// @dev For ERC20 transfers, msg.value should be zero.
    /// @param self The token to verify (use COINBASE for native coin).
    /// @param amount The expected amount that should match msg.value for coinbase transfers.
    function coinVerifyValue(IERC20 self, uint256 amount) internal view {
        if (self == COINBASE) {
            if (msg.value != amount) revert WrongMsgValue();
        } else {
            if (msg.value > 0) revert WrongMsgValue();
        }
    }

    /// @notice Transfers tokens from one address to another.
    /// @dev For coinbase transfers, does nothing as coinbase is transferred via msg.value.
    /// @param self The token to transfer (use COINBASE for native coin).
    /// @param from The address to transfer tokens from.
    /// @param to The address to transfer tokens to.
    /// @param amount The amount of tokens to transfer.
    function coinTransferFrom(IERC20 self, address from, address to, uint256 amount) internal {
        if (self != COINBASE && amount > 0) {
            self.safeTransferFrom(from, to, amount);
        }
    }

    /// @notice Internal helper to safely get the maximum amount that can be swapped
    /// @param mocSwapper The address of the MocSwapper contract
    /// @param tokenIn The input token address
    /// @param tokenOut The output token address
    /// @return maxAmount The maximum amount that can be swapped, or 0 if the call fails
    function _getSafeMaxAmountToSwap(
        address mocSwapper,
        address tokenIn,
        address tokenOut
    ) internal view returns (uint256 maxAmount) {
        try IMocSwapper(mocSwapper).getSafeMaxAmountToSwap(tokenIn, tokenOut) returns (uint256 max) {
            maxAmount = max;
        } catch {
            // If getSafeMaxAmountToSwap fails, return 0
            maxAmount = 0;
        }
    }

    /// @notice Swaps tokens using MocSwapper with try-catch protection.
    /// @param self The token to swap from.
    /// @param mocSwapper The address of the MocSwapper contract.
    /// @param tokenOut The address of the token to receive.
    /// @param to The address to send the swapped tokens to.
    /// @param amountIn The amount of tokens to swap.
    /// @param minPriceOut The minimum token out price for the swap.
    /// @return realAmountIn The actual amount of tokens swapped in (0 if failed).
    /// @return amountOut The actual amount of tokens received from the swap (0 if failed).
    function swap(
        IERC20 self,
        address mocSwapper,
        address tokenOut,
        address to,
        uint256 amountIn,
        uint256 minPriceOut
    ) internal returns (uint256 realAmountIn, uint256 amountOut) {
        if (mocSwapper == address(0) || amountIn == 0) {
            return (0, 0);
        }

        uint256 maxAmountIn = _getSafeMaxAmountToSwap(mocSwapper, address(self), tokenOut);
        if (maxAmountIn == 0) {
            return (0, 0);
        }
        realAmountIn = Math.min(amountIn, maxAmountIn);
        // [N] = [N] * [PREC] / [PREC]
        uint256 minAmountOut = realAmountIn.mulPrec(minPriceOut);

        if (self == COINBASE) {
            try IMocSwapper(mocSwapper).swapCoinbase{ value: realAmountIn }(tokenOut, minAmountOut, to) returns (
                uint256 outputAmount
            ) {
                amountOut = outputAmount;
            } catch {
                // If swap fails, return zeros
                return (0, 0);
            }
        } else {
            self.forceApprove(address(mocSwapper), realAmountIn);
            try IMocSwapper(mocSwapper).swapRC20(address(self), tokenOut, realAmountIn, minAmountOut, to) returns (
                uint256 outputAmount
            ) {
                amountOut = outputAmount;
            } catch {
                // If swap fails, return zeros
                return (0, 0);
            }
        }
        return (realAmountIn, amountOut);
    }

    /// @notice Swaps tokens to get an exact output amount
    /// @param self The input token to swap from
    /// @param mocSwapper The swapper contract address
    /// @param tokenOut The output token address
    /// @param to The recipient address for the output tokens
    /// @param amountOut The desired output amount
    /// @param minPriceOut The minimum acceptable price (tokenOut/tokenIn) with PRECISION
    /// @return realAmountOut The actual amount of output tokens received
    /// @return amountIn The amount of input tokens spent
    function swapExactOutput(
        IERC20 self,
        address mocSwapper,
        address tokenOut,
        address to,
        uint256 amountOut,
        uint256 minPriceOut
    ) internal returns (uint256 realAmountOut, uint256 amountIn) {
        if (mocSwapper == address(0) || amountOut == 0) {
            return (0, 0);
        }

        uint256 maxAmountInToSwap = _getSafeMaxAmountToSwap(mocSwapper, address(self), tokenOut);
        if (maxAmountInToSwap == 0) {
            return (0, 0);
        }
        // [N] = [N] * [PREC] / [PREC]
        uint256 maxAmountIn = amountOut.divPrec(minPriceOut);
        if (maxAmountIn > maxAmountInToSwap) {
            maxAmountIn = maxAmountInToSwap;
            realAmountOut = maxAmountInToSwap.mulPrec(minPriceOut);
        } else {
            realAmountOut = amountOut;
        }
        if (self == COINBASE) {
            try
                IMocSwapper(mocSwapper).swapCoinbaseExactOutput{ value: maxAmountIn }(tokenOut, realAmountOut, to)
            returns (uint256 inputAmount) {
                amountIn = inputAmount;
            } catch {
                // If swap fails, return zero
                return (0, 0);
            }
        } else {
            self.forceApprove(address(mocSwapper), maxAmountIn);
            try
                IMocSwapper(mocSwapper).swapRC20ExactOutput(address(self), tokenOut, realAmountOut, maxAmountIn, to)
            returns (uint256 inputAmount) {
                amountIn = inputAmount;
            } catch {
                // If swap fails, return zero
                return (0, 0);
            }
        }
        return (realAmountOut, amountIn);
    }

    /// @notice Swaps tokens in two steps: first with core swapper, then with exchange swapper.
    /// @param self The token to swap from.
    /// @param swapperCore The address of the MoC Swapper Core contract.
    /// @param swapperExchange The address of the MoC Swapper Exchange contract.
    /// @param tokenOut The address of the token to receive.
    /// @param to The address to send the swapped tokens to.
    /// @param amountIn The amount of tokens to swap.
    /// @param minPriceOut The minimum token out price for the swap.
    /// @param revertOnFailure Whether to revert the transaction on failure swap.
    /// @return acSwapped The total actual amount of tokens swapped in.
    /// @return tpReceived The total actual amount of tokens received from the swap.
    function swapTwoSteps(
        IERC20 self,
        address swapperCore,
        address swapperExchange,
        address tokenOut,
        address to,
        uint256 amountIn,
        uint256 minPriceOut,
        bool revertOnFailure
    ) internal returns (uint256 acSwapped, uint256 tpReceived) {
        uint256 swapped;
        uint256 received;
        // Try swapping with core swapper first
        (swapped, received) = swap(self, swapperCore, tokenOut, to, amountIn, minPriceOut);

        acSwapped = swapped;
        tpReceived = received;

        // All was swapped in the first step
        if (amountIn == acSwapped) {
            return (acSwapped, tpReceived);
        }

        // Try swapping remaining AC with exchange swapper if any left
        (swapped, received) = swap(self, swapperExchange, tokenOut, to, amountIn - acSwapped, minPriceOut);
        acSwapped += swapped;
        tpReceived += received;

        if (revertOnFailure && (acSwapped == 0 || tpReceived == 0)) {
            revert SwapFailed();
        }
        return (acSwapped, tpReceived);
    }

    /// @notice Swaps tokens in two steps for exact output: first with core swapper, then with exchange swapper.
    /// @param self The token to swap from.
    /// @param swapperCore The address of the MoC Swapper Core contract.
    /// @param swapperExchange The address of the MoC Swapper Exchange contract.
    /// @param tokenOut The address of the token to receive.
    /// @param to The address to send the swapped tokens to.
    /// @param amountOut The exact amount of tokens to receive.
    /// @param minPriceOut The minimum token out price for the swap.
    /// @param revertOnFailure Whether to revert the transaction on failure swap.
    /// @return acSwapped The total actual amount of tokens swapped in.
    /// @return tpReceived The total actual amount of tokens received from the swap.
    function swapTwoStepsExactOutput(
        IERC20 self,
        address swapperCore,
        address swapperExchange,
        address tokenOut,
        address to,
        uint256 amountOut,
        uint256 minPriceOut,
        bool revertOnFailure
    ) internal returns (uint256 acSwapped, uint256 tpReceived) {
        uint256 swapped;
        uint256 received;
        // Try swapping with core swapper first
        (received, swapped) = swapExactOutput(self, swapperCore, tokenOut, to, amountOut, minPriceOut);

        acSwapped = swapped;
        tpReceived = received;

        // All was swapped in the first step
        if (amountOut == tpReceived) {
            return (acSwapped, tpReceived);
        }

        // Try swapping remaining AC with exchange swapper if any left
        (received, swapped) = swapExactOutput(self, swapperExchange, tokenOut, to, amountOut - tpReceived, minPriceOut);
        acSwapped += swapped;
        tpReceived += received;

        if (revertOnFailure && (acSwapped == 0 || tpReceived == 0)) {
            revert SwapFailed();
        }
        return (acSwapped, tpReceived);
    }
}

