pragma solidity 0.8.24;

import { C } from "./Constants.sol";

/// @title Fixed-point math helpers
/// @notice Wad-based (1e18) multiply/divide and utilities.
/// @author Money On Chain
library FixedPoint {
    /// @notice increment a number by 1, unchecked.
    /// @param i_ Input value.
    /// @return Incremented value.
    function uncheckedInc(uint256 i_) internal pure returns (uint256) {
        unchecked {
            return i_ + 1;
        }
    }

    /// @notice multiply two number and remove precision
    /// @param a Multiplicand
    /// @param b Multiplier
    /// @return result `a_` * `b_` / PRECISION
    function mulPrec(uint256 a, uint256 b) internal pure returns (uint256 result) {
        return (a * b) / C.PRECISION;
    }

    /// @notice add precision and div two number
    /// @param a Numerator
    /// @param b Denominator
    /// @return result `a_` * PRECISION / `b_`
    function divPrec(uint256 a, uint256 b) internal pure returns (uint256 result) {
        return (a * C.PRECISION) / b;
    }

    /// @notice Add precision
    /// @param a Input value without PRECISION
    /// @return Value with PRECISION
    function addPrec(uint256 a) internal pure returns (uint256) {
        return a * C.PRECISION;
    }

    /// @notice Remove precision
    /// @param a Input value with PRECISION
    /// @return Value without PRECISION
    function subPrec(uint256 a) internal pure returns (uint256) {
        return a / C.PRECISION;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import { FixedPoint } from "./FixedPoint.sol";
import { C } from "./Constants.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { TPInjector } from "../TPInjector.sol";

/**
 * @title MocLendingPool
 * @author Money On Chain
 * @notice Library for managing lending pool state and operations
 */
library MocLendingPool {
    using FixedPoint for uint256;
    using MocLendingPool for State;

    // -----------------
    // Custom Errors
    // -----------------

    /// @notice Thrown when trying to initialize an already initialized pool
    error PoolAlreadyInitialized();

    /// @notice Thrown when there is not enough liquidity in the pool
    error InsufficientLiquidity();

    /// @notice Thrown when the coverage ratio is below the minimum required
    error CoverageBelowMin();

    /// @notice Thrown when liquidation is not allowed
    error LiquidationNotAllowed();

    /// @notice Thrown when it is not time to inject TP tokens
    error MissingTimeToInject();

    /// @notice Thrown when an action is attempted while the vault is being liquidated
    error VaultBeingLiquidated();

    /// @notice Thrown when the TP injection is excessive compared to pool liquidity
    error ExcessiveTPInjection();

    /// @notice Thrown when there are insufficient AC tokens in the vault to remove
    error InsufficientACInVault();

    /// @notice Thrown when the amount results in zero units after conversion (dust amount)
    error AmountTooSmall();

    struct State {
        /// Pool Parameters ///
        /// @notice The TP token used in the lending pool.
        IERC20 tpToken;
        /// @notice TP Injector contract to inject TP tokens to the pool.
        TPInjector tpInjector;
        /// @notice Minimum coverage ratio required for a vault. [PREC]
        uint256 minCoverage;
        /// @notice Coverage threshold to liquidate a vault. [PREC]
        uint256 liquidationCoverage;
        /// @notice Borrow fee taken from the interest paid by borrowers. [PREC]
        uint256 borrowFee;
        /// @notice Utilization rate at which the kink occurs. [PREC]
        uint256 uKinkPoint;
        /// @notice Slope of the interest rate model when utilization is below the kink point. [PREC]
        uint256 uSoftSlope;
        /// @notice Slope of the interest rate model when utilization is above the kink point. [PREC]
        uint256 uMaxSlope;
        /// @notice TP emission rate at which the first brake occurs. [PREC]
        uint256 brakeFirstKink;
        /// @notice TP emission rate at which the second brake occurs. [PREC]
        uint256 brakeSecondKink;
        /// Pool Global States ///
        /// @notice Total liquidity available in the pool (in TP tokens).
        uint256 liquidity;
        /// @notice Total credit supply (in credit units).
        uint256 creditSupply;
        /// @notice Total deposit supply (in deposit units).
        uint256 depositSupply;
        /// @notice Injection base factor used for calculating TP injection. [PREC]
        uint256 injectionBaseFactor;
        /// @notice Next time to inject TP tokens.
        uint256 nextInjectionTime;
        /// @notice Time span to inject TP tokens.
        uint256 injectionTimeSpan;
        /// @notice TP injected per second [PREC]
        uint256 injectionRate;
        /// @notice Borrow base interest rate from TP injection [PREC]
        uint256 borrowInjectionRate;
        /// Pool Last Snapshot ///
        /// @notice Last time the interest was accrued.
        uint256 lastUpdateTime;
        /// @notice Last fee accrued from borrowers. [N]
        uint256 lastFeeAccrued;
        /// @notice Last price of the credit unit. [PREC]
        uint256 lastPCU;
        /// @notice Reserve TP tokens used during a vault liquidation.
        /// TP are added when a liquidation has a surplus and removed when there is a deficit.
        uint256 reservePool;
        /// Pool Users Balances ///
        /// @notice Users deposit unit balances
        mapping(address user => uint256 depositBalance) depositBalance;
        /// @notice Users vaults credit unit balances
        mapping(address user => mapping(address mocBucket => uint256 vaultCreditBalance)) vaultCreditBalance;
        /// @notice Users vaults AC token balances
        mapping(address user => mapping(address mocBucket => uint256 vaultACBalance)) vaultACBalance;
        /// @notice Credit units pending during an ongoing liquidation
        mapping(address user => mapping(address mocBucket => uint256)) liquidationCUPending;
        /// @notice Flag indicating if a vault is currently being liquidated
        mapping(address user => mapping(address mocBucket => bool)) isLiquidating;
    }

    /// @notice Initialize the lending pool with the given parameters.
    /// @param self The lending pool state.
    /// @param tpToken_ The TP token used in the lending pool.
    /// @param tpInjector_ TP Injector contract to inject TP tokens to the pool.
    /// @param minCoverage_ Minimum coverage ratio required for a vault. [PREC]
    /// @param liquidationCoverage_ Coverage threshold to liquidate a vault. [PREC]
    /// @param borrowFee_ Borrow fee taken from the interest paid by borrowers. [PREC]
    /// @param uKinkPoint_ Utilization rate at which the kink occurs. [PREC]
    /// @param uSoftSlope_ Slope of the interest rate model when utilization is below the kink point. [PREC]
    /// @param uMaxSlope_ Slope of the interest rate model when utilization is above the kink point. [PREC]
    /// @param injectionTimeSpan_ Time span to inject TP tokens.
    /// @param injectionBaseFactor_ Injection base factor used for calculating TP injection. [PREC]
    /// @param brakeFirstKink_ TP emission rate at which the first brake occurs. [PREC]
    /// @param brakeSecondKink_ TP emission rate at which the second brake occurs. [PREC]
    function initialize(
        State storage self,
        address tpToken_,
        address tpInjector_,
        uint256 minCoverage_,
        uint256 liquidationCoverage_,
        uint256 borrowFee_,
        uint256 uKinkPoint_,
        uint256 uSoftSlope_,
        uint256 uMaxSlope_,
        uint256 injectionTimeSpan_,
        uint256 injectionBaseFactor_,
        uint256 brakeFirstKink_,
        uint256 brakeSecondKink_
    ) internal {
        if (address(self.tpToken) != address(0)) revert PoolAlreadyInitialized();

        self.tpToken = IERC20(tpToken_);
        self.tpInjector = TPInjector(payable(tpInjector_));
        self.minCoverage = minCoverage_;
        self.liquidationCoverage = liquidationCoverage_;
        self.borrowFee = borrowFee_;
        self.uKinkPoint = uKinkPoint_;
        self.uSoftSlope = uSoftSlope_;
        self.uMaxSlope = uMaxSlope_;
        self.nextInjectionTime = block.timestamp + injectionTimeSpan_;
        self.injectionTimeSpan = injectionTimeSpan_;
        self.injectionBaseFactor = injectionBaseFactor_;
        self.brakeFirstKink = brakeFirstKink_;
        self.brakeSecondKink = brakeSecondKink_;
        self.injectionRate = 0;
        self.borrowInjectionRate = 0;
        self.reservePool = 0;
        self.lastUpdateTime = block.timestamp;
        self.lastPCU = C.ONE; // initial price of credit unit is 1 TP token
    }

    /// @notice Deposit TP tokens into the lending pool.
    /// @param self The lending pool state.
    /// @param user_ The address of the user making the deposit.
    /// @param tpAmount_ The amount of TP tokens to deposit.
    /// @return depositUnits The amount of deposit units received.
    function deposit(State storage self, address user_, uint256 tpAmount_) internal returns (uint256 depositUnits) {
        // accrue interest before any action
        self.accrueInterest();

        // [N] = [N] * [PREC] / [PREC]
        depositUnits = tpAmount_.divPrec(self.priceDepositUnit());
        if (depositUnits == 0) revert AmountTooSmall();
        // update states
        self.liquidity += tpAmount_;
        self.depositSupply += depositUnits;
        self.depositBalance[user_] += depositUnits;
    }

    /// @notice Withdraw TP tokens from the lending pool.
    /// @param self The lending pool state.
    /// @param user_ The address of the user making the withdrawal.
    /// @param depositUnits_ The amount of deposit units to withdraw.
    /// @return tpToWithdraw The amount of TP tokens withdrawn.
    function withdraw(
        State storage self,
        address user_,
        uint256 depositUnits_
    ) internal returns (uint256 tpToWithdraw) {
        // accrue interest before any action
        self.accrueInterest();

        uint256 depositToWithdraw = Math.min(self.depositBalance[user_], depositUnits_);

        // [N] = [N] * [PREC] / [PREC]
        tpToWithdraw = depositToWithdraw.mulPrec(self.priceDepositUnit());
        if (self.liquidity < tpToWithdraw) revert InsufficientLiquidity();

        // update states
        self.liquidity -= tpToWithdraw;
        self.depositSupply -= depositToWithdraw;
        self.depositBalance[user_] -= depositToWithdraw;

        // when pool had deposits and withdrawals, liquidity could be > 0 due to rounding.
        // We need to reset liquidity to 0 in that case to avoid issues calculating PDU.
        if (self.depositSupply == 0) {
            self.liquidity = 0;
            // reset injection rates as there are no deposits
            // this is a very unusual case, so if there are TPs injected that are not accounted for liquidity yet
            // they are simply ignored and locked in the contract, they could be recovered by governance later
            self.borrowInjectionRate = 0;
            self.injectionRate = 0;
            // when no deposits, no credit neither. So we can reset PCU to 1
            self.lastPCU = C.ONE;
        }

        return tpToWithdraw;
    }

    /// @notice Add AC tokens to a user's vault as collateral.
    /// @param self The lending pool state.
    /// @param user_ The address of the user adding AC tokens to their vault.
    /// @param mocBucket_ The Moc Bucket which use the AC token to be added as collateral.
    /// @param acAmount_ The amount of AC tokens to add to the vault.
    function addACtoVault(State storage self, address user_, address mocBucket_, uint256 acAmount_) internal {
        if (self.isLiquidating[user_][mocBucket_]) revert VaultBeingLiquidated();

        // update states
        self.vaultACBalance[user_][mocBucket_] += acAmount_;
    }

    /// @notice Remove AC tokens from a user's vault.
    /// @dev The user can only remove AC tokens if their vault maintains the minimum coverage ratio after the removal.
    /// @param self The lending pool state.
    /// @param user_ The address of the user removing AC tokens from their vault.
    /// @param mocBucket_ The Moc Bucket which use the AC token to be removed from the vault.
    /// @param acAmount_ The amount of AC tokens to remove from the vault.
    /// @param pACtp_ AC/TP price (validated by the manager). [PREC]
    /// @param minCoverageRequired_ The minimum coverage ratio required.
    function removeACfromVault(
        State storage self,
        address user_,
        address mocBucket_,
        uint256 acAmount_,
        uint256 pACtp_,
        uint256 minCoverageRequired_
    ) internal {
        if (self.isLiquidating[user_][mocBucket_]) revert VaultBeingLiquidated();

        // accrue interest before any action
        self.accrueInterest();

        uint256 vaultACBalance = self.vaultACBalance[user_][mocBucket_];
        if (acAmount_ > vaultACBalance) revert InsufficientACInVault();

        uint256 newVaultACBalance = vaultACBalance - acAmount_;
        uint256 vaultCreditBalance = self.vaultCreditBalance[user_][mocBucket_];
        // if vault has zero credit balance, it can remove all the AC tokens its has
        if (vaultCreditBalance > 0) {
            uint256 coverage = vaultCoverage(vaultCreditBalance, newVaultACBalance, self.lastPCU, pACtp_);
            if (coverage < minCoverageRequired_) revert CoverageBelowMin();
        }

        // update states
        self.vaultACBalance[user_][mocBucket_] = newVaultACBalance;
    }

    /// @notice Borrow TP tokens from the lending pool using AC tokens as collateral.
    /// @dev The user must have the AC tokens in their vault and maintain the minimum coverage ratio after borrowing.
    /// @param self The lending pool state.
    /// @param user_ The address of the user borrowing TP tokens.
    /// @param mocBucket_ The Moc Bucket which use the AC token as collateral.
    /// @param tpAmount_ The amount of TP tokens to borrow.
    /// @param pACtp_ AC/TP price (validated by the manager). [PREC]
    /// @return creditUnits The amount of credit units issued.
    function borrow(
        State storage self,
        address user_,
        address mocBucket_,
        uint256 tpAmount_,
        uint256 pACtp_
    ) internal returns (uint256 creditUnits) {
        if (self.isLiquidating[user_][mocBucket_]) revert VaultBeingLiquidated();
        // accrue interest before any action
        self.accrueInterest();

        if (self.liquidity < tpAmount_) revert InsufficientLiquidity();

        // [N] = [N] * [PREC] / [PREC]
        creditUnits = tpAmount_.divPrec(self.lastPCU);
        if (creditUnits == 0) revert AmountTooSmall();
        uint256 newVaultCreditBalance = self.vaultCreditBalance[user_][mocBucket_] + creditUnits;
        uint256 vaultACBalance = self.vaultACBalance[user_][mocBucket_];

        uint256 coverage = vaultCoverage(newVaultCreditBalance, vaultACBalance, self.lastPCU, pACtp_);
        if (coverage < self.minCoverage) revert CoverageBelowMin();

        // update states
        self.liquidity -= tpAmount_;
        self.creditSupply += creditUnits;
        self.vaultCreditBalance[user_][mocBucket_] = newVaultCreditBalance;
    }

    /// @notice Repay borrowed TP tokens to the lending pool.
    /// @dev The user repays using credit units, which are converted to TP tokens
    /// based on the current price of the credit unit.
    /// As well, a portion of the repayment is taken as fees based on the reserve factor and sent to the MoC fee flow.
    /// @param self The lending pool state.
    /// @param user_ The address of the user repaying the borrowed TP tokens.
    /// @param mocBucket_ The Moc Bucket which use the AC token as collateral.
    /// @param creditUnits_ The amount of credit units to repay.
    /// @return totalTPtoRepay The amount of TP tokens repaid. (includes the fees taken)
    /// @return tpToFeeFlow The amount of TP tokens taken as fees and sent to the MoC fee flow.
    function repay(
        State storage self,
        address user_,
        address mocBucket_,
        uint256 creditUnits_
    ) internal returns (uint256 totalTPtoRepay, uint256 tpToFeeFlow) {
        if (self.isLiquidating[user_][mocBucket_]) revert VaultBeingLiquidated();
        // accrue interest before any action
        self.accrueInterest();

        uint256 creditToRepay = Math.min(self.vaultCreditBalance[user_][mocBucket_], creditUnits_);

        // [N] = [N] * [PREC] / [PREC]
        totalTPtoRepay = creditToRepay.mulPrec(self.lastPCU);

        uint256 lastFeeAccrued = self.lastFeeAccrued;
        uint256 creditSupply = self.creditSupply;

        tpToFeeFlow = calcFee(lastFeeAccrued, creditToRepay, creditSupply);

        // update states
        self.liquidity += totalTPtoRepay - tpToFeeFlow;
        self.lastFeeAccrued = lastFeeAccrued - tpToFeeFlow;
        self.creditSupply = creditSupply - creditToRepay;
        self.vaultCreditBalance[user_][mocBucket_] -= creditToRepay;

        return (totalTPtoRepay, tpToFeeFlow);
    }

    /// @notice Calculate the amount of TP needed to repay a certain amount of credit units
    /// @dev This function accrues interest to get the current PCU, then calculates the TP amount needed
    /// and finally converts it to AC using the provided price
    /// @param self The lending pool state
    /// @param user_ The address of the user whose vault is being liquidated.
    /// @param mocBucket_ The Moc Bucket which use the AC token as collateral.
    /// @param creditUnits_ The amount of credit units to repay
    /// @return The amount of TP tokens needed to swap for the required ACs
    function calculateTPforRepay(
        State storage self,
        address user_,
        address mocBucket_,
        uint256 creditUnits_
    ) internal returns (uint256) {
        // Accrue interest to get current PCU
        self.accrueInterest();
        // Determine how many credit units can actually be repaid
        uint256 creditToRepay = Math.min(self.vaultCreditBalance[user_][mocBucket_], creditUnits_);

        // Calculate how many TPs we need to repay
        // [N] = [N] * [PREC] / [PREC]
        return creditToRepay.mulPrec(self.lastPCU);
    }

    /// @notice Trigger a liquidation of a user's vault if its coverage ratio is below the liquidation threshold.
    /// @dev Can be called multiple times during a multi-step liquidation process.
    /// On first call, stores the credit unit debt. On subsequent calls, returns stored value.
    /// @param self The lending pool state.
    /// @param user_ The address of the user whose vault is being liquidated.
    /// @param mocBucket_ The Moc Bucket which use the AC token as collateral.
    /// @param pACtp_ AC/TP price (validated by the manager). [PREC]
    /// @return acInVault The amount of AC tokens available in the user's vault.
    function triggerLiquidation(
        State storage self,
        address user_,
        address mocBucket_,
        uint256 pACtp_
    ) internal returns (uint256 acInVault) {
        // accrue interest before any action
        self.accrueInterest();

        acInVault = self.vaultACBalance[user_][mocBucket_];

        // If not liquidating yet, initialize liquidation
        if (!self.isLiquidating[user_][mocBucket_]) {
            uint256 vaultCreditBalance = self.vaultCreditBalance[user_][mocBucket_];

            // Check coverage
            uint256 coverage = vaultCoverage(vaultCreditBalance, acInVault, self.lastPCU, pACtp_);
            if (coverage > self.liquidationCoverage) revert LiquidationNotAllowed();

            // Store credit unit debt and set liquidation flag
            self.liquidationCUPending[user_][mocBucket_] = vaultCreditBalance;
            self.isLiquidating[user_][mocBucket_] = true;
        }

        return acInVault;
    }

    /// @notice Process debt payment during liquidation using obtained TP tokens.
    /// @dev Calculates how much debt can be paid with obtained TP, updates pool state,
    /// and returns the TP used and fees charged.
    /// @param self The lending pool state.
    /// @param user_ The address of the user whose vault is being liquidated.
    /// @param mocBucket_ The Moc Bucket which use the AC token as collateral.
    /// @param cuPending_ The amount of credit units pending to be paid.
    /// @param tpObtained_ The amount of TP tokens obtained from the swap.
    /// @return tpUsed The amount of TP tokens used to pay the debt.
    /// @return tpToFeeFlow The amount of TP tokens taken as fees.
    function processLiquidationDebtPayment(
        State storage self,
        address user_,
        address mocBucket_,
        uint256 cuPending_,
        uint256 tpObtained_
    ) internal returns (uint256 tpUsed, uint256 tpToFeeFlow) {
        // Calculate how much credit can be paid with obtained TP
        // [N] = [N] * [PREC] / [PREC]
        uint256 maxCreditFromTP = tpObtained_.divPrec(self.lastPCU);

        uint256 creditToPay;
        if (maxCreditFromTP >= cuPending_) {
            // All remaining debt can be paid - calculate exact TP needed for the debt
            creditToPay = cuPending_;
            // [N] = [N] * [PREC] / [PREC]
            tpUsed = creditToPay.mulPrec(self.lastPCU);
        } else {
            // Partial payment - use ALL the TP obtained (avoids rounding loss)
            creditToPay = maxCreditFromTP;
            tpUsed = tpObtained_;
        }

        // Calculate fee proportional to credit being paid
        tpToFeeFlow = calcFee(self.lastFeeAccrued, creditToPay, self.creditSupply);

        // Update liquidity and fees
        self.liquidity += tpUsed - tpToFeeFlow;
        self.lastFeeAccrued -= tpToFeeFlow;

        // Update credit state
        self.creditSupply -= creditToPay;
        self.vaultCreditBalance[user_][mocBucket_] -= creditToPay;

        // Update pending CU debt
        self.liquidationCUPending[user_][mocBucket_] = cuPending_ - creditToPay;

        return (tpUsed, tpToFeeFlow);
    }

    /// @notice Process a liquidation step by applying the swapped AC and obtained TP.
    /// @dev This function handles partial liquidations. It removes swapped AC from vault,
    /// reduces the pending CU debt, adds liquidity, and determines if liquidation is complete.
    /// Liquidation is complete when either all AC is removed OR all debt is paid.
    /// @param self The lending pool state.
    /// @param user_ The address of the user whose vault is being liquidated.
    /// @param mocBucket_ The Moc Bucket which use the AC token as collateral.
    /// @param acSwapped_ The amount of AC tokens that were swapped in this step.
    /// @param tpObtained_ The amount of TP tokens obtained from the swap in this step.
    /// @return tpToFeeFlow The amount of TP tokens taken as fees and sent to the MoC fee flow.
    /// @return isComplete True if liquidation is complete, false if more steps are needed.
    function liquidate(
        State storage self,
        address user_,
        address mocBucket_,
        uint256 acSwapped_,
        uint256 tpObtained_
    ) internal returns (uint256 tpToFeeFlow, bool isComplete) {
        // accrue interest is not needed here, already done in triggerLiquidation

        // Check if vault is being liquidated
        if (!self.isLiquidating[user_][mocBucket_]) revert LiquidationNotAllowed();

        uint256 cuPending = self.liquidationCUPending[user_][mocBucket_];
        // Remove the swapped AC from vault
        self.vaultACBalance[user_][mocBucket_] -= acSwapped_;

        uint256 tpUsed;

        // If there's debt to pay, process payment
        if (cuPending > 0) {
            (tpUsed, tpToFeeFlow) = self.processLiquidationDebtPayment(user_, mocBucket_, cuPending, tpObtained_);
        } else {
            // No debt remaining - all TP obtained goes to reserves (surplus)
            tpUsed = 0;
            tpToFeeFlow = 0;
        }

        // Check if liquidation is complete (all AC swapped)
        isComplete = self.vaultACBalance[user_][mocBucket_] == 0;
        uint256 finalCuPending = self.liquidationCUPending[user_][mocBucket_];
        if (finalCuPending == 0) {
            // If all debt paid, add any excess TP obtained to the reserve
            if (tpObtained_ > tpUsed) {
                self.reservePool += tpObtained_ - tpUsed;
            }
        } else {
            if (isComplete) {
                // If there's still debt but no AC left, take from reserve to cover it
                // [N] = [N] * [PREC] / [PREC]
                uint256 tpDebtRemaining = finalCuPending.mulPrec(self.lastPCU);
                uint256 tpFromReserves = Math.min(self.reservePool, tpDebtRemaining);

                // Adjust last fee accrued proportionally to the credit being cleared
                self.lastFeeAccrued -= calcFee(self.lastFeeAccrued, finalCuPending, self.creditSupply);

                // Transfer from reserves to liquidity to cover the debt
                self.reservePool -= tpFromReserves;
                self.liquidity += tpFromReserves;

                // Clear pending liquidation
                self.liquidationCUPending[user_][mocBucket_] = 0;

                // Clear remaining credit balance and credit supply
                self.creditSupply -= finalCuPending;
                self.vaultCreditBalance[user_][mocBucket_] = 0;
            }
        }

        if (isComplete) {
            // Liquidation is complete - clear the flag
            self.isLiquidating[user_][mocBucket_] = false;
        }

        return (tpToFeeFlow, isComplete);
    }

    /// @notice Calculate the fee to be taken from the repayment based on the proportion of credit being repaid.
    /// @dev The fee is calculated as a percentage of the last fee accrued, proportional to the
    /// amount of credit being repaid relative to the total credit supply.
    /// Formula: fee = lastFeeAccrued * (creditToPay / creditSupply)
    /// @param lastFeeAccrued_ The total amount of pending fees
    /// @param creditToPay_ The amount of credit units being repaid.
    /// @param creditSupply_ The total credit supply before the repayment. (in credit units)
    /// @return fee The fee to be taken from the repayment. (in TP tokens)
    function calcFee(
        uint256 lastFeeAccrued_,
        uint256 creditToPay_,
        uint256 creditSupply_
    ) internal pure returns (uint256 fee) {
        // Guard against division-by-zero when creditSupply_ is 0
        if (creditSupply_ == 0) return 0;
        // [N] = [N] * [N] / [N]
        fee = (lastFeeAccrued_ * creditToPay_) / creditSupply_;
    }

    /**
     * @notice Applies accrued interest to total borrows and reserves
     * @dev This calculates interest accrued from the last checkpoint block
     *   up to the current block and writes new checkpoint to storage.
     * @param self The lending pool state.
     */
    function accrueInterest(State storage self) internal {
        uint256 _lastUpdateTime = self.lastUpdateTime;

        /* Short-circuit accumulating 0 interest */
        if (block.timestamp == _lastUpdateTime) {
            return;
        }

        // Cache storage reads to save gas
        uint256 _liquidity = self.liquidity;
        uint256 _lastPCU = self.lastPCU;

        uint256 lastTimeInjectionApplicable = self.getLastTimeInjectionApplicable();
        uint256 deltaPCU = self.getDeltaPCU(_liquidity, _lastPCU, _lastUpdateTime, lastTimeInjectionApplicable);
        uint256 deltaLiquidity = self.getDeltaLiquidity(_lastUpdateTime, lastTimeInjectionApplicable);

        // Write to storage once
        self.lastPCU = _lastPCU + deltaPCU;
        self.liquidity = _liquidity + deltaLiquidity;
        self.lastFeeAccrued += self.getDeltaFee(deltaPCU);
        self.lastUpdateTime = block.timestamp;
    }

    /// @notice Calculates the coverage of a given vault values.
    /// @param vaultCreditBalance_ The amount of credit units in the vault.
    /// @param vaultACBalance_ The amount of AC tokens in the vault.
    /// @param pCU_ The price of the credit unit.
    /// @param pACtp_ The price of the AC token in terms of TP token.
    /// @return The coverage of a given vault values. [PREC]
    function vaultCoverage(
        uint256 vaultCreditBalance_,
        uint256 vaultACBalance_,
        uint256 pCU_,
        uint256 pACtp_
    ) internal pure returns (uint256) {
        // [PREC] = [N] * [PREC]
        uint256 borrows = vaultCreditBalance_ * pCU_;
        if (borrows == 0) {
            return C.MAX_UINT;
        }
        // [PREC] = [N] * [PREC] * [PREC] / [PREC]
        return (vaultACBalance_ * pACtp_).divPrec(borrows);
    }

    /// @notice Get the current price of the deposit unit.
    /// @dev The price of the deposit unit (PDU) is calculated based on the total liquidity,
    /// total credit supply, price of the credit unit, and total deposit supply.
    /// @param self The lending pool state.
    /// @return The current price of the deposit unit. [PREC]
    function priceDepositUnit(State storage self) internal view returns (uint256) {
        if (self.depositSupply == 0) {
            return C.ONE;
        }
        // [PREC] = [N] * [PREC] / [N]
        return self.getAvailableCash().divPrec(self.depositSupply);
    }

    /// @notice Get the current price of the credit unit.
    /// @dev The price of the credit unit (PCU) is updated based on the borrow
    /// rate and the time elapsed since the last update.
    /// @param self The lending pool state.
    /// @return The current price of the credit unit. [PREC]
    function priceCreditUnit(State storage self) internal view returns (uint256) {
        uint256 pCU = self.lastPCU;
        uint256 lastUpdateTime = self.lastUpdateTime;
        if (block.timestamp > lastUpdateTime) {
            uint256 lastTimeInjectionApplicable = self.getLastTimeInjectionApplicable();
            return pCU + self.getDeltaPCU(self.liquidity, pCU, lastUpdateTime, lastTimeInjectionApplicable);
        }
        return pCU;
    }

    /// @notice Get the current liquidity of the pool.
    /// @dev The liquidity is updated based on the injection rate
    /// and the time elapsed since the last update.
    /// @param self The lending pool state.
    /// @return The current liquidity of the pool. (in TP tokens)
    function liquidityFresh(State storage self) internal view returns (uint256) {
        uint256 lastUpdateTime = self.lastUpdateTime;
        if (block.timestamp > lastUpdateTime) {
            uint256 lastTimeInjectionApplicable = self.getLastTimeInjectionApplicable();
            return self.liquidity + self.getDeltaLiquidity(lastUpdateTime, lastTimeInjectionApplicable);
        }
        return self.liquidity;
    }

    /// @notice Get the current fee accrued from borrowers.
    /// @dev The fee accrued is updated based on the borrow fee,
    /// total credit supply, and the change in the price of the credit unit since the last update.
    /// @param self The lending pool state.
    /// @return The current fee accrued from borrowers. [N]
    function getFeeAccrued(State storage self) internal view returns (uint256) {
        uint256 pCU = self.lastPCU;
        uint256 lastUpdateTime = self.lastUpdateTime;
        if (block.timestamp > lastUpdateTime) {
            uint256 lastTimeInjectionApplicable = self.getLastTimeInjectionApplicable();
            uint256 deltaPCU = self.getDeltaPCU(self.liquidity, pCU, lastUpdateTime, lastTimeInjectionApplicable);
            return self.lastFeeAccrued + self.getDeltaFee(deltaPCU);
        }
        return self.lastFeeAccrued;
    }

    /// @notice Calculate the change in liquidity since the last update due to the injection rate.
    /// @dev This function calculates the delta of the liquidity based on the injection rate
    /// and the time elapsed since the last update.
    /// @param self The lending pool state.
    /// @param lastUpdateTime_ The last time the interest was accrued.
    /// @param lastTimeInjectionApplicable_ The last time injection was applicable.
    /// @return The change in liquidity. (in TP tokens)
    function getDeltaLiquidity(
        State storage self,
        uint256 lastUpdateTime_,
        uint256 lastTimeInjectionApplicable_
    ) internal view returns (uint256) {
        // update liquidity with injected TP tokens if we are in an injection cycle
        if (lastTimeInjectionApplicable_ <= lastUpdateTime_) {
            return 0;
        }
        return self.injectionRate.mulPrec(lastTimeInjectionApplicable_ - lastUpdateTime_);
    }

    /// @notice Calculate the change in the price of the credit unit since the last update.
    /// @dev This function calculates the delta of the price of the credit unit (PCU) based on the borrow rate
    /// and the time elapsed since the last update.
    /// @param self The lending pool state.
    /// @param liquidity_ The current liquidity of the pool.
    /// @param pCU_ The current price of the credit unit.
    /// @param lastUpdateTime_ The last time the interest was accrued.
    /// @param lastTimeInjectionApplicable_ The last time injection was applicable.
    /// @return The change in the price of the credit unit. [PREC]
    function getDeltaPCU(
        State storage self,
        uint256 liquidity_,
        uint256 pCU_,
        uint256 lastUpdateTime_,
        uint256 lastTimeInjectionApplicable_
    ) internal view returns (uint256) {
        // amount of borrow interest to be charged since last update
        // [PREC] = [PREC] + [PREC]
        uint256 borrowInc = self.getInterestByUtilization(liquidity_, pCU_, lastUpdateTime_) +
            self.getInterestByInjection(lastUpdateTime_, lastTimeInjectionApplicable_);
        // add the borrow fee to the credit unit price
        // [PREC] = ([PREC] * [PREC]) / [PREC]
        return (pCU_ * borrowInc) / (C.ONE - self.borrowFee);
    }

    /// @notice Calculate the change in the fee accrued since the last update.
    /// @dev This function calculates the delta of the fee accrued based on the borrow fee,
    /// total credit supply, and the change in the price of the credit unit since the last update.
    /// The formula used is: deltaFee = borrowFee * totalCreditSupply * deltaPCU
    /// @param self The lending pool state.
    /// @param deltaPCU_ The change in the price of the credit unit since the last update. [PREC]
    /// @return The change in the fee accrued. [N]
    function getDeltaFee(State storage self, uint256 deltaPCU_) internal view returns (uint256) {
        // [N] = [PREC] * ([N] * [PREC] / [PREC]) / [PREC]
        return self.borrowFee.mulPrec(self.creditSupply.mulPrec(deltaPCU_));
    }

    /// @notice Calculate the interest  contribution from the injection rate.
    /// @dev This function calculates the borrow interest contribution based on the injection rate
    /// and the time elapsed since the last update.
    /// @param self The lending pool state.
    /// @param lastUpdateTime_ The last time the interest was accrued.
    /// @param lastTimeInjectionApplicable_ The last time injection was applicable.
    /// @return The interest contribution from the injection rate. [PREC]
    function getInterestByInjection(
        State storage self,
        uint256 lastUpdateTime_,
        uint256 lastTimeInjectionApplicable_
    ) internal view returns (uint256) {
        if (lastTimeInjectionApplicable_ <= lastUpdateTime_) {
            return 0;
        }
        // [PREC] = [PREC] * ([N] - [N])
        return self.borrowInjectionRate * (lastTimeInjectionApplicable_ - lastUpdateTime_);
    }

    /// @notice Calculate the borrow interest based on the current utilization of the pool.
    /// @dev The interest rate model is a piecewise linear function with a kink.
    /// It makes borrowing more expensive above the kink point and cheaper below it.
    /// @param self The lending pool state.
    /// @param liquidity_ The current liquidity of the pool.
    /// @param pCU_ The current price of the credit unit.
    /// @param lastUpdateTime_ The last time the interest was accrued.
    /// @return The borrow interest regarding utilization. [PREC]
    function getInterestByUtilization(
        State storage self,
        uint256 liquidity_,
        uint256 pCU_,
        uint256 lastUpdateTime_
    ) internal view returns (uint256) {
        uint256 uRate = self.getUtilizationRate(liquidity_, pCU_);
        uint256 deltaTime = block.timestamp - lastUpdateTime_;

        if (uRate <= self.uKinkPoint) {
            // [PREC] = ([PREC] * [PREC] * [N]) / [PREC]
            return (self.uSoftSlope * uRate * deltaTime) / (self.uKinkPoint);
        }
        // [PREC²] = ([PREC] - [PREC]) * ([PREC] - [PREC])
        uint256 num = (uRate - self.uKinkPoint) * (self.uMaxSlope - self.uSoftSlope);
        // [PREC] = [PREC] - [PREC]
        uint256 denom = C.ONE - self.uKinkPoint;
        // [PREC] = [PREC] * [N] + ([PREC²] * [N]) / [PREC])
        return self.uSoftSlope * deltaTime + ((num * deltaTime) / denom);
    }

    /// @notice Calculate the utilization of the pool (pure version).
    /// @dev Utilization is defined as: total borrows / (total borrows + total liquidity)
    /// @param creditSupply_ The total credit supply (in credit units).
    /// @param liquidity_ The total liquidity available in the pool (in TP tokens).
    /// @param pCU_ The price of the credit unit. [PREC]
    /// @return utilization The utilization. [PREC]
    function calculateUtilizationRate(
        uint256 creditSupply_,
        uint256 liquidity_,
        uint256 pCU_
    ) internal pure returns (uint256) {
        // [PREC] = [N] * [PREC]
        uint256 borrows = creditSupply_ * pCU_;
        // utilization rate is 0 when there are no borrows
        if (borrows == 0) {
            return 0;
        }
        // [PREC] = [PREC²] / ([PREC] + [PREC])
        return borrows.addPrec() / (liquidity_.addPrec() + borrows);
    }

    /// @notice Calculate the utilization of the pool.
    /// @dev Utilization is defined as: total borrows / (total borrows + total liquidity)
    /// @param self The lending pool state.
    /// @param liquidity_ The current liquidity of the pool.
    /// @param pCU_ The current price of the credit unit.
    /// @return utilization The utilization. [PREC]
    function getUtilizationRate(State storage self, uint256 liquidity_, uint256 pCU_) internal view returns (uint256) {
        return calculateUtilizationRate(self.creditSupply, liquidity_, pCU_);
    }

    /// @notice Calculate the brake factor based on the emission rate (pure version).
    /// @dev The brake factor is used to reduce the interest rate when the emission rate is high.
    /// It is 1 when the emission rate is below the first kink, decreases linearly to 0 at the second kink,
    /// and is 0 when the emission rate is above the second kink.
    /// @param emissionRate_ The emission rate for minting new TP tokens. [PREC]
    /// @param brakeFirstKink_ TP emission rate at which the first brake occurs. [PREC]
    /// @param brakeSecondKink_ TP emission rate at which the second brake occurs. [PREC]
    /// @return The brake factor. [PREC]
    function calculateBrakeFactor(
        uint256 emissionRate_,
        uint256 brakeFirstKink_,
        uint256 brakeSecondKink_
    ) internal pure returns (uint256) {
        if (emissionRate_ <= brakeFirstKink_) {
            return C.ONE;
        } else if (emissionRate_ < brakeSecondKink_) {
            // [PREC] = [PREC] - (([PREC] - [PREC]) * [PREC] / ([PREC] - [PREC]))
            return C.ONE - (emissionRate_ - brakeFirstKink_).divPrec(brakeSecondKink_ - brakeFirstKink_);
        } else {
            return 0;
        }
    }

    /// @notice Calculate the brake factor based on the emission rate.
    /// @dev The brake factor is used to reduce the interest rate when the emission rate is high.
    /// It is 1 when the emission rate is below the first kink, decreases linearly to 0 at the second kink,
    /// and is 0 when the emission rate is above the second kink.
    /// @param self The lending pool state.
    /// @param emissionRate_ The emission rate for minting new TP tokens (provided by the manager). [PREC]
    /// @return The brake factor. [PREC]
    function getBrakeFactor(State storage self, uint256 emissionRate_) internal view returns (uint256) {
        return calculateBrakeFactor(emissionRate_, self.brakeFirstKink, self.brakeSecondKink);
    }

    /// @notice Calculate the inject rate for TP tokens from the TP minter.
    /// @param self The lending pool state.
    /// @param emissionRate_ The emission rate for minting new TP tokens (provided by the manager). [PREC]
    /// @return The inject rate for TP tokens. [PREC]
    function getTPInjectRate(State storage self, uint256 emissionRate_) internal view returns (uint256) {
        uint256 liq = self.liquidityFresh();
        // [PREC²] = [PREC] * [PREC] * [N]
        uint256 num = self.injectionBaseFactor * self.getBrakeFactor(emissionRate_) * liq;
        // [PREC] = [N] * [PREC] + [N] * [PREC]
        uint256 den = liq.addPrec() + self.creditSupply * self.priceCreditUnit();
        // [PREC] = [PREC²] / [PREC]
        return num / den;
    }

    /// @notice Perform the TP token injection process if the required time has passed.
    /// @dev Updates the next injection time and pending injection amount.
    /// @param self The lending pool state.
    /// @return tpInjected The amount of TP tokens injected into the pool.
    function tpInjection(State storage self) internal returns (uint256 tpInjected) {
        if (block.timestamp < self.nextInjectionTime) revert MissingTimeToInject();
        self.accrueInterest();

        uint256 tpBalanceBefore = self.tpToken.balanceOf(address(this));
        self.tpInjector.injectTP();
        tpInjected = self.tpToken.balanceOf(address(this)) - tpBalanceBefore;

        uint256 availableCash = self.getAvailableCash();
        // Safety check to prevent disproportionately large deposits when pool liquidity is extremely low.
        // In such low-liquidity scenarios (near the wei range), a large deposit could distort the pool
        // math and artificially inflate the deposit unit price
        if (tpInjected > availableCash) revert ExcessiveTPInjection();

        // [PREC] = [N] * [PREC] / [N]
        self.injectionRate = tpInjected.divPrec(self.injectionTimeSpan);
        // [PREC] = [N] * [PREC] / ([N] * [N])
        self.borrowInjectionRate = tpInjected.divPrec(availableCash * self.injectionTimeSpan);
        self.nextInjectionTime = block.timestamp + self.injectionTimeSpan;
        return tpInjected;
    }

    /// @notice Get the available cash in the pool.
    /// @dev The available cash is calculated as: liquidity + (creditSupply * pCU) - lastFeeAccrued
    /// @param self The lending pool state.
    /// @return The available cash in the pool. (in TP tokens)
    function getAvailableCash(State storage self) internal view returns (uint256) {
        uint256 liquidity = self.liquidity;
        uint256 pCU = self.lastPCU;
        uint256 fee = self.lastFeeAccrued;
        uint256 lastUpdateTime = self.lastUpdateTime;
        if (block.timestamp > lastUpdateTime) {
            uint256 lastTimeInjectionApplicable = self.getLastTimeInjectionApplicable();
            uint256 deltaPCU = self.getDeltaPCU(liquidity, pCU, lastUpdateTime, lastTimeInjectionApplicable);
            pCU += deltaPCU;
            liquidity += self.getDeltaLiquidity(lastUpdateTime, lastTimeInjectionApplicable);
            fee += self.getDeltaFee(deltaPCU);
        }
        // [N] = [N] + ([N] * [PREC] / [PREC]) - [N]
        return liquidity + self.creditSupply.mulPrec(pCU) - fee;
    }

    /// @notice Get the last time the injection is applicable.
    /// @dev This is the minimum between the current block timestamp and the next injection time.
    /// @param self The lending pool state.
    /// @return The last time the injection is applicable.
    function getLastTimeInjectionApplicable(State storage self) internal view returns (uint256) {
        return Math.min(block.timestamp, self.nextInjectionTime);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import { MocLendingQueue } from "./MocLendingQueue.sol";
import { MocLendingPool as Pool } from "./lib/MocLendingPool.sol";
import { FixedPoint } from "./lib/FixedPoint.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Coin } from "./lib/Coin.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title MocLendingManager
 * @author Money On Chain
 * @notice Main contract for managing lending and borrowing operations in the MoC protocol
 */
contract MocLendingManager is MocLendingQueue {
    using Pool for Pool.State;
    using SafeERC20 for IERC20;
    using Coin for IERC20;
    using FixedPoint for uint256;

    // -----------------
    // Custom Errors
    // -----------------

    /// @notice Thrown when a function meant to be called only by this contract is called by another address
    error OnlySelf();

    /// @notice Thrown when the TP token is not valid in the MoC system
    error InvalidTPToken();

    /// @notice Thrown when trying to operate with a pool that has not been initialized
    error PoolNotInitialized();

    /// @notice Thrown when trying to open a new vault on a liquidated bucket
    error LiquidatedBucketNewVault();

    // -----------------
    // Events
    // -----------------

    /// @notice Emitted when a user deposits TP tokens into the lending pool
    /// @param user The address of the user depositing
    /// @param recipient The address receiving the deposit units
    /// @param tpToken The TP token address
    /// @param tpAmount The amount of TP tokens deposited
    /// @param depositUnits The amount of deposit units received
    event Deposit(
        address indexed user,
        address indexed recipient,
        address indexed tpToken,
        uint256 tpAmount,
        uint256 depositUnits
    );

    /// @notice Emitted when a user withdraws TP tokens from the lending pool
    /// @param user The address of the user withdrawing
    /// @param recipient The address receiving the TP tokens
    /// @param tpToken The TP token address
    /// @param depositUnits The amount of deposit units withdrawn
    /// @param tpAmount The amount of TP tokens received
    event Withdraw(
        address indexed user,
        address indexed recipient,
        address indexed tpToken,
        uint256 depositUnits,
        uint256 tpAmount
    );

    /// @notice Emitted when AC tokens are added to a vault as collateral
    /// @param user The address adding the collateral
    /// @param recipient The address whose vault receives the collateral
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param acAmount The amount of AC tokens added
    event AddACtoVault(
        address indexed user,
        address recipient,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 acAmount
    );

    /// @notice Emitted when AC tokens are removed from a vault
    /// @param user The address whose vault is being modified
    /// @param recipient The address receiving the AC tokens
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param acAmount The amount of AC tokens removed
    event RemoveACfromVault(
        address indexed user,
        address recipient,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 acAmount
    );

    /// @notice Emitted when a user borrows TP tokens
    /// @param user The address whose vault is used as collateral
    /// @param recipient The address receiving the TP tokens
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param tpAmount The amount of TP tokens borrowed
    /// @param creditUnits The amount of credit units issued
    event Borrow(
        address indexed user,
        address recipient,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 tpAmount,
        uint256 creditUnits
    );

    /// @notice Emitted when a user repays borrowed TP tokens
    /// @param user The address repaying
    /// @param recipient The address whose debt is being repaid
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param creditUnits The amount of credit units repaid
    /// @param tpAmount The amount of TP tokens repaid
    /// @param tpToFeeFlow The amount of TP tokens sent to fee flow
    event Repay(
        address indexed user,
        address recipient,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 creditUnits,
        uint256 tpAmount,
        uint256 tpToFeeFlow
    );

    /// @notice Emitted when a user repays borrowed TP tokens using AC from their vault
    /// @param user The address repaying
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param creditUnits The amount of credit units repaid
    /// @param acSold The amount of AC tokens sold
    /// @param tpAmount The amount of TP tokens repaid
    /// @param tpToFeeFlow The amount of TP tokens sent to fee flow
    event RepayWithAC(
        address indexed user,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 creditUnits,
        uint256 acSold,
        uint256 tpAmount,
        uint256 tpToFeeFlow
    );

    /// @notice Emitted when a vault is liquidated
    /// @param liquidator The address initiating the liquidation
    /// @param user The address being liquidated
    /// @param tpToken The TP token address
    /// @param mocBucket The Moc Bucket address
    /// @param acSwapped The amount of AC swapped in this step
    /// @param tpPaid The actual TP amount paid
    /// @param tpToFeeFlow The amount of TP tokens sent to fee flow
    /// @param isComplete Whether the liquidation is now complete
    event Liquidate(
        address liquidator,
        address indexed user,
        address indexed tpToken,
        address indexed mocBucket,
        uint256 acSwapped,
        uint256 tpPaid,
        uint256 tpToFeeFlow,
        bool isComplete
    );

    /// @notice Emitted when TP tokens are injected into the lending pool
    /// @param tpToken The TP token address
    /// @param tpAmount The amount of TP tokens injected
    event TPInjection(address indexed tpToken, uint256 tpAmount);

    // -----------------
    // Modifiers
    // -----------------

    /// @notice Modifier to validate that a pool exists before executing a function
    /// @param tpToken_ The TP token address to check
    modifier poolExists(address tpToken_) {
        _poolExists(tpToken_);
        _;
    }

    /// @notice Internal function to validate that a pool exists
    /// @param tpToken_ The TP token address to check
    function _poolExists(address tpToken_) internal view {
        if (address(_pools[tpToken_].tpToken) == address(0)) revert PoolNotInitialized();
    }

    // -----------------
    // Storage
    // -----------------

    /// @notice Mapping from TP token address to its lending pool state
    mapping(address tpToken => Pool.State) internal _pools;
    /// @notice List of all TP tokens with initialized pools
    address[] public poolsList;
    /// @notice Maximum slippage allowed for swaps (1e18 = 100%, 0.01e18 = 1%)
    uint256 public maxSlippage;
    /// @notice Mapping of Moc Bucket and TP token to MoC fee flow address
    mapping(address mocBucket => mapping(address tpToken => address)) public mocFeeFlow;
    /// @notice Mapping of Moc Bucket and TP token to MoC Swapper Core contract
    mapping(address mocBucket => mapping(address tpToken => address)) public mocSwapperCore;
    /// @notice Mapping of Moc Bucket and TP token to MoC Swapper Exchange contract
    mapping(address mocBucket => mapping(address tpToken => address)) public mocSwapperExchange;

    /// @notice Constructor to disable initializers for the implementation contract
    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the contract
    /// @param governor_ The address of the governor contract
    /// @param pauser_ The address of the pauser contract
    /// @param mocAdapter_ The address of the MoC adapter contract
    /// @param maxSlippage_ The maximum slippage allowed for swaps (1e18 = 100%, 0.03e18 = 3%)
    /// @param initializeQueueParams_ The parameters for initializing the queue
    function initialize(
        address governor_,
        address pauser_,
        address mocAdapter_,
        uint256 maxSlippage_,
        InitializeQueueParams calldata initializeQueueParams_
    ) external initializer {
        maxSlippage = maxSlippage_;
        __MocLendingQueue_init({
            governor_: governor_,
            pauser_: pauser_,
            mocAdapter_: mocAdapter_,
            initializeQueueParams_: initializeQueueParams_
        });
    }

    /// @notice Create and initialize a new lending pool for a given TP token
    /// @param tpToken_ The TP token used in the lending pool.
    /// @param tpInjector_ TP Injector contract to inject TP tokens to the pool.
    /// @param minCoverage_ Minimum coverage ratio required for a vault. [PREC]
    /// @param liquidationCoverage_ Coverage threshold to liquidate a vault. [PREC]
    /// @param borrowFee_ Borrow fee taken from the interest paid by borrowers. [PREC]
    /// @param uKinkPoint_ Utilization rate at which the kink occurs. [PREC]
    /// @param uSoftSlope_ Slope of the interest rate model when utilization is below the kink point. [PREC]
    /// @param uMaxSlope_ Slope of the interest rate model when utilization is above the kink point. [PREC]
    /// @param injectionTimeSpan_ Time span to inject TP tokens.
    /// @param injectionBaseFactor_ Injection base factor used for calculating TP injection. [PREC]
    /// @param brakeFirstKink_ TP emission rate at which the first brake occurs. [PREC]
    /// @param brakeSecondKink_ TP emission rate at which the second brake occurs. [PREC]
    function initializePool(
        address tpToken_,
        address tpInjector_,
        uint256 minCoverage_,
        uint256 liquidationCoverage_,
        uint256 borrowFee_,
        uint256 uKinkPoint_,
        uint256 uSoftSlope_,
        uint256 uMaxSlope_,
        uint256 injectionTimeSpan_,
        uint256 injectionBaseFactor_,
        uint256 brakeFirstKink_,
        uint256 brakeSecondKink_
    ) external onlyAuthorizedChanger {
        if (!mocAdapter.isValidTP(tpToken_)) revert InvalidTPToken();
        Pool.State storage pool = _pools[tpToken_];
        pool.initialize(
            tpToken_,
            tpInjector_,
            minCoverage_,
            liquidationCoverage_,
            borrowFee_,
            uKinkPoint_,
            uSoftSlope_,
            uMaxSlope_,
            injectionTimeSpan_,
            injectionBaseFactor_,
            brakeFirstKink_,
            brakeSecondKink_
        );
        poolsList.push(tpToken_);
    }

    /// @notice Sets the maximum slippage allowed for swaps
    /// @param maxSlippage_ The new maximum slippage (1e18 = 100%, 0.01e18 = 1%)
    function setMaxSlippage(uint256 maxSlippage_) external onlyAuthorizedChanger {
        maxSlippage = maxSlippage_;
    }

    /// @notice Sets the MoC fee flow address for a given Moc Bucket and TP token
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @param feeFlow_ The new fee flow address
    function setMocFeeFlow(address mocBucket_, address tpToken_, address feeFlow_) external onlyAuthorizedChanger {
        mocFeeFlow[mocBucket_][tpToken_] = feeFlow_;
    }

    /// @notice Sets the MoC Swapper Core contract for a given Moc Bucket and TP token
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @param swapperCore_ The new Swapper Core address
    function setMocSwapperCore(
        address mocBucket_,
        address tpToken_,
        address swapperCore_
    ) external onlyAuthorizedChanger {
        mocSwapperCore[mocBucket_][tpToken_] = swapperCore_;
    }

    /// @notice Sets the MoC Swapper Exchange contract for a given Moc Bucket and TP token
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @param swapperExchange_ The new Swapper Exchange address
    function setMocSwapperExchange(
        address mocBucket_,
        address tpToken_,
        address swapperExchange_
    ) external onlyAuthorizedChanger {
        mocSwapperExchange[mocBucket_][tpToken_] = swapperExchange_;
    }

    // -----------------
    // Pool Parameter Setters
    // -----------------

    /// @notice Set minimum coverage for a pool
    /// @param tpToken_ The TP token address
    /// @param minCoverage_ The new minimum coverage value [PREC]
    function setPoolMinCoverage(address tpToken_, uint256 minCoverage_) external onlyAuthorizedChanger {
        _pools[tpToken_].minCoverage = minCoverage_;
    }

    /// @notice Set liquidation coverage for a pool
    /// @param tpToken_ The TP token address
    /// @param liquidationCoverage_ The new liquidation coverage value [PREC]
    function setPoolLiquidationCoverage(address tpToken_, uint256 liquidationCoverage_) external onlyAuthorizedChanger {
        _pools[tpToken_].liquidationCoverage = liquidationCoverage_;
    }

    /// @notice Set borrow fee for a pool
