    /// @notice Internal function to get and validate AC/TP price and AC token
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @return pACtp The validated AC/TP price [PREC]
    /// @return acToken The validated AC token address
    function _validateAndGetPACtp(address mocBucket_, address tpToken_) internal view returns (uint256, address) {
        // reverts if mocBucket or price are invalid
        return mocAdapter.validateAndGetPACtp(mocBucket_, tpToken_);
    }

    /// @notice Internal helper: validates a bucket/TP pair and returns price, AC token, and liquidation status
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @return pACtp The current price of the TP token in AC
    /// @return acToken The address of the AC token
    /// @return isLiquidated True if the bucket has been liquidated
    function _validateAndGetPACtpAndLiquidated(
        address mocBucket_,
        address tpToken_
    ) internal view returns (uint256 pACtp, address acToken, bool isLiquidated) {
        return mocAdapter.validateAndGetPACtpAndLiquidated(mocBucket_, tpToken_);
    }

    /// @notice Internal function to transfer fees to the fee flow address
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @param tpToFeeFlow The amount of TP tokens to transfer to the fee flow
    function _transferFees(address mocBucket_, address tpToken_, uint256 tpToFeeFlow) internal {
        address feeFlow = mocFeeFlow[mocBucket_][tpToken_];
        if (feeFlow != address(0) && tpToFeeFlow > 0) {
            IERC20(tpToken_).safeTransfer(feeFlow, tpToFeeFlow);
        }
    }

    /// @notice Deposit TP tokens into the lending pool.
    /// @param recipient_ the address that will receive the deposit units
    /// @param tpToken_ the address of the TP token to deposit
    /// @param tpAmount_ the amount of TP tokens to deposit
    function deposit(address recipient_, address tpToken_, uint256 tpAmount_) external notPaused poolExists(tpToken_) {
        Pool.State storage pool = _pools[tpToken_];
        uint256 depositUnits = pool.deposit(recipient_, tpAmount_);

        // transfer TP tokens from the depositor to this pool manager
        IERC20(tpToken_).safeTransferFrom(msg.sender, address(this), tpAmount_);

        emit Deposit(msg.sender, recipient_, tpToken_, tpAmount_, depositUnits);
    }

    /// @notice Withdraw TP tokens from the lending pool.
    /// @param recipient_ the address that will receive the TP tokens
    /// @param tpToken_ the address of the TP token to withdraw
    /// @param depositUnits_ the amount of deposit units to withdraw
    function withdraw(
        address recipient_,
        address tpToken_,
        uint256 depositUnits_
    ) external notPaused poolExists(tpToken_) {
        Pool.State storage pool = _pools[tpToken_];
        uint256 tpToWithdraw = pool.withdraw(msg.sender, depositUnits_);
        // transfer TP tokens from this pool manager to the recipient
        IERC20(tpToken_).safeTransfer(recipient_, tpToWithdraw);

        emit Withdraw(msg.sender, recipient_, tpToken_, depositUnits_, tpToWithdraw);
    }

    /// @notice Add AC tokens to the recipient's vault as collateral.
    /// @dev For ERC20, the sender must approve this contract to transfer the AC tokens before calling this function.
    /// For coinbase (address(0)), the sender must send the exact amount of coinbase as msg.value.
    /// @param recipient_ The address whose vault will receive the AC tokens
    /// @param tpToken_ The TP token associated with the lending pool.
    /// @param mocBucket_ The Moc Bucket which use the AC token to be added as collateral.
    /// @param acAmount_ The amount of AC tokens to add to the vault. (should match msg.value if acToken_ is coinbase)
    function addACtoVault(
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 acAmount_
    ) external payable notPaused poolExists(tpToken_) {
        // bucket token must be part of the MoC system, reverts if invalid.
        // isLiquidated is true when the bucket has been liquidated
        (address acToken, bool isLiquidated) = mocAdapter.validateAndGetACToken(mocBucket_);

        IERC20(acToken).coinVerifyValue(acAmount_);

        Pool.State storage pool = _pools[tpToken_];

        // If the bucket is liquidated, only allow operations on existing vaults
        // (with AC balance or outstanding debt) to let users pay down debt or add collateral.
        // Prevent opening brand-new vaults on liquidated buckets.
        if (
            isLiquidated &&
            pool.vaultACBalance[recipient_][mocBucket_] == 0 &&
            pool.vaultCreditBalance[recipient_][mocBucket_] == 0
        ) revert LiquidatedBucketNewVault();

        pool.addACtoVault(recipient_, mocBucket_, acAmount_);

        // transfer AC tokens from the sender to this pool manager
        IERC20(acToken).coinTransferFrom(msg.sender, address(this), acAmount_);

        emit AddACtoVault(msg.sender, recipient_, tpToken_, mocBucket_, acAmount_);
    }

    /// @notice Remove AC tokens from the recipient's vault.
    /// @dev The recipient must maintain the minimum coverage ratio after removing the AC tokens.
    /// @param recipient_ The address whose vault will have AC tokens removed
    /// @param tpToken_ The TP token associated with the lending pool.
    /// @param mocBucket_ The Moc Bucket which uses the AC token to remove from the vault.
    /// @param acAmount_ The amount of AC tokens to remove from the vault.
    /// @return operId The operation ID if queued, 0 if executed immediately
    function removeACfromVault(
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 acAmount_
    ) external payable notPaused nonReentrant poolExists(tpToken_) returns (uint256 operId) {
        if (useQueue) {
            return _queueOperation(OperType.REMOVE_AC_FROM_VAULT, recipient_, tpToken_, mocBucket_, acAmount_);
        } else {
            _executeRemoveACfromVault(msg.sender, recipient_, tpToken_, mocBucket_, acAmount_);
            return 0;
        }
    }

    /// @notice Internal function to execute removeACfromVault
    /// @param user_ The address whose vault will have AC tokens removed
    /// @param recipient_ The address who will receive the AC tokens
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @param acAmount_ The amount of AC tokens to remove
    function _executeRemoveACfromVault(
        address user_,
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 acAmount_
    ) internal {
        // reverts if AC token is invalid or price is invalid
        (uint256 pACtp, address acToken) = _validateAndGetPACtp(mocBucket_, tpToken_);
        Pool.State storage pool = _pools[tpToken_];

        pool.removeACfromVault(user_, mocBucket_, acAmount_, pACtp, pool.minCoverage);
        // transfer AC tokens from this pool manager to the recipient
        IERC20(acToken).coinTransfer(recipient_, acAmount_);

        emit RemoveACfromVault(user_, recipient_, tpToken_, mocBucket_, acAmount_);
    }

    /// @notice Borrow TP tokens from the lending pool using AC tokens as collateral.
    /// @dev The recipient must have the AC tokens in their vault and maintain the
    /// minimum coverage ratio after borrowing.
    /// @param recipient_ The address whose vault will be used and who will receive the TP tokens
    /// @param tpToken_ The TP token to borrow.
    /// @param mocBucket_ The Moc Bucket which uses the AC token as collateral.
    /// @param tpAmount_ The amount of TP tokens to borrow.
    /// @return operId The operation ID if queued, 0 if executed immediately
    function borrow(
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 tpAmount_
    ) external payable notPaused poolExists(tpToken_) returns (uint256 operId) {
        if (useQueue) {
            return _queueOperation(OperType.BORROW, recipient_, tpToken_, mocBucket_, tpAmount_);
        } else {
            _executeBorrow(msg.sender, recipient_, tpToken_, mocBucket_, tpAmount_);
            return 0;
        }
    }

    /// @notice Internal function to execute borrow
    /// @param user_ The address whose vault will be used as collateral
    /// @param recipient_ The address who will receive the TP tokens
    /// @param tpToken_ The TP token to borrow
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpAmount_ The amount of TP tokens to borrow
    function _executeBorrow(
        address user_,
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 tpAmount_
    ) internal {
        // Fetch price and liquidation status in one adapter call.
        // Reject new borrows against a liquidated bucket
        // Once a bucket is liquidated, existing vaults are limited to deleveraging (repay /
        // removeAC). Creating new debt against a liquidated bucket is not allowed.
        (uint256 pACtp, , bool isLiquidated) = _validateAndGetPACtpAndLiquidated(mocBucket_, tpToken_);
        if (isLiquidated) revert LiquidatedBucketNewVault();

        Pool.State storage pool = _pools[tpToken_];

        uint256 creditUnits = pool.borrow(user_, mocBucket_, tpAmount_, pACtp);

        // transfer TP tokens from this pool manager to the recipient
        IERC20(tpToken_).safeTransfer(recipient_, tpAmount_);

        emit Borrow(user_, recipient_, tpToken_, mocBucket_, tpAmount_, creditUnits);
    }

    /// @notice Repay borrowed TP tokens to the lending pool.
    /// @dev The sender must approve this contract to transfer the TP tokens before calling this function.
    /// @param recipient_ The address whose debt will be repaid
    /// @param tpToken_ The TP token to repay.
    /// @param mocBucket_ The Moc Bucket which uses the AC token as collateral.
    /// @param creditUnits_ The amount of credit units to repay.
    function repay(
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 creditUnits_
    ) external notPaused poolExists(tpToken_) {
        Pool.State storage pool = _pools[tpToken_];
        (uint256 totalTPtoRepay, uint256 tpToFeeFlow) = pool.repay(recipient_, mocBucket_, creditUnits_);

        // transfer TP tokens from the payer to this pool manager
        IERC20(tpToken_).safeTransferFrom(msg.sender, address(this), totalTPtoRepay);

        // transfer TP tokens from this pool manager to the MocFeeFlow
        _transferFees(mocBucket_, tpToken_, tpToFeeFlow);

        emit Repay(msg.sender, recipient_, tpToken_, mocBucket_, creditUnits_, totalTPtoRepay, tpToFeeFlow);
    }

    /// @notice Repay borrowed TP tokens to the lending pool using AC tokens from the sender's vault.
    /// @dev The sender must have enough AC tokens in their vault to cover the repayment and fees.
    /// Only the msg.sender can repay their own debt using their own AC tokens.
    /// @param tpToken_ The TP token to repay.
    /// @param mocBucket_ The Moc Bucket which uses the AC token as collateral.
    /// @param creditUnits_ The amount of credit units to repay.
    /// @return operId The operation ID if queued, 0 if executed immediately
    function repayWithAC(
        address tpToken_,
        address mocBucket_,
        uint256 creditUnits_
    ) external payable notPaused poolExists(tpToken_) returns (uint256 operId) {
        if (useQueue) {
            return _queueOperation(OperType.REPAY_WITH_AC, msg.sender, tpToken_, mocBucket_, creditUnits_);
        } else {
            _executeRepayWithAC(msg.sender, tpToken_, mocBucket_, creditUnits_);
            return 0;
        }
    }

    /// @notice Internal function to execute repayWithAC
    /// @param user_ The address of the user repaying
    /// @param tpToken_ The TP token to repay
    /// @param mocBucket_ The Moc Bucket address
    /// @param creditUnits_ The amount of credit units to repay
    function _executeRepayWithAC(address user_, address tpToken_, address mocBucket_, uint256 creditUnits_) internal {
        // reverts if AC token is invalid or price is invalid
        (uint256 pACtp, address acToken) = _validateAndGetPACtp(mocBucket_, tpToken_);

        Pool.State storage pool = _pools[tpToken_];

        // Calculate TP needed for the repay (this also accrues interest)
        uint256 tpNeeded = pool.calculateTPforRepay(user_, mocBucket_, creditUnits_);

        // Swap AC for TP using both swappers if needed (Core first, then Exchange)
        (uint256 acSold, uint256 tpBought) = IERC20(acToken).swapTwoStepsExactOutput(
            mocSwapperCore[mocBucket_][tpToken_],
            mocSwapperExchange[mocBucket_][tpToken_],
            tpToken_,
            address(this),
            tpNeeded,
            pACtp.mulPrec(ONE - maxSlippage),
            true // revert if swaps fail
        );

        uint256 actualCreditUnitsToRepay = creditUnits_;
        // Calculate how many credit units this TP amount represents, if we bought less than needed
        if (tpBought < tpNeeded) {
            // [N] = [N] * [PREC] / [PREC]
            actualCreditUnitsToRepay = tpBought.divPrec(pool.lastPCU);
        }

        // Now do the actual repay with the TPs we obtained
        (uint256 totalTPtoRepay, uint256 tpToFeeFlow) = pool.repay(user_, mocBucket_, actualCreditUnitsToRepay);

        // Use liquidationCoverage instead of minCoverage since user is reducing debt
        pool.removeACfromVault(user_, mocBucket_, acSold, pACtp, pool.liquidationCoverage);
        // transfer TP tokens from this pool manager to the MocFeeFlow
        _transferFees(mocBucket_, tpToken_, tpToFeeFlow);
        // transfer the surplus TP tokens (if any) back to the user
        if (tpBought > totalTPtoRepay) {
            IERC20(tpToken_).safeTransfer(user_, tpBought - totalTPtoRepay);
        }
        emit RepayWithAC(user_, tpToken_, mocBucket_, actualCreditUnitsToRepay, acSold, totalTPtoRepay, tpToFeeFlow);
    }

    /// @notice Trigger TP injection for a lending pool
    /// @dev This function can be called by anyone to inject TP tokens into the pool if enough time has passed
    /// since the last injection. The injection increases pool liquidity and affects interest rates.
    /// @param tpToken_ The TP token associated with the lending pool
    function triggerTPInjection(address tpToken_) external notPaused poolExists(tpToken_) {
        uint256 tpInjected = _pools[tpToken_].tpInjection();
        emit TPInjection(tpToken_, tpInjected);
    }

    /// @notice Liquidate an under-collateralized position.
    /// @dev This function can be called by anyone (including repeatedly) to liquidate a user's position.
    /// The liquidation uses AC tokens from the user's vault to swap for TP tokens to repay debt.
    /// Due to swap limits (maxACtoSwap), liquidation may require multiple transactions.
    /// The function tracks progress automatically and handles:
    /// - Partial swaps when maxACtoSwap limits are hit
    /// - Reserve pool usage when AC is insufficient to cover debt
    /// - Surplus TP returned to reserve pool
    /// @param user_ The address of the user to liquidate.
    /// @param tpToken_ The TP token associated with the lending pool.
    /// @param mocBucket_ The Moc Bucket which uses the AC token as collateral.
    function liquidate(address user_, address tpToken_, address mocBucket_) external notPaused poolExists(tpToken_) {
        (uint256 pACtp, address acToken) = _validateAndGetPACtp(mocBucket_, tpToken_);
        Pool.State storage pool = _pools[tpToken_];

        // Check if liquidation is needed and get AC in vault
        uint256 acInVault = pool.triggerLiquidation(user_, mocBucket_, pACtp);

        // Swap AC for TP using both swappers if needed (Core first, then Exchange)
        (uint256 acSwapped, uint256 tpObtained) = IERC20(acToken).swapTwoSteps(
            mocSwapperCore[mocBucket_][tpToken_],
            mocSwapperExchange[mocBucket_][tpToken_],
            tpToken_,
            address(this),
            acInVault,
            pACtp.mulPrec(ONE - maxSlippage),
            true // revert if swaps fail
        );

        // Process liquidation step
        (uint256 tpToFeeFlow, bool isComplete) = pool.liquidate(user_, mocBucket_, acSwapped, tpObtained);

        // Transfer TP fees to MocFeeFlow if any
        _transferFees(mocBucket_, tpToken_, tpToFeeFlow);

        // Emit liquidation event
        emit Liquidate(msg.sender, user_, tpToken_, mocBucket_, acSwapped, tpObtained, tpToFeeFlow, isComplete);
    }

