    /// @notice Get the last update time
    /// @param tpToken_ The TP token address
    /// @return lastUpdateTime The last update timestamp
    function getLastUpdateTime(address tpToken_) external view returns (uint256) {
        return _pools[tpToken_].lastUpdateTime;
    }

    /// @notice Get the change in price of credit unit since last update
    /// @dev Returns deltaPCU which includes both utilization and injection interest
    /// @param tpToken_ The TP token address
    /// @return deltaPCU The change in PCU [PREC]
    function getDeltaPCU(address tpToken_) external view returns (uint256) {
        Pool.State storage pool = _pools[tpToken_];
        uint256 lastTimeInjectionApplicable = Math.min(block.timestamp, pool.nextInjectionTime);
        return pool.getDeltaPCU(pool.liquidity, pool.lastPCU, pool.lastUpdateTime, lastTimeInjectionApplicable);
    }

    // ============ Liquidation State Functions ============

    /// @notice Check if a vault is currently being liquidated
    /// @param user_ The user address
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return isLiquidating True if vault is in liquidation process
    function isVaultLiquidating(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (bool isLiquidating) {
        return _pools[tpToken_].isLiquidating[user_][mocBucket_];
    }

    // ============ Queue Management Functions ============

    /// @notice Internal function to execute a queued operation (implements abstract function)
    /// @param operation_ The operation to execute
    /// @param operId_ The operation ID
    function _executeOper(QueuedOperation memory operation_, uint256 operId_) internal override {
        // solhint-disable-next-line no-empty-blocks
        try this.executeOper(operation_) {} catch (bytes memory returnData) {
            emit OperationError(operId_, returnData);
        }
    }

    /// @notice External function callable only by this contract to execute operation logic
    /// @param operation_ The operation to execute
    function executeOper(QueuedOperation calldata operation_) external {
        if (msg.sender != address(this)) revert OnlySelf();

        if (operation_.operType == OperType.BORROW) {
            // user's vault is used as collateral, recipient receives the TP tokens
            _executeBorrow(
                operation_.user,
                operation_.recipient,
                operation_.tpToken,
                operation_.mocBucket,
                operation_.amount
            );
        } else if (operation_.operType == OperType.REMOVE_AC_FROM_VAULT) {
            // user's vault is modified, recipient receives the AC tokens
            _executeRemoveACfromVault(
                operation_.user,
                operation_.recipient,
                operation_.tpToken,
                operation_.mocBucket,
                operation_.amount
            );
        } else if (operation_.operType == OperType.REPAY_WITH_AC) {
            // user repays their own debt using their own AC (no recipient differentiation)
            _executeRepayWithAC(operation_.user, operation_.tpToken, operation_.mocBucket, operation_.amount);
        }
    }

    /// @notice Allows the contract to receive coinbase for refunds when swapping
    receive() external payable {
        // Accept coinbase for refunds when swapping
    }

    /// @dev This empty reserved space is put in place to allow future versions to add new
    /// variables without shifting down storage in the inheritance chain.
    /// See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps

    // Purposely left unused to save some state space to allow for future upgrades
    // slither-disable-next-line unused-state
    uint256[50] private _gap;
}

