pragma solidity 0.8.24;

import { MocUpgradable } from "@moc/moc-main/contracts/governance/MocUpgradable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import { IMocAdapter } from "./interfaces/IMocAdapter.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Coin } from "./lib/Coin.sol";

/**
 * @title MocLendingQueue
 * @author Money On Chain
 * @notice Base contract for managing a FIFO queue of operations with gas payment mechanism
 */
abstract contract MocLendingQueue is MocUpgradable, ReentrancyGuardUpgradeable {
    using Coin for IERC20;

    // -----------------
    // Custom Errors
    // -----------------

    /// @notice Thrown when queue configuration is invalid
    error InvalidQueueConfig();
    /// @notice Thrown when execution fee is insufficient
    /// @param required The required fee amount
    /// @param provided The provided fee amount
    error InsufficientExecutionFee(uint256 required, uint256 provided);
    /// @notice Thrown when execution fee exceeds maximum
    /// @param required The required fee amount
    /// @param provided The provided fee amount
    error ExcessiveExecutionFee(uint256 required, uint256 provided);

    // -----------------
    // Events
    // -----------------

    /// @notice Emitted when an operation is queued
    /// @param operId The operation ID
    /// @param operType The type of operation
    /// @param user The user who initiated the operation
    /// @param recipient The recipient of the operation
    /// @param tpToken The TP token address
    /// @param mocBucket The MoC bucket address
    /// @param amount The amount involved in the operation
    event OperationQueued(
        uint256 indexed operId,
        OperType operType,
        address indexed user,
        address recipient,
        address indexed tpToken,
        address mocBucket,
        uint256 amount
    );
    /// @notice Emitted when an operation execution fails
    /// @param operId The operation ID
    /// @param reason The error data
    event OperationError(uint256 operId, bytes reason);
    /// @notice Emitted when an operation is executed
    /// @param executor The address that executed the operation
    /// @param operId The operation ID
    event OperationExecuted(address indexed executor, uint256 indexed operId);

    /// @notice Operation types for queued operations
    enum OperType {
        NONE,
        BORROW,
        REMOVE_AC_FROM_VAULT,
        REPAY_WITH_AC
    }

    /// @notice Structure for queued operations
    struct QueuedOperation {
        OperType operType;
        address user; // The user who initiated the operation (payer)
        address recipient; // The user who will receive the benefits/effects of the operation
        address tpToken;
        address mocBucket;
        uint256 amount; // tpAmount for BORROW, acAmount for REMOVE_AC, creditUnits for REPAY_WITH_AC
        uint256 queuedBlk;
    }

    /// @notice Parameters for initializing the queue
    struct InitializeQueueParams {
        bool useQueue;
        uint256 minOperWaitingBlk;
        uint256 maxOperWaitingBlk;
        uint256 maxOperationPerBatch;
        uint256 borrowExecCost;
        uint256 removeACExecCost;
        uint256 repayWithACExecCost;
    }

    // -----------------
    // Storage
    // -----------------

    /// @notice Contract to adapt requirements for the different MoC protocols
    IMocAdapter public mocAdapter;
    /// @notice If true, operations that consume pACtp will be queued and executed later.
    bool public useQueue;
    /// @notice Amount of Operations created
    uint256 public operIdCount;
    /// @notice First operation to be executed
    uint256 public firstOperId;
    /// @notice Min amount of blocks the Operation should wait in the Queue before execution
    uint256 public minOperWaitingBlk;
    /// @notice Max amount of blocks the Operation should wait in the Queue. Even if there is no price update
    /// it can be executed after this amount of blocks
    uint256 public maxOperWaitingBlk;
    /// @notice Maximum number of operations that can be executed in a single batch
    uint256 public maxOperationPerBatch;
    /// @notice Total coinbase held for paying execution fees
    uint256 public coinbaseForPayExecutions;
    /// @notice Gas costs for each operation type
    mapping(OperType => uint256) public execCost;
    /// @notice Mapping from operation ID to queued operation
    mapping(uint256 operId => QueuedOperation) public operations;

    /// @notice Initialize queue parameters
    /// @param governor_ The governor contract address
    /// @param pauser_ The pauser contract address
    /// @param mocAdapter_ The MoC adapter contract address
    /// @param initializeQueueParams_ The parameters for initializing the queue
    function __MocLendingQueue_init(
        address governor_,
        address pauser_,
        address mocAdapter_,
        InitializeQueueParams calldata initializeQueueParams_
    ) internal onlyInitializing {
        __MocUpgradable_init(governor_, pauser_);
        __ReentrancyGuard_init();
        mocAdapter = IMocAdapter(mocAdapter_);
        useQueue = initializeQueueParams_.useQueue;
        minOperWaitingBlk = initializeQueueParams_.minOperWaitingBlk;
        maxOperWaitingBlk = initializeQueueParams_.maxOperWaitingBlk;
        maxOperationPerBatch = initializeQueueParams_.maxOperationPerBatch;
        operIdCount = 1;
        firstOperId = 1;

        // Set gas costs for each operation type
        execCost[OperType.BORROW] = initializeQueueParams_.borrowExecCost;
        execCost[OperType.REMOVE_AC_FROM_VAULT] = initializeQueueParams_.removeACExecCost;
        execCost[OperType.REPAY_WITH_AC] = initializeQueueParams_.repayWithACExecCost;
    }

    /// @notice Set the MoC Adapter contract
    /// @param mocAdapter_ The new MoC adapter contract address
    function setMocAdapter(address mocAdapter_) external onlyAuthorizedChanger {
        mocAdapter = IMocAdapter(mocAdapter_);
    }

    /// @notice Configure the queue system
    /// @param useQueue_ Whether to enable the queue system
    /// @param minOperWaitingBlk_ Minimum blocks to wait before operation execution
    /// @param maxOperWaitingBlk_ Maximum blocks to wait before operation expires
    /// @param maxOperationPerBatch_ Maximum number of operations that can be executed in a single batch
    function configureQueue(
        bool useQueue_,
        uint256 minOperWaitingBlk_,
        uint256 maxOperWaitingBlk_,
        uint256 maxOperationPerBatch_
    ) external onlyAuthorizedChanger {
        if (maxOperWaitingBlk_ <= minOperWaitingBlk_) revert InvalidQueueConfig();

        useQueue = useQueue_;
        minOperWaitingBlk = minOperWaitingBlk_;
        maxOperWaitingBlk = maxOperWaitingBlk_;
        maxOperationPerBatch = maxOperationPerBatch_;
    }

    /// @notice Set the gas cost for a specific operation type
    /// @param operType_ The operation type
    /// @param execCost_ The gas cost for this operation type
    function setExecutionCost(OperType operType_, uint256 execCost_) external onlyAuthorizedChanger {
        execCost[operType_] = execCost_;
    }

    // ============ Queue Operation Functions ============

    /// @notice Queue an operation for later execution
    /// @param operType_ The type of operation
    /// @param recipient_ The address that will receive the benefits/effects of the operation
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @param amount_ The amount parameter (meaning depends on operation type)
    /// @return operId The operation ID
    function _queueOperation(
        OperType operType_,
        address recipient_,
        address tpToken_,
        address mocBucket_,
        uint256 amount_
    ) internal returns (uint256 operId) {
        // Calculate required gas payment
        uint256 gas = execCost[operType_];
        uint256 requiredPayment = gas * _getBaseFee();

        // Check if user sent enough coinbase to cover gas
        if (msg.value < requiredPayment) {
            revert InsufficientExecutionFee(requiredPayment, msg.value);
        }

        // If the value sent is 10x higher than network required, we assumed user error
        if (msg.value > requiredPayment * 10) {
            revert ExcessiveExecutionFee(requiredPayment, msg.value);
        }

        operId = operIdCount;

        operations[operId] = QueuedOperation({
            operType: operType_,
            user: msg.sender,
            recipient: recipient_,
            tpToken: tpToken_,
            mocBucket: mocBucket_,
            amount: amount_,
            queuedBlk: block.number
        });

        ++operIdCount;
        coinbaseForPayExecutions += msg.value;

        emit OperationQueued(operId, operType_, msg.sender, recipient_, tpToken_, mocBucket_, amount_);
        return operId;
    }

    /// @notice Execute multiple operations in FIFO order
    /// @param recipient_ Address to receive the gas payment
    function execute(address payable recipient_) external notPaused nonReentrant {
        uint256 currentOperId = firstOperId;
        uint256 lastOperId;
        uint256 limitBlk;
        uint256 totalExecutionFee;
        uint256 blocksSinceLastPublication = block.number - mocAdapter.getLastPublicationBlock();
        lastOperId = Math.min(operIdCount, currentOperId + maxOperationPerBatch);
        limitBlk = _getLastBlockToExecute(blocksSinceLastPublication, minOperWaitingBlk, maxOperWaitingBlk);

        // loop through all pending Operations
        while (currentOperId < lastOperId) {
            QueuedOperation memory operation = operations[currentOperId];
            // If current Operation has not met the waiting block criteria, we end the loop
            if (operation.queuedBlk > limitBlk) break;

            _executeOper(operation, currentOperId);
            emit OperationExecuted(msg.sender, currentOperId);
            delete operations[currentOperId];

            ++currentOperId;
            totalExecutionFee += execCost[operation.operType];
        }

        // Calculate total fee in wei (coinbase)
        totalExecutionFee = totalExecutionFee * _getBaseFee();
        // Limit payment to available balance (safety check)
        totalExecutionFee = Math.min(coinbaseForPayExecutions, totalExecutionFee);

        // Define new reference to queue beginning
        firstOperId = currentOperId;
        coinbaseForPayExecutions -= totalExecutionFee;
        // Send total gas payment to recipient
        Coin.COINBASE.coinTransfer(recipient_, totalExecutionFee);
    }

    /// @notice Internal function to execute a queued operation
    /// @param operation_ The operation to execute
    /// @param operId_ The operation ID
    function _executeOper(QueuedOperation memory operation_, uint256 operId_) internal virtual;

    /// @notice gets the last block in which the queued operations can be executed.
    /// Only operations enqueued before `blocksSinceLastPublication_` can be executed,
    /// but they must have been queued for at least `minOperWaitingBlk_` and at most `maxOperWaitingBlk_`
    /// @param blocksSinceLastPublication_ amount of blocks since last price publication
    /// @param minOperWaitingBlk_ min amount of blocks the operation should wait in the Queue before execution
    /// @param maxOperWaitingBlk_ max amount of blocks the operation should wait in the Queue before execution
    /// @return lastBlockToExecute last block to execute operations
    function _getLastBlockToExecute(
        uint256 blocksSinceLastPublication_,
        uint256 minOperWaitingBlk_,
        uint256 maxOperWaitingBlk_
    ) internal view returns (uint256 lastBlockToExecute) {
        uint256 qBlocksBefore;
        if (blocksSinceLastPublication_ >= maxOperWaitingBlk_) {
            qBlocksBefore = maxOperWaitingBlk_;
        } else {
            // when maxOperWaitingBlk_ < blocksSinceLastPublication_, this max is not necessary to calculate
            // because maxOperWaitingBlk_ is always > minOperWaitingBlk_ by parameter
            qBlocksBefore = Math.max(minOperWaitingBlk_, blocksSinceLastPublication_);
        }
        return block.number - qBlocksBefore;
    }

    /// @notice Internal function to get the current base fee
    /// @return The current block base fee
    function _getBaseFee() internal view virtual returns (uint256) {
        return block.basefee;
    }

    // ============ View Functions ============

    /// @notice Get the execution fee for a given operation type
    /// @param operType_ The operation type
    /// @return currentExecFee The current execution fee in coinbase
    function getExecFee(OperType operType_) public view returns (uint256 currentExecFee) {
        unchecked {
            currentExecFee = execCost[operType_] * _getBaseFee();
        }
    }

    /// @notice Get the number of pending operations
    /// @return count The number of pending operations
    function getPendingOperationsCount() external view returns (uint256 count) {
        return operIdCount - firstOperId;
    }

    /// @notice true if the queue is empty
    /// @return True if the queue is empty
    function isEmpty() public view returns (bool) {
        return firstOperId == operIdCount;
    }

    /// @notice true if the queue has at least one Operation ready to be executed
    /// @param blocksSinceLastPublication_ amount of blocks since last price publication
    /// @return True if there are operations ready to execute
    function readyToExecute(uint256 blocksSinceLastPublication_) external view returns (bool) {
        if (isEmpty()) return false;
        QueuedOperation memory operInfo = operations[firstOperId];
        return (operInfo.queuedBlk <=
            _getLastBlockToExecute(blocksSinceLastPublication_, minOperWaitingBlk, maxOperWaitingBlk));
    }

    /// @dev This empty reserved space is put in place to allow future versions to add new
    /// variables without shifting down storage in the inheritance chain.
    /// See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps

    // Purposely left unused to save some state space to allow for future upgrades
    // slither-disable-next-line unused-state
    uint256[50] private __gap;
}

