pragma solidity 0.8.24;

import { MocLendingManager } from "./MocLendingManager.sol";
import { MocLendingPool as Pool } from "./lib/MocLendingPool.sol";
import { IMocAdapter } from "./interfaces/IMocAdapter.sol";
import { C } from "./lib/Constants.sol";
import { FixedPoint } from "./lib/FixedPoint.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title MocLendingReader
/// @author Money On Chain
/// @notice Helper contract to read computed data from MocLendingManager
/// @dev This contract contains view functions that perform calculations to reduce the size of MocLendingManager
contract MocLendingReader {
    using Pool for Pool.State;
    using FixedPoint for uint256;

    /// @notice Reference to the MocLendingManager contract
    MocLendingManager public immutable LENDING_MANAGER;

    /// @notice Thrown when the AC / TP price is invalid
    error InvalidPrice();

    /// @notice Constructor
    /// @param lendingManager_ The address of the MocLendingManager contract
    constructor(address payable lendingManager_) {
        LENDING_MANAGER = MocLendingManager(lendingManager_);
    }

    /// @notice Internal function to get and validate AC/TP price
    /// @param mocBucket_ The Moc Bucket address
    /// @param tpToken_ The TP token address
    /// @return pACtp The validated AC/TP price [PREC]
    function _validateAndGetPACtp(address mocBucket_, address tpToken_) internal view returns (uint256 pACtp) {
        // reverts if mocBucket or price are invalid
        (pACtp, ) = LENDING_MANAGER.mocAdapter().validateAndGetPACtp(mocBucket_, tpToken_);
    }

    /// @notice Calculate the coverage ratio of a vault
    /// @dev Coverage = (AC balance * AC/TP price) / (credit units * PCU)
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return coverage The coverage ratio [PREC]. Returns MAX_UINT if no debt
    function getCoverage(address user_, address tpToken_, address mocBucket_) external view returns (uint256 coverage) {
        // Get and validate AC/TP price from adapter
        uint256 pACtp = _validateAndGetPACtp(mocBucket_, tpToken_);
        return getCoverageWithPACtp(user_, tpToken_, mocBucket_, pACtp);
    }

    /// @notice Calculate the coverage ratio of a vault with a specific AC/TP price
    /// @dev Coverage = (AC balance * AC/TP price) / (credit units * PCU)
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @param pACtp_ The AC/TP price [PREC]
    /// @return coverage The coverage ratio [PREC]. Returns MAX_UINT if no debt
    function getCoverageWithPACtp(
        address user_,
        address tpToken_,
        address mocBucket_,
        uint256 pACtp_
    ) public view returns (uint256 coverage) {
        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);
        uint256 vaultACBalance = LENDING_MANAGER.getUserVaultACBalance(user_, tpToken_, mocBucket_);
        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);

        return Pool.vaultCoverage(vaultCreditBalance, vaultACBalance, pCU, pACtp_);
    }

    /// @notice Check if a vault is liquidable
    /// @dev A vault is liquidable when coverage < liquidationCoverage. Gets price from adapter.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return isLiquidable True if the vault can be liquidated
    function isVaultLiquidable(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (bool isLiquidable) {
        // Get and validate AC/TP price from adapter
        uint256 pACtp = _validateAndGetPACtp(mocBucket_, tpToken_);
        return isVaultLiquidableWithPACtp(user_, tpToken_, mocBucket_, pACtp);
    }

    /// @notice Check if a vault is liquidable with a specific AC/TP price
    /// @dev A vault is liquidable when coverage < liquidationCoverage
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @param pACtp_ The AC/TP price [PREC]
    /// @return isLiquidable True if the vault can be liquidated at this price
    function isVaultLiquidableWithPACtp(
        address user_,
        address tpToken_,
        address mocBucket_,
        uint256 pACtp_
    ) public view returns (bool isLiquidable) {
        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);

        // If no debt, cannot be liquidated
        if (vaultCreditBalance == 0) return false;

        uint256 liquidationCoverage = LENDING_MANAGER.getLiquidationCoverage(tpToken_);
        uint256 coverage = getCoverageWithPACtp(user_, tpToken_, mocBucket_, pACtp_);

        return coverage < liquidationCoverage;
    }

    /// @notice Calculate the AC/TP price at which a vault would become liquidable
    /// @dev Returns the pACtp where coverage equals liquidationCoverage
    /// If vault has no debt, returns 0 (cannot be liquidated)
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address
    /// @return pACtpLiquidation The AC/TP price [PREC] at which the vault becomes liquidable. Returns 0 if no debt.
    function getLiquidationPrice(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256 pACtpLiquidation) {
        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);

        // If no debt, cannot be liquidated
        if (vaultCreditBalance == 0) return 0;

        uint256 vaultACBalance = LENDING_MANAGER.getUserVaultACBalance(user_, tpToken_, mocBucket_);

        // If no AC collateral, already liquidable at any price
        if (vaultACBalance == 0) return C.MAX_UINT;

        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);
        uint256 liquidationCoverage = LENDING_MANAGER.getLiquidationCoverage(tpToken_);

        // At liquidation: coverage = (vaultACBalance * pACtp) / (vaultCreditBalance * pCU) = liquidationCoverage
        // Solving for pACtp: pACtp = (liquidationCoverage * vaultCreditBalance * pCU) / vaultACBalance
        // [PREC] = [PREC] * [N] * [PREC] / [N] * [PREC]
        pACtpLiquidation = (liquidationCoverage * vaultCreditBalance * pCU) / (vaultACBalance * C.PRECISION);

        return pACtpLiquidation;
    }

    /// @notice Calculate the maximum TP tokens a user can borrow from their vault
    /// @dev Considers: AC collateral in vault, existing credit units, pool liquidity,
    /// and minCoverage requirement. Gets price from adapter.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address used as collateral
    /// @return maxTPToBorrow The maximum TP tokens that can be borrowed
    function getMaxTPToBorrow(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256 maxTPToBorrow) {
        // Get and validate AC/TP price from adapter
        uint256 pACtp = _validateAndGetPACtp(mocBucket_, tpToken_);
        return getMaxTPToBorrowWithPACtp(user_, tpToken_, mocBucket_, pACtp);
    }

    /// @notice Calculate the maximum TP tokens a user can borrow from their vault with a specific AC/TP price
    /// @dev Considers: AC collateral in vault, existing credit units, pool liquidity, and minCoverage requirement
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address used as collateral
    /// @param pACtp_ The AC/TP price [PREC]
    /// @return maxTPToBorrow The maximum TP tokens that can be borrowed
    function getMaxTPToBorrowWithPACtp(
        address user_,
        address tpToken_,
        address mocBucket_,
        uint256 pACtp_
    ) public view returns (uint256 maxTPToBorrow) {
        // Get vault state
        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);
        uint256 vaultACBalance = LENDING_MANAGER.getUserVaultACBalance(user_, tpToken_, mocBucket_);

        // If no AC in vault, cannot borrow
        if (vaultACBalance == 0) return 0;

        // Get current price of credit unit
        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);

        // Get minimum coverage required
        uint256 minCoverage = LENDING_MANAGER.getMinCoverage(tpToken_);

        // Calculate max TP based on collateral constraint:
        // coverage = (vaultACBalance * pACtp) / (totalCreditUnits * pCU) >= minCoverage
        // Solving for totalCreditUnits:
        // totalCreditUnits <= (vaultACBalance * pACtp) / (minCoverage * pCU)
        // [N] = [N] * [PREC] * [PREC] / [PREC] * [PREC]
        uint256 maxTotalCreditUnits = (vaultACBalance * pACtp_).divPrec((minCoverage * pCU));

        // Subtract existing credit units to get additional credit units available
        uint256 additionalCreditUnits = maxTotalCreditUnits > vaultCreditBalance
            ? maxTotalCreditUnits - vaultCreditBalance
            : 0;

        // Convert credit units to TP tokens
        // [N] = [N] * [PREC] / [PREC]
        uint256 maxTPFromCollateral = additionalCreditUnits.mulPrec(pCU);

        // Get available liquidity in pool
        uint256 poolLiquidity = LENDING_MANAGER.getPoolLiquidity(tpToken_);

        // Return the minimum of collateral-based limit and pool liquidity
        return Math.min(maxTPFromCollateral, poolLiquidity);
    }

    /// @notice Calculate the maximum AC tokens a user can remove from their vault
    /// @dev Considers: existing AC collateral, credit units debt, and minCoverage requirement. Gets price from adapter.
    /// If there's no debt, all AC can be removed. If there's debt, must maintain minCoverage.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address used as collateral
    /// @return maxACToRemove The maximum AC tokens that can be removed
    function getMaxACToRemove(
        address user_,
        address tpToken_,
        address mocBucket_
    ) external view returns (uint256 maxACToRemove) {
        // Get and validate AC/TP price from adapter
        uint256 pACtp = _validateAndGetPACtp(mocBucket_, tpToken_);
        return getMaxACToRemoveWithPACtp(user_, tpToken_, mocBucket_, pACtp);
    }

    /// @notice Calculate the maximum AC tokens a user can remove from their vault with a specific AC/TP price
    /// @dev Considers: existing AC collateral, credit units debt, and minCoverage requirement
    /// If there's no debt, all AC can be removed. If there's debt, must maintain minCoverage.
    /// @param user_ The vault owner
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket address used as collateral
    /// @param pACtp_ The AC/TP price [PREC]
    /// @return maxACToRemove The maximum AC tokens that can be removed
    function getMaxACToRemoveWithPACtp(
        address user_,
        address tpToken_,
        address mocBucket_,
        uint256 pACtp_
    ) public view returns (uint256 maxACToRemove) {
        // Get vault state
        uint256 vaultCreditBalance = LENDING_MANAGER.getUserVaultCreditBalance(user_, tpToken_, mocBucket_);
        uint256 vaultACBalance = LENDING_MANAGER.getUserVaultACBalance(user_, tpToken_, mocBucket_);

        // If no AC in vault, cannot remove anything
        if (vaultACBalance == 0) return 0;

        // If no debt, can remove all AC
        if (vaultCreditBalance == 0) return vaultACBalance;

        // Get current price of credit unit
        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);

        // Get minimum coverage required
        uint256 minCoverage = LENDING_MANAGER.getMinCoverage(tpToken_);

        // Calculate min AC required to maintain minCoverage:
        // coverage = (minACBalance * pACtp) / (vaultCreditBalance * pCU) >= minCoverage
        // Solving for minACBalance:
        // minACBalance >= (vaultCreditBalance * pCU * minCoverage) / pACtp
        // [N] = [N] * [PREC] * [PREC] / [PREC] * [PREC]
        uint256 minACRequired = (vaultCreditBalance * pCU * minCoverage) / (pACtp_ * C.PRECISION);

        // Max to remove is current balance minus minimum required
        if (vaultACBalance <= minACRequired) return 0;

        return vaultACBalance - minACRequired;
    }

    /// @notice Calculate the brake factor for TP injection based on emission rate
    /// @dev The brake factor reduces injection rate when emission is high:
    /// - Returns 1.0 when emission <= brakeFirstKink (no brake)
    /// - Returns linear interpolation between brakeFirstKink and brakeSecondKink
    /// - Returns 0 when emission >= brakeSecondKink (full brake)
    /// @param tpToken_ The TP token address
    /// @param emissionRate_ The current emission rate [PREC]
    /// @return brakeFactor The brake factor [PREC] (0 to C.ONE)
    function getBrakeFactor(address tpToken_, uint256 emissionRate_) external view returns (uint256 brakeFactor) {
        uint256 brakeFirstKink = LENDING_MANAGER.getBrakeFirstKink(tpToken_);
        uint256 brakeSecondKink = LENDING_MANAGER.getBrakeSecondKink(tpToken_);

        return Pool.calculateBrakeFactor(emissionRate_, brakeFirstKink, brakeSecondKink);
    }

    /// @notice Calculate the utilization rate of a pool
    /// @dev Utilization is defined as: total borrows / (total borrows + total liquidity)
    /// @param tpToken_ The TP token address
    /// @return utilization The utilization rate [PREC]
    function getUtilizationRate(address tpToken_) external view returns (uint256 utilization) {
        uint256 creditSupply = LENDING_MANAGER.getPoolCreditSupply(tpToken_);
        uint256 liquidity = LENDING_MANAGER.getPoolLiquidity(tpToken_);
        uint256 pCU = LENDING_MANAGER.getPriceCreditUnit(tpToken_);

        return Pool.calculateUtilizationRate(creditSupply, liquidity, pCU);
    }

    /// @notice Returns the list of unique (acToken, tpToken) pairs for all pending operations in the queue.
    /// @dev Each element is 40 bytes: abi.encode(acToken, tpToken)
    /// This function helps off-chain services know which price pairs they need to publish.
    /// @return pairs An array of encoded address pairs (acToken, tpToken).
    function getPACtpNeeded() external view returns (bytes[] memory pairs) {
        IMocAdapter mocAdapter = LENDING_MANAGER.mocAdapter();
        // Get queue state from lending manager
        uint256 operIdCount = LENDING_MANAGER.operIdCount();
        uint256 firstOperId = LENDING_MANAGER.firstOperId();
        uint256 pendingCount = operIdCount - firstOperId;

        if (pendingCount == 0) return new bytes[](0);

        bytes[] memory tempPairs = new bytes[](pendingCount);
        bytes32[] memory seenHashes = new bytes32[](pendingCount);
        uint256 uniqueCount;

        for (uint256 i = 0; i < pendingCount; ++i) {
            // Read operation from lending manager
            (
                , // operType - not needed
                , // user - not needed
                , // recipient - not needed
                address tpToken,
                address mocBucket,
                , // amount - not needed

            ) = LENDING_MANAGER.operations(firstOperId + i); // queuedBlk - not needed
            (address acToken, ) = mocAdapter.validateAndGetACToken(mocBucket);
            bytes memory packed = abi.encode(acToken, tpToken);
            bytes32 hash = keccak256(packed);

            bool duplicate = false;
            for (uint256 j = 0; j < uniqueCount; ++j) {
                if (seenHashes[j] == hash) {
                    duplicate = true;
                    break;
                }
            }

            if (!duplicate) {
                seenHashes[uniqueCount] = hash;
                tempPairs[uniqueCount] = packed;
                ++uniqueCount;
            }
        }

        pairs = new bytes[](uniqueCount);
        for (uint256 i = 0; i < uniqueCount; ++i) {
            pairs[i] = tempPairs[i];
        }

        return pairs;
    }
}

