pragma solidity 0.8.24;

import { FixedPoint } from "../lib/FixedPoint.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IMocSwapper } from "@moc/moc-main/contracts/interfaces/IMocSwapper.sol";
import { Governed, IGovernor } from "@moc/moc-main/contracts/governance/Governed.sol";
import { IMocV1, IMocStateV1, IMocInrateV1 } from "../interfaces/IMocV1.sol";

/// @title Swapper contract to exchange rBTC and DOC using MOC V1
/// @author Money On Chain
/// @notice This contract allows swapping between rBTC (coinbase) and DOC tokens using the MOC V1 protocol.
contract MocSwapperCoreV1 is IMocSwapper, Governed {
    using SafeERC20 for IERC20;
    using FixedPoint for uint256;

    address private constant COINBASE = address(0);

    // -----------------
    // Custom Errors
    // -----------------

    /// @notice Thrown when the input amount is lower than the minimum required
    error AmountInTooLow();

    /// @notice Thrown when the output amount is lower than the minimum expected
    error AmountOutTooLow();

    /// @notice Thrown when the provided token address is incorrect
    error WrongToken();

    /// @notice Thrown when coinbase transfer fails
    error CoinbaseTransferFailed();

    /// @notice Thrown when a function is not implemented
    error NotImplemented();

    // -----------------
    // Storage
    // -----------------

    /// @notice Moc V1 contract
    IMocV1 public immutable MOC_V1;
    /// @notice Moc State V1 contract
    IMocStateV1 public immutable MOC_STATE_V1;
    /// @notice Moc Inrate V1 contract
    IMocInrateV1 public immutable MOC_INRATE_V1;
    /// @notice Address of the DOC token
    address public immutable DOC;

    enum TxType {
        NONE,
        MINT_BPRO_FEES_RBTC,
        REDEEM_BPRO_FEES_RBTC,
        MINT_DOC_FEES_RBTC,
        REDEEM_DOC_FEES_RBTC,
        MINT_BTCX_FEES_RBTC,
        REDEEM_BTCX_FEES_RBTC,
        MINT_BPRO_FEES_MOC,
        REDEEM_BPRO_FEES_MOC,
        MINT_DOC_FEES_MOC,
        REDEEM_DOC_FEES_MOC,
        MINT_BTCX_FEES_MOC,
        REDEEM_BTCX_FEES_MOC
    }

    /// @notice Constructor
    /// @param governor_ The address of the governor contract
    /// @param mocV1_ The address of the MOC V1 contract
    /// @param mocStateV1_ The address of the MOC State V1 contract
    /// @param mocInrateV1_ The address of the MOC Inrate V1 contract
    /// @param doc_ The address of the DOC token
    constructor(address governor_, address mocV1_, address mocStateV1_, address mocInrateV1_, address doc_) {
        _disableInitializers();
        governor = IGovernor(governor_);
        MOC_V1 = IMocV1(mocV1_);
        MOC_STATE_V1 = IMocStateV1(mocStateV1_);
        MOC_INRATE_V1 = IMocInrateV1(mocInrateV1_);
        DOC = doc_;
    }

    /// @inheritdoc IMocSwapper
    function swapCoinbase(
        address tokenOut_,
        uint256 amountOutMin_,
        address recipient_
    ) external payable override returns (uint256 amountOut) {
        if (tokenOut_ != DOC) revert WrongToken();
        // subtract platform fees from the rBTC sent
        // [N] = [N] * [PREC] / [PREC]
        uint256 btcWithoutFees = msg.value.divPrec(
            ONE + MOC_INRATE_V1.commissionRatesByTxType(uint8(TxType.MINT_DOC_FEES_RBTC))
        );

        // mint DOC with the all the rBTC sent
        uint256 docBalanceBefore = IERC20(tokenOut_).balanceOf(address(this));
        MOC_V1.mintDoc{ value: msg.value }(btcWithoutFees);
        uint256 docBalanceAfter = IERC20(tokenOut_).balanceOf(address(this));
        amountOut = docBalanceAfter - docBalanceBefore;
        if (amountOut < amountOutMin_) revert AmountOutTooLow();

        // transfer the minted DOC to the recipient
        IERC20(tokenOut_).safeTransfer(recipient_, amountOut);
        return amountOut;
    }

    /// @inheritdoc IMocSwapper
    function swapCoinbaseExactOutput(
        address tokenOut_,
        uint256 amountOut_,
        address recipient_
    ) external payable override returns (uint256 amountIn) {
        if (tokenOut_ != DOC) revert WrongToken();
        // increase the amountOut_ to absorb rounding errors
        uint256 inflatedAmountOut = amountOut_.mulPrec(PRECISION + 1e6);
        uint256 btcAmount = inflatedAmountOut.divPrec(MOC_STATE_V1.getBitcoinPrice());
        if (msg.value <= btcAmount) revert AmountInTooLow();

        // mint the exact amount of DOC needed
        uint256 btcBalanceBefore = address(this).balance;
        // if msg.value is not enough to cover btcAmount + fees, this will revert
        MOC_V1.mintDoc{ value: msg.value }(btcAmount);
        uint256 btcBalanceAfter = address(this).balance;
        amountIn = btcBalanceBefore - btcBalanceAfter;

        // transfer the minted DOC to the recipient
        IERC20(tokenOut_).safeTransfer(recipient_, amountOut_);
        // return the surplus rBTC to the caller
        (bool success, ) = msg.sender.call{ value: msg.value - amountIn }("");
        if (!success) revert CoinbaseTransferFailed();
        return amountIn;
    }

    /// @inheritdoc IMocSwapper
    function swapRC20(
        address /*tokenIn_*/,
        address /*tokenOut_*/,
        uint256 /*amountIn_*/,
        uint256 /*amountOutMin_*/,
        address /*recipient_*/
    ) external pure override returns (uint256 /*amountOut*/) {
        revert NotImplemented();
    }

    /// @inheritdoc IMocSwapper
    function swapRC20ExactOutput(
        address /*tokenIn_*/,
        address /*tokenOut_*/,
        uint256 /*amountOut_*/,
        uint256 /*amountInMax_*/,
        address /*recipient_*/
    ) external pure override returns (uint256 /*amountIn*/) {
        revert NotImplemented();
    }

    /// @inheritdoc IMocSwapper
    function getSafeMaxAmountToSwap(address tokenIn_, address tokenOut_) external view override returns (uint256) {
        if (tokenIn_ != COINBASE || tokenOut_ != DOC) revert WrongToken();
        // max amount of DOC that can be minted due to the current system limit
        return MOC_STATE_V1.absoluteMaxDoc().divPrec(MOC_STATE_V1.getBitcoinPrice());
    }

    /// @notice Emergency function to withdraw ERC20 tokens from the contract.
    /// @dev Only callable by an authorized changer
    /// @param token_ The address of the ERC20 token to withdraw.
    /// @param to_ The address to send the withdrawn tokens to.
    function emergencyWithdrawERC20(address token_, address to_) external onlyAuthorizedChanger {
        IERC20 token = IERC20(token_);
        uint256 balance = token.balanceOf(address(this));
        token.safeTransfer(to_, balance);
    }

    /// @notice Emergency function to withdraw coinbase (rBTC) from the contract.
    /// @dev Only callable by an authorized changer
    /// @param to_ The address to send the withdrawn coinbase to.
    function emergencyWithdrawCoinbase(address to_) external onlyAuthorizedChanger {
        uint256 balance = address(this).balance;
        (bool success, ) = to_.call{ value: balance }("");
        if (!success) revert CoinbaseTransferFailed();
    }

    /// @notice Receive function to accept coinbase transfers
    receive() external payable {}
}

