pragma solidity 0.8.24;

import { MocUpgradable } from "@moc/moc-main/contracts/governance/MocUpgradable.sol";
import { MocLendingManager } from "./MocLendingManager.sol";
import { IMocAdapter } from "./interfaces/IMocAdapter.sol";
import { Coin } from "./lib/Coin.sol";
import { C } from "./lib/Constants.sol";
import { FixedPoint } from "./lib/FixedPoint.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/// @title TPInjector contract to inject TP tokens to the lending pool
/// @author Money On Chain
/// @notice This contract receives AC tokens and mints TP tokens to the lending pool once every certain period.
contract TPInjector is MocUpgradable {
    using FixedPoint for uint256;
    using Coin for IERC20;

    // -----------------
    // Custom Errors
    // -----------------
    error OnlyLendingManager();

    /// @notice Thrown when the AC/TP price is invalid
    error InvalidPrice();

    // -----------------
    // Modifiers
    // -----------------
    /// @notice Modifier to restrict access to the Lending Manager
    modifier onlyLendingManager() {
        _onlyLendingManager();
        _;
    }

    /// @notice Internal function to restrict access to the Lending Manager
    function _onlyLendingManager() internal view {
        if (msg.sender != address(mocLendingManager)) revert OnlyLendingManager();
    }

    // -----------------
    // Storage
    // -----------------
    /// @notice The TP token address to mint
    address public tpToken;
    /// @notice The MocLendingManager contract reference
    MocLendingManager public mocLendingManager;

    /// @notice Constructor to disable initializers for the implementation contract
    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the contract
    /// @param governor_ The address of the governor contract
    /// @param pauser_ The address of the pauser contract
    /// @param tpToken_ The address of the TP token to mint
    /// @param mocLendingManager_ The address of the MocLendingManager contract
    function initialize(
        address governor_,
        address pauser_,
        address tpToken_,
        address payable mocLendingManager_
    ) public initializer {
        __MocUpgradable_init(governor_, pauser_);
        tpToken = tpToken_;
        mocLendingManager = MocLendingManager(mocLendingManager_);
    }

    /// @notice Mints TP tokens and inject them to the lending pool using the AC tokens held by this contract.
    /// @dev The amount to mint is determined by the lending manager for each bucket (AC token).
    /// Any unused AC tokens after minting are sent back to the protocol's core contract.
    function injectTP() external onlyLendingManager {
        // Get mocAdapter from the lending manager
        IMocAdapter mocAdapter = mocLendingManager.mocAdapter();
        address tp = tpToken;

        // Get all buckets
        address[] memory mocBuckets = mocAdapter.getMocBuckets();
        uint256[] memory tpInjectRates = new uint256[](mocBuckets.length);
        uint256[] memory tpSupplyBuckets = new uint256[](mocBuckets.length);

        // We need to calculate for all the buckets before the swaps, so the previous swaps
        // do not affect the next calculations
        for (uint256 i = 0; i < mocBuckets.length; ++i) {
            (tpInjectRates[i], tpSupplyBuckets[i]) = _calcTPInjectionRate(mocAdapter, mocBuckets[i], tp);
        }

        // Iterate over each bucket to perform the injections
        for (uint256 i = 0; i < mocBuckets.length; ++i) {
            _injectForBucket(mocAdapter, tp, mocBuckets[i], tpInjectRates[i], tpSupplyBuckets[i]);
        }
    }

    /// @notice Internal function to calculate the TP injection rate and TP supply for a specific bucket
    /// @param mocAdapter The MocAdapter instance
    /// @param mocBucket_ The Moc Bucket for this bucket
    /// @param tpToken_ The TP token address
    /// @return tpInjectionRate The TP injection rate for this bucket
    /// @return tpSupplyBucket The TP supply for this bucket
    function _calcTPInjectionRate(
        IMocAdapter mocAdapter,
        address mocBucket_,
        address tpToken_
    ) internal view returns (uint256 tpInjectionRate, uint256 tpSupplyBucket) {
        // Get emission rate for this bucket
        uint256 emissionRate = mocAdapter.getEmissionRateByBucket(mocBucket_, tpToken_);
        // Get TP supply for this bucket
        tpSupplyBucket = mocAdapter.getTPSupplyByBucket(mocBucket_, tpToken_);
        // Get injection rate from the lending manager for this bucket's emission rate
        tpInjectionRate = mocLendingManager.getTPInjectRate(tpToken_, emissionRate);
        return (tpInjectionRate, tpSupplyBucket);
    }

    /// @notice Internal function to inject TP for a specific bucket
    /// @param mocAdapter_ The MocAdapter instance
    /// @param tpToken_ The TP token address
    /// @param mocBucket_ The Moc Bucket for this bucket
    /// @param tpInjectRate_ The TP injection rate for this bucket
    /// @param tpSupplyBucket_ The TP supply for this bucket
    function _injectForBucket(
        IMocAdapter mocAdapter_,
        address tpToken_,
        address mocBucket_,
        uint256 tpInjectRate_,
        uint256 tpSupplyBucket_
    ) internal {
        // Get price and validate. Reverts if invalid
        (uint256 pACtp, address acToken) = mocAdapter_.validateAndGetPACtp(mocBucket_, tpToken_);

        // Get AC balance for this token
        uint256 acBalance = IERC20(acToken).coinBalanceOf(address(this));

        // Skip if no AC balance
        if (acBalance == 0) {
            return;
        }

        // Calculate the amount of AC tokens to spend
        uint256 acToSpend = _calculateACToSpend(tpInjectRate_, acBalance, tpSupplyBucket_);

        // Skip if nothing to spend
        if (acToSpend > 0) {
            // Perform the swap
            acToSpend = _performSwap(mocBucket_, acToken, tpToken_, acToSpend, pACtp);
        }

        // Send remaining AC tokens to core if any
        IERC20(acToken).coinTransfer(mocBucket_, acBalance - acToSpend);
    }

    /// @notice Calculate the amount of AC to spend for injection
    /// @param tpInjectRate The TP injection rate
    /// @param acBalance The available AC balance
    /// @param tpSupplyBucket The TP supply for this bucket
    /// @return acToSpend The amount of AC to spend
    function _calculateACToSpend(
        uint256 tpInjectRate,
        uint256 acBalance,
        uint256 tpSupplyBucket
    ) internal pure returns (uint256 acToSpend) {
        // Calculate the amount of AC tokens to spend based on:
        // - injection rate (with precision)
        // - available AC balance
        // - TP supply for this bucket (with precision)
        // tpInjectRate and tpSupplyBucket should be always <= C.ONE (1e18)
        // [N] = [PREC] * ([N] * [PREC] / [PREC]) / [PREC]
        acToSpend = tpInjectRate.mulPrec(acBalance * tpSupplyBucket).subPrec();
    }

    /// @notice Perform the swap and send remaining AC to core
    /// @param mocBucket_ The address of the Moc bucket.
    /// @param acToken_ The AC token being swapped
    /// @param tpToken_ The TP token being swapped
    /// @param acToSpend_ The amount of AC to spend
    /// @param pACtp_ The AC/TP price
    /// @return The amount of AC tokens spent
    function _performSwap(
        address mocBucket_,
        address acToken_,
        address tpToken_,
        uint256 acToSpend_,
        uint256 pACtp_
    ) internal returns (uint256) {
        // Calculate minimum price with slippage protection
        uint256 maxSlippage = mocLendingManager.maxSlippage();
        uint256 minPriceOut = pACtp_.mulPrec(C.ONE - maxSlippage);

        // Swap AC to TP tokens using the both mocSwapper, sending TPs to the lending manager
        (uint256 acSwapped, ) = IERC20(acToken_).swapTwoSteps(
            mocLendingManager.mocSwapperCore(mocBucket_, tpToken_),
            mocLendingManager.mocSwapperExchange(mocBucket_, tpToken_),
            tpToken_,
            address(mocLendingManager),
            acToSpend_,
            minPriceOut,
            false // do not revert on failure swap
        );

        return acSwapped;
    }

    /// @notice Fallback function to accept coinbase transfers
    receive() external payable {}

    /// @dev This empty reserved space is put in place to allow future versions to add new
    /// variables without shifting down storage in the inheritance chain.
    /// See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps

    // Purposely left unused to save some state space to allow for future upgrades
    // slither-disable-next-line unused-state
    uint256[50] private __gap;
}

