    function liqRedeemTP(address tp_, address recipient_) external returns (uint256 qACRedeemed) {
        return _liqRedeemTPTo(tp_, msg.sender, recipient_);
    }

    /**
     * @notice distribute appreciation factor to beneficiary and success fee to Moc Fee Flow
     */
    function _distributeSuccessFee() internal {
        uint256 mocGain = 0;
        uint256 pegAmount = pegContainer.length;
        uint256[] memory tpToMint = new uint256[](pegAmount);
        for (uint256 i = 0; i < pegAmount; i = unchecked_inc(i)) {
            uint256 pACtp = _getPACtp(i);
            _updateTPtracking(i, pACtp);
            int256 iou = tpiou[i];
            if (iou > 0) {
                // [N] = (([PREC] * [PREC] / [PREC]) * [N]) / [PREC]
                tpToMint[i] = _mulPrec(_mulPrec(appreciationFactor, pACtp), uint256(iou));
                // [N] = [N] + [N]
                mocGain += uint256(iou);
                // reset TP profit
                tpiou[i] = 0;
                _depositAndMintTP(i, tpToMint[i], 0, mocAppreciationBeneficiaryAddress);
            }
        }
        if (mocGain != 0) {
            // [N] = [N] * [PREC] / [PREC]
            mocGain = _mulPrec(mocGain, successFee);
            // sub qAC from the Bucket
            nACcb -= mocGain;
            // transfer the mocGain AC to Moc Fee Flow
            acTransfer(mocFeeFlowAddress, mocGain);
        }
        emit SuccessFeeDistributed(mocGain, tpToMint);
    }

    // ------- External Functions -------

    /**
     * @notice this function is executed during settlement.
     *  stores amount of locked AC by Pegged Tokens at this moment and distribute success fee
     */
    function execSettlement() external notPaused {
        // check if it is in the corresponding time to execute the settlement
        if (block.timestamp < nextSettlementTime) revert MissingTimeToSettlement();
        unchecked {
            nextSettlementTime = block.timestamp + settlementTimeSpan;
        }
        emit SettlementExecuted();
        _distributeSuccessFee();
    }

    /**
     * @notice executes the interest payment of the TC holders
     *  can only be executed after `tcInterestPaymentTimeSpan`
     * @dev
     *  -   The amount is not differential, it's a snapshot of the moment it's executed
     *  -   It does not check coverage
     */
    function tcHoldersInterestPayment() external notPaused {
        // check if it is in the corresponding time to execute the interest payment
        if (block.timestamp < nextTCInterestPayment) revert MissingTimeToTCInterestPayment();
        unchecked {
            nextTCInterestPayment = block.timestamp + tcInterestPaymentTimeSpan;
        }
        // [N] = [N] * [PREC] / [PREC]
        uint256 interestAmount = _mulPrec(nACcb, tcInterestRate);
        emit TCInterestPayment(interestAmount);
        // sub interests from the Bucket
        nACcb -= interestAmount;
        // transfer interests to the interest collector address, reverts if fail
        acTransfer(tcInterestCollectorAddress, interestAmount);
    }

    /**
     * @notice removes TPs from the bucket and send AC to the MultiCollateralGuard contract
     *  called during a rebalancing process
     * @dev only called by MultiCollateralGuard contract
     * @param tp_ Pegged Token address
     * @param qTP_ amount of TPs to remove
     * @param qAC_ amount of AC to sent
     */
    function rebalance(address tp_, uint256 qTP_, uint256 qAC_) external onlyMultiCollateralGuard {
        uint256 tpIndex = _tpi(tp_);
        _updateTPtracking(tpIndex, _getPACtp(tpIndex));
        _withdrawTP(tpIndex, qTP_, qAC_);
        acTransfer(msg.sender, qAC_);
    }

    /**
     * @notice adds TPs to the bucket
     *  called during a rebalancing process
     * @dev only called by MultiCollateralGuard contract
     * @param tp_ Pegged Token address
     * @param qTP_ amount of TPs to add
     */
    function acceptRebalance(address tp_, uint256 qTP_) external onlyMultiCollateralGuard {
        uint256 tpIndex = _tpi(tp_);
        _updateTPtracking(tpIndex, _getPACtp(tpIndex));
        // qAC will be taking on account when the AC is transferred
        _depositTP(tpIndex, qTP_, 0 /*qAC*/);
    }

    // ------- Only Authorized Changer Functions -------

    /**
     * @dev sets Moc Core Expansion contract address
     * @param mocCoreExpansion_ moc core expansion new contract address
     */
    function setMocCoreExpansion(address mocCoreExpansion_) external onlyAuthorizedChanger {
        // slither-disable-next-line missing-zero-check
        mocCoreExpansion = mocCoreExpansion_;
    }

    /**
     * @notice add a Pegged Token to the protocol
     * @dev Note that the ema value, should consider `nextEmaCalculation`
     *  This function is implemented in MocCoreExpansion but with this contract context
     *  @param tpToken_ Pegged Token contract to add
     *  peggedTokenParams_ params of Pegged Token to add:
     *      priceProviderAddress Pegged Token price provider contract address
     *      tpCtarg Pegged Token target coverage [PREC]
     *      tpMintFee additional fee pct applied on mint [PREC]
     *      tpRedeemFee additional fee pct applied on redeem [PREC]
     *      tpEma initial Pegged Token exponential moving average [PREC]
     *      tpEmaSf Pegged Token smoothing factor [PREC]
     * @dev Pegged Token should be added using the corresponding changer template, which
     *      should guarantee that it is added on all the buckets(mandatory for multiCollateral)
     *
     *  Requirements:
     *
     * - the caller must have governance authorization.
     * - tpToken must be a MocRC20, with mint, burn roles already settled
     *  for this contract
     */
    function addPeggedToken(
        IMocRC20 tpToken_,
        PeggedTokenParams calldata peggedTokenParams_
    ) external onlyAuthorizedChanger {
        bytes memory payload = abi.encodeCall(
            MocCoreExpansion(mocCoreExpansion).addPeggedToken,
            (tpToken_, peggedTokenParams_)
        );
        // slither-disable-next-line unused-return
        Address.functionDelegateCall(mocCoreExpansion, payload);
    }

    /**
     * @notice modifies a Pegged Token of the protocol
     * @dev Note that the ema value, should consider `nextEmaCalculation`
     *  This function is implemented in MocCoreExpansion but with this contract context
     *  @param tpToken_ Pegged Token contract to edit
     *  peggedTokenParams_ params of Pegged Token to edit:
     *      priceProviderAddress Pegged Token price provider contract address
     *      tpCtarg Pegged Token target coverage [PREC]
     *      tpMintFee additional fee pct applied on mint [PREC]
     *      tpRedeemFee additional fee pct applied on redeem [PREC]
     *      tpEma initial Pegged Token exponential moving average [PREC]
     *      tpEmaSf Pegged Token smoothing factor [PREC]
     *
     *  Requirements:
     *
     * - the caller must have governance authorization.
     * - the tpTokenAddress must exists
     */
    function editPeggedToken(
        IMocRC20 tpToken_,
        PeggedTokenParams calldata peggedTokenParams_
    ) external onlyAuthorizedChanger {
        bytes memory payload = abi.encodeCall(
            MocCoreExpansion(mocCoreExpansion).editPeggedToken,
            (tpToken_, peggedTokenParams_)
        );
        // slither-disable-next-line unused-return
        Address.functionDelegateCall(mocCoreExpansion, payload);
    }

    /**
     * @notice liquidate the bucket, settling the TPs liquidation prices and blocking all mint & redeem operations.
     * @dev it should only be used when it is the only bucket available
     *  because it is a single collateral protocol or a multi collateral but the rest has already been liquidated
     *
     * May emit a {ContractLiquidated} event.
     */
    function liquidate() external notPaused onlyMultiCollateralGuard {
        liquidated = true;
        // Freeze current Peg Price given the AC available
        bytes memory payload = abi.encodeCall(MocCoreExpansion(mocCoreExpansion).settleLiquidationPrices, ());
        Address.functionDelegateCall(mocCoreExpansion, payload);
    }

    /**
     * @notice set liquidated
     * @dev only called by MocMultiCollateralGuard after rebalancing all the TPs to other buckets.
     *  This bucket will be removed from the multi collateral protocol as well
     */
    function setLiquidated() external notPaused onlyMultiCollateralGuard {
        liquidated = true;
    }

    /**
     * @dev sets Moc Vendors contract address
     * @param mocVendors_ moc Vendors new contract address
     */
    function setMocVendors(address mocVendors_) external onlyAuthorizedChanger {
        // slither-disable-next-line missing-zero-check
        mocVendors = MocVendors(mocVendors_);
    }

    // ------- Getters Functions -------

    /**
     * @notice gets Pegged Token minted
     * @return nTP
     */
    function getNTP(address tp_) external view returns (uint256 nTP) {
        return pegContainer[_tpi(tp_)].nTP;
    }

    /**
     * @notice gets Collateral Token price
     * @return pTCac [PREC]
     */
    function getPTCac() external view returns (uint256 pTCac) {
        (uint256 lckAC, uint256 nACgain) = _getLckACandACgain(_getPACtps());
        return _getPTCac(lckAC, nACgain);
    }

    /**
     * @notice calc Collateral Token price given an array of TP prices
     * @param pACtps_ All tps prices [PREC]
     * @return pTCac [PREC]
     */
    function calcPTCac(uint256[] calldata pACtps_) external view returns (uint256 pTCac) {
        (uint256 lckAC, uint256 nACgain) = _getLckACandACgain(pACtps_);
        return _getPTCac(lckAC, nACgain);
    }

    /**
     * @notice gets all TP prices
     * @return pACtps All tps prices [PREC]
     */
    function getPACtps() external view returns (uint256[] memory pACtps) {
        return _getPACtps();
    }

    /**
     * @notice get the min or max last publication block among all Pegged Tokens
     * @param useMaxLastPublicationBlock_ use the max last publication block to trigger the queue execution
     * @return lastPublicationBlock the max last block where there was a price publication
     */
    function getLastPublicationBlock(
        bool useMaxLastPublicationBlock_
    ) external view returns (uint256 lastPublicationBlock) {
        lastPublicationBlock = pegContainer[0].priceProvider.getLastPublicationBlock();
        uint256 pegAmount = pegContainer.length;
        for (uint256 i = 1; i < pegAmount; i = unchecked_inc(i)) {
            uint256 tpLastPublicationBlock = pegContainer[i].priceProvider.getLastPublicationBlock();
            lastPublicationBlock = useMaxLastPublicationBlock_
                ? Math.max(lastPublicationBlock, tpLastPublicationBlock)
                : Math.min(lastPublicationBlock, tpLastPublicationBlock);
        }
    }

    /**
     * @notice gets bucket global coverage
     * @return cglob [PREC]
     */
    function getCglb() external view returns (uint256 cglob) {
        (uint256 lckAC, uint256 nACgain) = _getLckACandACgain(_getPACtps());
        return _getCglb(lckAC, nACgain);
    }

    /**
     * @notice calc bucket global coverage given an array of TP prices
     * @param pACtps_ All tps prices [PREC]
     * @return cglob [PREC]
     */
    function calcCglb(uint256[] calldata pACtps_) external view returns (uint256 cglob) {
        (uint256 lckAC, uint256 nACgain) = _getLckACandACgain(pACtps_);
        return _getCglb(lckAC, nACgain);
    }

    /**
     * @notice gets amount of Collateral Asset locked by Pegged Token
     * @return lckAC [PREC]
     */
    function getLckAC() external view returns (uint256 lckAC) {
        (lckAC, ) = _getLckACandACgain(_getPACtps());
    }

    /**
     * @notice calc amount of Collateral Asset locked by Pegged Token given an array of TP prices
     * @param pACtps_ All tps prices [PREC]
     * @return lckAC [PREC]
     */
    function calcLckAC(uint256[] calldata pACtps_) external view returns (uint256 lckAC) {
        (lckAC, ) = _getLckACandACgain(pACtps_);
    }

    /**
     * @notice calc global coverage and amount of Collateral Asset locked by Pegged Token given an array of TP prices
     * @param i_ Pegged Token index
     * @notice gets amount of Collateral Asset locked by a given Pegged Token
     * @return lckAC [PREC]
     */
    function getLckACByTP(uint256 i_) external view returns (uint256 lckAC) {
        uint256 pACtp = _getPACtp(i_);
        (uint256 tpGain, ) = _getPnLTP(i_, pACtp);
        // [N] = ([N] + [N]) * [PREC] / [PREC]
        return _divPrec(pegContainer[i_].nTP + tpGain, pACtp);
    }

    /**
     * @notice gets global coverage and amount of Collateral Asset locked by Pegged Token
     * @return cglob [PREC]
     * @return lckAC [PREC]
     */
    function calcCglbAndLckAC(uint256[] calldata pACtps_) external view returns (uint256 cglob, uint256 lckAC) {
        uint256 nACgain;
        (lckAC, nACgain) = _getLckACandACgain(pACtps_);
        return (_getCglb(lckAC, nACgain), lckAC);
    }

    /**
     * @notice calc amount of Collateral Asset available considering how many are locked by Pegged Token adjusted by EMA
     *  given an array of TP prices
     * @param pACtps_ All tps prices [PREC]
     * @return lckACemaAdjusted [PREC]
     */
    function calcLckACemaAdjusted(uint256[] calldata pACtps_) external view returns (int256 lckACemaAdjusted) {
        uint256 ctargemaCA = _calcCtargemaCA(pACtps_);
        (uint256 lckAC, uint256 nACgain) = _calcLckACandACgain(pACtps_);
        return _getLckACemaAdjusted(ctargemaCA, lckAC, nACgain);
    }

    /**
     * @notice gets amount of Collateral Token available to redeem signed
     * @dev because it is a view function we are not calculating the new ema,
     *  since we are using the last ema calculation, this may differ a little from the real amount
     *  of TC available to redeem. Consider it an approximation.
     * @return tcAvailableToRedeem [N]
     */
    function getTCAvailableToRedeem() external view returns (uint256 tcAvailableToRedeem) {
        return calcTCAvailableToRedeem(_getPACtps());
    }

    /**
     * @notice calc amount of Collateral Token available to redeem signed given an array of TP prices
     * @dev because it is a view function we are not calculating the new ema,
     *  since we are using the last ema calculation, this may differ a little from the real amount
     *  of TC available to redeem. Consider it an approximation.
     * @param pACtps_ All tps prices [PREC]
     * @return tcAvailableToRedeem [N]
     */
    function calcTCAvailableToRedeem(uint256[] memory pACtps_) public view returns (uint256 tcAvailableToRedeem) {
        uint256 ctargemaCA = _calcCtargemaCA(pACtps_);
        (uint256 lckAC, uint256 nACgain) = _calcLckACandACgain(pACtps_);
        return _getTCAvailableToRedeem(ctargemaCA, lckAC, nACgain);
    }

    /**
     * @notice gets amount of Pegged Token available to mint signed
     * @dev because it is a view function we are not calculating the new ema,
     *  since we are using the last ema calculation, this may differ a little from the real amount
     *  of TP available to mint. Consider it an approximation.
     * @param tp_ Pegged Token address
     * @return tpAvailableToMintSigned [N]
     */
    function getTPAvailableToMint(address tp_) external view returns (int256 tpAvailableToMintSigned) {
        return calcTPAvailableToMint(tp_, _getPACtps());
    }

    /**
     * @notice calc amount of Pegged Token available to mint signed given an array of TP prices
     * @dev because it is a view function we are not calculating the new ema,
     *  since we are using the last ema calculation, this may differ a little from the real amount
     *  of TP available to mint. Consider it an approximation.
     * @param tp_ Pegged Token address
     * @param pACtps_ All tps prices [PREC]
     * @return tpAvailableToMintSigned [N]
     */
    function calcTPAvailableToMint(
        address tp_,
        uint256[] memory pACtps_
    ) public view returns (int256 tpAvailableToMintSigned) {
        uint256 ctargemaCA = _calcCtargemaCA(pACtps_);
        (uint256 lckAC, uint256 nACgain) = _calcLckACandACgain(pACtps_);
        uint256 i = _tpi(tp_);
        uint256 pACtp = pACtps_[i];
        return _getTPAvailableToMintSigned(ctargemaCA, _getCtargemaTP(i, pACtp, protThrld), pACtp, lckAC, nACgain);
    }

    /**
     * @notice gets total Collateral Asset available
     * @return totalACavailable [N]
     */
    function getTotalACavailable() external view returns (uint256 totalACavailable) {
        (, uint256 nACgain) = _getLckACandACgain(_getPACtps());
        return _getTotalACavailable(nACgain);
    }

    /**
     * @notice returns true if bucket can be liquidated
     */
    function isLiquidationAvailable() external view returns (bool) {
        return liqEnabled && !liquidated && isLiquidationReached();
    }

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */

    // Purposely left unused to save some state space to allow for future upgrades
    // slither-disable-next-line unused-state
    uint256[50] private __gap;
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import { MocCommons, PeggedTokenParams } from "./MocCommons.sol";
import { IMocRC20 } from "../interfaces/IMocRC20.sol";
import { IMocMultiCollateralGuard } from "../interfaces/IMocMultiCollateralGuard.sol";
import { IPriceProvider } from "../interfaces/IPriceProvider.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title MocCoreExpansion
 * @notice This contract is used as an expansion of MocCore because 24kb size limitation
 *  MocCore delegate some function calls to it.
 * @dev IMPORTANT NOTES:
 *  1. MocCore and MocCoreExpansion must have always the same storage layout to avoid collisions
 *  2. Because MocCore is upgradeable and delegates calls to MocCoreExpansion, it cannot be upgradeable because
 *      a proxy contract cannot delegate calls to another proxy contract. So, for any MocCoreExpansion upgrade
 *      you must deploy a new implementation and set it to MocCore.
 */
contract MocCoreExpansion is MocCommons {
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice add a Pegged Token to the protocol
     * @dev Note that the ema value, should consider `nextEmaCalculation`
     *  This function is called by MocCore contract using it's context with delegate call
     *  Checks done there:
     *  -  onlyAuthorizedChanger: the caller must have governance authorization.
     * @param tpToken_ Pegged Token contract to add
     *  peggedTokenParams_ params of Pegged Token to add:
     *      priceProviderAddress Pegged Token price provider contract address
     *      tpCtarg Pegged Token target coverage [PREC]
     *      tpMintFee additional fee pct applied on mint [PREC]
     *      tpRedeemFee additional fee pct applied on redeem [PREC]
     *      tpEma initial Pegged Token exponential moving average [PREC]
     *      tpEmaSf Pegged Token smoothing factor [PREC]
     * @dev Pegged Token should be added using the corresponding changer template, which
     *      should guarantee that it is added on all the buckets(mandatory for multiCollateral)
     *
     *  Requirements:
     *
     *  - tpTokenAddress must be a MocRC20, with mint, burn roles already settled
     *  for this contract
     */
    function addPeggedToken(IMocRC20 tpToken_, PeggedTokenParams calldata peggedTokenParams_) external {
        IPriceProvider priceProvider = IPriceProvider(peggedTokenParams_.priceProviderAddress);

        if (peggedTokenIndex[address(tpToken_)].exists) revert PeggedTokenAlreadyAdded();
        uint256 newTPindex = uint256(tpTokens.length);
        peggedTokenIndex[address(tpToken_)] = PeggedTokenIndex({ index: newTPindex, exists: true });

        // set Pegged Token address
        tpTokens.push(tpToken_);
        // set peg container item
        pegContainer.push(PegContainerItem({ nTP: 0, priceProvider: priceProvider }));
        // set target coverage
        tpCtarg.push(peggedTokenParams_.tpCtarg);
        // set mint fee pct
        tpMintFees[address(tpToken_)] = peggedTokenParams_.tpMintFee;
        // set redeem fee pct
        tpRedeemFees[address(tpToken_)] = peggedTokenParams_.tpRedeemFee;
        // set EMA initial value and smoothing factor
        tpEma.push(EmaItem({ ema: peggedTokenParams_.tpEma, sf: peggedTokenParams_.tpEmaSf }));
        tpiou.push();

        /**
         * Price providers may not be valid at the time of adding a
         * pegged token, so we initialize the last token price with a fixed value.
         * This value should be realistic, otherwise it would momentarily affect the
         * successFee calculation when the protocol starts operating.
         */
        pACtpLstop.push(peggedTokenParams_.tpEma);
        // emit the event
        emit PeggedTokenChange(newTPindex, address(tpToken_), peggedTokenParams_);
    }

    /**
     * @notice modifies a Pegged Token of the protocol
     * @dev Note that the ema value, should consider `nextEmaCalculation`
     *  This function is called by MocCore contract using it's context with delegate call
     *  Checks done there:
     *  -  onlyAuthorizedChanger: the caller must have governance authorization.
     * @param tpToken_ Pegged Token contract to edit
     *  peggedTokenParams_ params of Pegged Token to edit:
     *      priceProviderAddress Pegged Token price provider contract address
     *      tpCtarg Pegged Token target coverage [PREC]
     *      tpMintFee additional fee pct applied on mint [PREC]
     *      tpRedeemFee additional fee pct applied on redeem [PREC]
     *      tpEma initial Pegged Token exponential moving average [PREC]
     *      tpEmaSf Pegged Token smoothing factor [PREC]
     *
     *  Requirements:
     *
     * - the tpTokenAddress must exists
     */
    function editPeggedToken(IMocRC20 tpToken_, PeggedTokenParams calldata peggedTokenParams_) external {
        PeggedTokenIndex memory ptIndex = peggedTokenIndex[address(tpToken_)];
        if (!ptIndex.exists) revert InvalidAddress();
        uint256 i = ptIndex.index;
        pegContainer[i].priceProvider = IPriceProvider(peggedTokenParams_.priceProviderAddress);
        // set target coverage
        tpCtarg[i] = peggedTokenParams_.tpCtarg;
        // set mint fee pct
        tpMintFees[address(tpToken_)] = peggedTokenParams_.tpMintFee;
        // set redeem fee pct
        tpRedeemFees[address(tpToken_)] = peggedTokenParams_.tpRedeemFee;
        // set EMA initial value and smoothing factor
        tpEma[i].sf = peggedTokenParams_.tpEmaSf;
        // emit the event
        emit PeggedTokenChange(i, address(tpToken_), peggedTokenParams_);
    }

    /**
     * @dev Calculates price at liquidation event as a relation between Pegs total supply
     * and the amount of Asset Collateral available to distribute
     */
    function settleLiquidationPrices() external {
        // Total amount of AC available to be redeemed
        uint256 totalACAvailable = nACcb;
        // slither-disable-next-line incorrect-equality
        if (totalACAvailable == 0) return;
        uint256 pegAmount = pegContainer.length;
        // this could be get by getLckAC(), but given the prices are needed after,
        // it's better to cache them here.
        uint256 lckAC;
        // Auxiliary cache of pegs pACtp
        uint256[] memory pACtps = new uint256[](pegAmount);
        // for each peg, calculates the proportion of AC reserves it's locked

        for (uint256 i = 0; i < pegAmount; i = unchecked_inc(i)) {
            pACtps[i] = _getPACtp(i);
            // [N] = [N] * [PREC] / [PREC]
            lckAC += _divPrec(pegContainer[i].nTP, pACtps[i]);
        }
        for (uint256 i = 0; i < pegAmount; i = unchecked_inc(i)) {
            // [PREC] = [PREC] * [N] / [N];
            tpLiqPrices.push((pACtps[i] * lckAC) / totalACAvailable);
        }
    }

    /**
     * @notice Allow redeem on liquidation state, user Peg balance gets burned
     * @dev This function is called by MocCore contract using it's context with delegate call
     *  The equivalent AC given the liquidation frozen price(qACRedeemed) is transferred
     *  to the `recipient_` by MocCore contract
     *  Checks done there:
     *  -  notPaused: the contract must be unpaused
     * @param tp_ Pegged Token address
     * @param sender_ address owner of the TP to be redeemed
     * @param recipient_ address who receives the AC
     * @return qACRedeemed amount of AC sent to `recipient_`
     */
    function liqRedeemTP(
        address tp_,
        address sender_,
        address recipient_,
        uint256 mocACBalance
    ) external returns (uint256 qACRedeemed) {
        if (!liquidated) revert OnlyWhenLiquidated();
        uint256 i = _tpi(tp_);
        uint256 qTP = tpTokens[i].balanceOf(sender_);
        // slither-disable-next-line incorrect-equality
        if (qTP == 0) revert InsufficientTPtoRedeem(qTP, qTP);
        // [PREC]
        uint256 liqPACtp = tpLiqPrices[i];
        // [PREC] = [N] * [PREC] / [PREC]
        qACRedeemed = _divPrec(qTP, liqPACtp);
        // Given rounding errors, the last redeemer might receive a little less
        if (mocACBalance < qACRedeemed) qACRedeemed = mocACBalance;
        // in liquidation doesn't pay fees or markup
        // qACfee, qFeeToken, qACVendorMarkup, qFeeTokenVendorMarkup  = (0, 0, 0, 0)
        emit LiqTPRedeemed(tp_, sender_, recipient_, qTP, qACRedeemed);
        // burn qTP from the sender
        tpTokens[i].burn(sender_, qTP);
    }

    /**
     * @notice mint Collateral Token and Pegged Token in exchange for Collateral Asset
     *  This operation is done without checking coverage
     *  Collateral Token and Pegged Token are minted in equivalent proportions so that its price
     *  and global coverage are not modified.
     *  Reverts if qAC sent are insufficient.
     * @param params_ mint TC and TP function parameters
     * @dev
     *      i_ Pegged Token index
     *      qTP_ amount of Pegged Token to mint
     *      qACmax_ maximum amount of Collateral Asset that can be spent
     *      sender_ address who sends Collateral Asset
     *      recipient_ address who receives the Collateral Token and Pegged Token
     *      vendor_ address who receives a markup. If its address(0) no markup is applied
     * @return qACtoMintTC amount of AC used to mint Collateral Token
     * @return qACtoMintTP amount of AC used to mint Pegged Token
     * @return qACtoSpent total amount of AC spent by `sender_` for TC and TP mint plus fees
     * @return qTCtoMint amount of Collateral Token minted
     * @return feeCalcs platform fee detail breakdown
     */
    function mintTCandTPto(
        MintTCandTPParams memory params_
    )
        external
        payable
        returns (
            uint256 qACtoMintTC,
            uint256 qACtoMintTP,
            uint256 qACtoSpent,
            uint256 qTCtoMint,
            FeeCalcs memory feeCalcs
        )
    {
        uint256[] memory pACtps = _getPACtps();
        uint256 localProtThrld = protThrld;
        uint256 i = _tpi(params_.tp);
        uint256 pACtp = pACtps[i];
        _updateTPtracking(i, pACtp);
        // evaluates whether or not the system coverage is healthy, reverts if it's not
        (uint256 lckAC, uint256 nACgain) = _evalCoverage(localProtThrld, pACtps);
        (qTCtoMint, qACtoMintTC, qACtoMintTP) = _calcQACforMintTCandTP(
            params_.qTP,
            pACtp,
            _getCtargemaTP(i, pACtp, localProtThrld),
            _getPTCac(lckAC, nACgain)
        );
        uint256 qACNeededtoMint = qACtoMintTC + qACtoMintTP;
        uint256 qACSurcharges;
        (qACSurcharges, feeCalcs) = _calcFees(params_.sender, params_.vendor, qACNeededtoMint, mintTCandTPFee);
        qACtoSpent = qACNeededtoMint + qACSurcharges;
        if (qACtoSpent > params_.qACmax) revert InsufficientQacSent(params_.qACmax, qACtoSpent);
        // if is 0 reverts because it is trying to mint an amount below precision
        // slither-disable-next-line incorrect-equality
        if (qACtoSpent == 0) revert QacNeededMustBeGreaterThanZero();
        // update flux capacitor and reverts if not allowed by accumulators
        _updateAccumulatorsOnMintTP(qACtoMintTP);
        _depositAndMintTC(qTCtoMint, qACNeededtoMint, params_.recipient);
        _depositAndMintTP(i, params_.qTP, 0, params_.recipient);
    }

    /**
     * @notice redeem Collateral Asset in exchange for Collateral Token and Pegged Token
     *  This operation is done without checking coverage
     *  Collateral Token and Pegged Token are redeemed in equivalent proportions so that its price
     *  and global coverage are not modified.
     *  Reverts if qTC sent are insufficient.
     * @param params_ redeem TC and TP function parameters
     * @dev
     *      i_ Pegged Token index
     *      qTC_ maximum amount of Collateral Token to redeem
     *      qTP_ amount of Pegged Token to redeem
     *      qACmin_ minimum amount of Collateral Asset that `recipient_` expects to receive
     *      sender_ address who sends Collateral Token and Pegged Token
     *      recipient_ address who receives the Collateral Asset
     *      vendor_ address who receives a markup. If its address(0) no markup is applied
     * @return qACtoRedeemTC amount of AC sent to `recipient_` for Collateral Token redemption
     * @return qACtoRedeemTP amount of AC sent to `recipient_` for Pegged Token redemption
     * @return qACtoReceive total amount of AC sent to `recipient_` for TC and TP redemption minus fees
     * @return qTCtoRedeem amount of Collateral Token redeemed
     * @return feeCalcs platform fee detail breakdown
     */
    function redeemTCandTPto(
        RedeemTCandTPParams memory params_
    )
        external
        payable
        returns (
            uint256 qACtoRedeemTC,
            uint256 qACtoRedeemTP,
            uint256 qACtoReceive,
            uint256 qTCtoRedeem,
            FeeCalcs memory feeCalcs
        )
    {
        IMocMultiCollateralGuard mocMultiCollateralGuard = _getMocMultiCollateralGuard();
        // emas are updated here
        (uint256 combinedCglb, uint256 combinedCtargemaCA, uint256[] memory pACtps) = mocMultiCollateralGuard
            .getCombinedValues(address(this));

        uint256 i = _tpi(params_.tp);
        uint256 pACtp = pACtps[i];
        _updateTPtracking(i, pACtp);

        uint256 ctargemaCA = _calcCtargemaCA(pACtps);
        (uint256 lckAC, uint256 nACgain) = _getLckACandACgain(pACtps);
        uint256 cglb = _getCglb(lckAC, nACgain);

        if (cglb <= ONE) {
            if (mocMultiCollateralGuard.getBucketAmount() > 1) revert OnlyWhenLastBucket();
            // [PREC] = [PREC] * [N] / [N]
            uint256 acAvailable = _getTotalACavailable(nACgain);
            uint256 tpPrice = (pACtp * lckAC) / acAvailable;
            qACtoRedeemTP = _divPrec(params_.qTP, tpPrice);
            // limit qACtoRedeem to do not revert because of rounding errors
            qACtoRedeemTP = Math.min(qACtoRedeemTP, acAvailable);
            // [N] = [N] * [N] / [N]
            qTCtoRedeem = (nTCcb * qACtoRedeemTP) / acAvailable;
            qACtoRedeemTC = 0;
        } else {
            if (combinedCglb <= ONE) revert LowCombinedCoverage();
            uint256 ctargemaTPMinusONE = _getCtargemaTP(i, pACtp, protThrld) - ONE;
            uint256 score = ((cglb - ONE) * ctargemaTPMinusONE) / (ctargemaCA - ONE);
            uint256 combinedScore = ((combinedCglb - ONE) * ctargemaTPMinusONE) / (combinedCtargemaCA - ONE);
            // [PREC] = [PREC] * [PREC] / [PREC]
            uint256 redeemProportion = Math.min(score, combinedScore);
            // calculate how many qAC are redeemed for TP
            // [N] = [N] * [PREC] / [PREC]
            qACtoRedeemTP = _divPrec(params_.qTP, pACtp);
            // calculate how many qAC are redeemed for TC
            // [N] = [N] * [PREC] / [PREC]
            qACtoRedeemTC = (params_.qTP * redeemProportion) / pACtp;
            // [N] = [N] * [N] * [PREC] / [N] * [PREC]
            qTCtoRedeem = (params_.qTP * redeemProportion * nTCcb) / ((_getTotalACavailable(nACgain) - lckAC) * pACtp);
        }

        // if is 0 reverts because it is trying to redeem an amount of TP or TC below precision
        // slither-disable-next-line incorrect-equality
        if (qACtoRedeemTP == 0 || qTCtoRedeem == 0) revert QacNeededMustBeGreaterThanZero();
        if (qTCtoRedeem > params_.qTC) revert InsufficientQtcSent(params_.qTC, qTCtoRedeem);
        uint256 qACtotalToRedeem = qACtoRedeemTC + qACtoRedeemTP;
        uint256 qACSurcharges;
        (qACSurcharges, feeCalcs) = _calcFees(params_.sender, params_.vendor, qACtotalToRedeem, redeemTCandTPFee);
        qACtoReceive = qACtotalToRedeem - qACSurcharges;
        if (qACtoReceive < params_.qACmin) revert QacBelowMinimumRequired(params_.qACmin, qACtoReceive);
        // update flux capacitor and reverts if not allowed by accumulators
        _updateAccumulatorsOnRedeemTP(qACtoRedeemTP);
        _withdrawAndBurnTC(qTCtoRedeem, qACtotalToRedeem);
        _withdrawAndBurnTP(i, params_.qTP, 0);
    }

    /**
     * @notice swap Pegged Token to another one
     *  This operation is done without checking coverage unless the target coverage for
     *  received Pegged Token is greater than the Pegged Token sent
     * @dev This function is called by MocCore contract using it's context with delegate call
     * @param params_ swap TP for TP function parameters
     * @dev
     *      iFrom_ owned Pegged Token index
     *      iTo_ target Pegged Token index
     *      qTP_ amount of owned Pegged Token to swap
     *      qTPmin_ minimum amount of target Pegged Token that `recipient_` expects to receive
     *      qACmax_ maximum amount of Collateral Asset that can be spent in fees
     *      sender_ address who sends the Pegged Token
     *      recipient_ address who receives the target Pegged Token
     *      vendor_ address who receives a markup. If its address(0) no markup is applied
     * @return qACSurcharges amount of AC used to pay fees and markup
     * @return qTPtoMint amount of Pegged Token minted
     * @return feeCalcs struct with:
     * @dev
     *      qACFee amount of AC needed to pay fees
     *      qFeeToken amount of Fee Token needed to pay fess
     *      qACVendorMarkup amount of AC needed to pay vendor markup
     *      qFeeTokenVendorMarkup amount of Fee Token needed to pay vendor markup
     */
    function swapTPforTPto(
        SwapTPforTPParams memory params_
    ) external payable returns (uint256 qACSurcharges, uint256 qTPtoMint, FeeCalcs memory feeCalcs) {
        if (params_.tpFrom == params_.tpTo) revert InvalidValue();
        uint256[] memory pACtps = _getPACtps();
        uint256 iFrom = _tpi(params_.tpFrom);
        uint256 iTo = _tpi(params_.tpTo);
        uint256 pACtpFrom = pACtps[iFrom];
        uint256 pACtpTo = pACtps[iTo];
        uint256 localProtThrld = protThrld;
        _updateTPtracking(iFrom, pACtpFrom);
        _updateTPtracking(iTo, pACtpTo);
        // calculate how many total qAC are redeemed
        // [N] = [N] * [PREC] / [PREC]
        uint256 qACtotalToRedeem = _divPrec(params_.qTP, pACtpFrom);
        // calculate how many qTP can mint with the given qAC
        // [N] = [N] * [PREC] / [PREC]
        qTPtoMint = (params_.qTP * pACtpTo) / pACtpFrom;
        if (qTPtoMint < params_.qTPmin || qTPtoMint == 0) revert QtpBelowMinimumRequired(params_.qTPmin, qTPtoMint);

        bool ctargemaTPRelation = _getCtargemaTP(iTo, pACtpTo, localProtThrld) >
            _getCtargemaTP(iFrom, pACtpFrom, localProtThrld);
        // if ctargemaTPto > ctargemaTPfrom we need to check coverage
        if (ctargemaTPRelation) {
            // emas are updated here and multi collateral status evaluated, reverts if it is not healthy enough
            (uint256 tpAvailableToMint, ) = _getMocMultiCollateralGuard().getCombinedAndTP(address(this), params_.tpTo);

            uint256 ctargemaCA = _calcCtargemaCA(pACtps);
            // evaluates whether or not the system coverage is healthy enough to mint TP
            // given the target coverage adjusted by the moving average, reverts if it's not
            _evalCoverage(ctargemaCA, pACtps);
            // evaluates if there are enough TP available to mint, reverts if it's not
            _evalTPavailableToMint(qTPtoMint, tpAvailableToMint);
        }
        (qACSurcharges, feeCalcs) = _calcFees(params_.sender, params_.vendor, qACtotalToRedeem, swapTPforTPFee);
        if (qACSurcharges > params_.qACmax) revert InsufficientQacSent(params_.qACmax, feeCalcs.qACFee);
        _depositAndMintTP(iTo, qTPtoMint, 0, params_.recipient);
        _withdrawAndBurnTP(iFrom, params_.qTP, 0);
    }

    /**
     * @notice swap Pegged Token to Collateral Token
     * @dev This function is called by MocCore contract using it's context with delegate call
     * @param params_ swap TP for TC function parameters
     * @dev
     *      i_ Pegged Token index
     *      qTP_ amount Pegged Token to swap
     *      qTCmin_ minimum amount of Collateral Token that `recipient_` expects to receive
     *      qACmax_ maximum amount of Collateral Asset that can be spent in fees
     *      sender_ address who sends the Pegged Token
     *      recipient_ address who receives Collateral Token
     *      vendor_ address who receives a markup. If its address(0) no markup is applied
     * @return qACSurcharges amount of AC used to pay fees and markup
     * @return qTCtoMint amount of Collateral Token minted
     * @return feeCalcs struct with:
     * @dev
     *      qACFee amount of AC needed to pay fees
     *      qFeeToken amount of Fee Token needed to pay fess
     *      qACVendorMarkup amount of AC needed to pay vendor markup
     *      qFeeTokenVendorMarkup amount of Fee Token needed to pay vendor markup
     */
    function swapTPforTCto(
        SwapTPforTCParams memory params_
    ) external payable returns (uint256 qACSurcharges, uint256 qTCtoMint, FeeCalcs memory feeCalcs) {
        uint256[] memory pACtps = _getPACtps();
        uint256 i = _tpi(params_.tp);
        uint256 pACtp = pACtps[i];
        _updateTPtracking(i, pACtp);
        // evaluates whether or not the system coverage is healthy enough to mint TC, reverts if it's not
        (uint256 lckAC, uint256 nACgain) = _evalCoverage(protThrld, pACtps);
        // calculate how many total qAC are redeemed TP
        // [N] = [N] * [PREC] / [PREC]
        uint256 qACtotalToRedeem = _divPrec(params_.qTP, pACtp);
        // calculate how many qTC can mint with the given qAC
        // qTCtoMint = qTP / pTCac / pACtp
        // [N] = [N] * [N] * [PREC] / ([N] - [N]) * [PREC]
        qTCtoMint = _divPrec(params_.qTP * nTCcb, (_getTotalACavailable(nACgain) - lckAC) * pACtp);
        // slither-disable-next-line incorrect-equality
        if (qTCtoMint < params_.qTCmin || qTCtoMint == 0) revert QtcBelowMinimumRequired(params_.qTCmin, qTCtoMint);

        (qACSurcharges, feeCalcs) = _calcFees(params_.sender, params_.vendor, qACtotalToRedeem, swapTPforTCFee);
        if (qACSurcharges > params_.qACmax) revert InsufficientQacSent(params_.qACmax, feeCalcs.qACFee);
        // update flux capacitor and reverts if not allowed by accumulators
        _updateAccumulatorsOnRedeemTP(qACtotalToRedeem);
        _withdrawAndBurnTP(i, params_.qTP, 0);
        _depositAndMintTC(qTCtoMint, 0, params_.recipient);
    }

    /**
     * @notice swap Collateral Token to Pegged Token
     * @dev This function is called by MocCore contract using it's context with delegate call
     * @param params_ swap TC for TP function parameters
     * @dev
     *      i_ Pegged Token index
     *      qTC_ amount of Collateral Token to swap
     *      qTPmin_ minimum amount of Pegged Token Token that `recipient_` expects to receive
     *      qACmax_ maximum amount of Collateral Asset that can be spent in fees
     *      sender_ address who sends the Collateral Token
     *      recipient_ address who receives the Pegged Token
     *      vendor_ address who receives a markup. If its address(0) no markup is applied
     * @return qACSurcharges amount of AC used to pay fees and markup
     * @return qTPtoMint amount of Pegged Token minted
     * @dev
     *      qACFee amount of AC needed to pay fees
     *      qFeeToken amount of Fee Token needed to pay fess
     *      qACVendorMarkup amount of AC needed to pay vendor markup
     *      qFeeTokenVendorMarkup amount of Fee Token needed to pay vendor markup
     */
    function swapTCforTPto(
        SwapTCforTPParams memory params_
    ) external payable returns (uint256 qACSurcharges, uint256 qTPtoMint, FeeCalcs memory feeCalcs) {
        // emas are updated here and multi collateral status evaluated, reverts if it is not healthy enough
        (
            uint256 tcAvailableToRedeem,
            uint256 tpAvailableToMint,
            uint256[] memory pACtps
        ) = _getMocMultiCollateralGuard().getCombinedAndTCAndTP(address(this), params_.tp);

        uint256 ctargemaCA = _calcCtargemaCA(pACtps);
        uint256 i = _tpi(params_.tp);
        uint256 pACtp = pACtps[i];
        _updateTPtracking(i, pACtp);
        // evaluates whether or not the system coverage is healthy enough to redeem TC and mint TP
        // given the target coverage adjusted by the moving average, reverts if it's not
        (uint256 lckAC, uint256 nACgain) = _evalCoverage(ctargemaCA, pACtps);
        // evaluates if there are enough Collateral Tokens available to redeem, reverts if there are not
        _evalTCAvailableToRedeem(params_.qTC, tcAvailableToRedeem);
        // calculate how many total qAC are redeemed
        // [N] = [N] * [PREC] / [PREC]
        uint256 qACtotalToRedeem = _mulPrec(params_.qTC, _getPTCac(lckAC, nACgain));
        // if is 0 reverts because it is trying to swap an amount below precision
        // slither-disable-next-line incorrect-equality
        if (qACtotalToRedeem == 0) revert QacNeededMustBeGreaterThanZero();
        // calculate how many qTP can mint with the given qAC
        // qTPtoMint = qTC * pTCac * pACtp
        // [N] = ([N] * ([N] - [N]) * [PREC] / [N]) / [PREC]
        qTPtoMint = ((params_.qTC * (_getTotalACavailable(nACgain) - lckAC) * pACtp) / nTCcb) / PRECISION;
        // evaluates if there are enough TP available to mint, reverts if it's not
        _evalTPavailableToMint(qTPtoMint, tpAvailableToMint);
        if (qTPtoMint < params_.qTPmin) revert QtpBelowMinimumRequired(params_.qTPmin, qTPtoMint);

        (qACSurcharges, feeCalcs) = _calcFees(params_.sender, params_.vendor, qACtotalToRedeem, swapTCforTPFee);
        if (qACSurcharges > params_.qACmax) revert InsufficientQacSent(params_.qACmax, feeCalcs.qACFee);
        // update flux capacitor and reverts if not allowed by accumulators
        _updateAccumulatorsOnMintTP(qACtotalToRedeem);
        _withdrawAndBurnTC(params_.qTC, 0);
        _depositAndMintTP(i, qTPtoMint, 0, params_.recipient);
    }

    /**
     * @notice calculate how many Collateral Asset are needed to mint an amount of Collateral Token
     * and Pegged Token in one operation
     * @param qTP_ amount of Pegged Token to mint
     * @param pACtp_ Pegged Token price [PREC]
     * @param ctargemaTP_ target coverage adjusted by the moving average of the value of a Pegged Token
     * @param pTCac_ Collateral Token price [PREC]
     * @return qTCtoMint amount of Collateral Token to mint [N]
     * @return qACtoMintTC amount of Collateral Asset needed to mint Collateral Token [N]
     * @return qACtoMintTP amount of Collateral Asset used to mint Pegged Token [N]
     */
    function _calcQACforMintTCandTP(
        uint256 qTP_,
        uint256 pACtp_,
        uint256 ctargemaTP_,
        uint256 pTCac_
    ) internal pure returns (uint256 qTCtoMint, uint256 qACtoMintTC, uint256 qACtoMintTP) {
        // calculate how many TC are needed to mint TP and total qAC used for mint both
        // [N] = [N] * ([PREC] - [PREC]) / [PREC]
        qACtoMintTC = (qTP_ * (ctargemaTP_ - ONE)) / pACtp_;
        // [N] = [N] *  [PREC] / [PREC]
        qTCtoMint = _divPrec(qACtoMintTC, pTCac_);
        // [N] = [N] *  [PREC] / [PREC]
        qACtoMintTP = _divPrec(qTP_, pACtp_);
        return (qTCtoMint, qACtoMintTC, qACtoMintTP);
    }

    /**
     * @notice calculate how many Collateral Asset are needed to redeem an amount of Collateral Token
     * and Pegged Token in one operation
     * @param qTC_ amount of Collateral Token to redeem
     * @param qTP_ amount of Pegged Token to redeem
     * @param pACtp_ Pegged Token price [PREC]
     * @param pTCac_ Collateral Token price [PREC]
     * @return qACtoRedeemTC amount of Collateral Asset needed to redeem Collateral Token [N]
     * @return qACtoRedeemTP amount of Collateral Asset used to redeem Pegged Token [N]
     */
    function _calcQACforRedeemTCandTP(
        uint256 qTC_,
        uint256 qTP_,
        uint256 pACtp_,
        uint256 pTCac_
    ) internal pure returns (uint256 qACtoRedeemTC, uint256 qACtoRedeemTP) {
        // calculate how many total qAC are redeemed
        // [N] = [N] * [PREC] / [PREC]
        qACtoRedeemTP = _divPrec(qTP_, pACtp_);
        // if is 0 reverts because it is trying to redeem an amount of TP below precision
        // we check it here to prevent qTP == 0 && qTC != 0
        // slither-disable-next-line incorrect-equality
        if (qACtoRedeemTP == 0) revert QacNeededMustBeGreaterThanZero();
        // calculate how many qAC are redeemed because TC
        // [N] = [N] * [PREC] / [PREC]
        qACtoRedeemTC = _mulPrec(qTC_, pTCac_);
        return (qACtoRedeemTC, qACtoRedeemTP);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import { MocBaseBucket } from "./MocBaseBucket.sol";

/**
 * @title MocEma: Exponential Moving Average
 * @notice Moc Ema, provides a set of methods that allows to calculate and track
 * Exponential Moving Average for each of the pegged Tokens.
 * @dev More information of EMA calculation https://en.wikipedia.org/wiki/Exponential_smoothing
 */
abstract contract MocEma is MocBaseBucket {
    // ------- Events -------
    event TPemaUpdated(uint256 indexed i_, uint256 oldTPema_, uint256 newTPema_);

    // ------- Structs -------
    struct EmaItem {
        // exponential moving average
        uint256 ema;
        // smoothing factor
        uint256 sf;
    }

    // ------- Storage -------
    // TP EMA items, indexes are in sync with PeggedTokens across Moc solution
    EmaItem[] public tpEma;
    // next ema calculation time
    uint256 public nextEmaCalculation;
    // amount of seconds to wait for next ema calculation
    uint256 public emaCalculationTimeSpan;

    /**
     * @notice calculates exponential moving average of the value of a Pegged Token
     * @dev more information of EMA calculation https://en.wikipedia.org/wiki/Exponential_smoothing
     * @param currentTPema_ current Ema value
     * @param pACtp_ current tp AC price
     */
    function _calcNewEma(EmaItem memory currentTPema_, uint256 pACtp_) private pure returns (uint256) {
        // [PREC²] = [PREC] * ([PREC] - [PREC])
        uint256 term1 = currentTPema_.ema * (ONE - currentTPema_.sf);
        // [PREC²] = [PREC] * [PREC]
        uint256 term2 = currentTPema_.sf * pACtp_;
        // [PREC] = ([PREC²] + [PREC²]) / [PREC]
        return (term1 + term2) / PRECISION;
    }

    // ------- Initializer -------
    /**
     * @notice contract initializer
     * @param emaCalculationTimeSpan_ amount of seconds to wait between Pegged ema calculation
     */
    function __MocEma_init_unchained(uint256 emaCalculationTimeSpan_) internal onlyInitializing {
        emaCalculationTimeSpan = emaCalculationTimeSpan_;
        _updateNextEmaCalculation(emaCalculationTimeSpan_);
    }

    // ------- Internal Functions -------

    /**
     * @notice updates next EMA calculation
     * @param emaCalculationTimeSpan_ amount of seconds to wait between Pegged ema calculation
     */
    function _updateNextEmaCalculation(uint256 emaCalculationTimeSpan_) internal {
        unchecked {
            nextEmaCalculation = block.timestamp + emaCalculationTimeSpan_;
        }
    }

    /**
     * @notice get target coverage adjusted by the moving average of the value of a Pegged Token
     * @param i_ Pegged Token index
     * @param pACtp_ Pegged Token price [PREC]
     * @return ctargemaTP [PREC]
     */
    function _getCtargemaTP(uint256 i_, uint256 pACtp_, uint256 protThrld_) internal view returns (uint256 ctargemaTP) {
        uint256 auxTpEma = tpEma[i_].ema;
        if (shouldCalculateEma()) auxTpEma = _calcNewEma(tpEma[i_], pACtp_);
        // [PREC] = ((([PREC] - [PREC]) * [PREC]) / [PREC]) + [PREC]
        uint256 computedCtargemaTP = (((tpCtarg[i_] - ONE) * pACtp_) / auxTpEma) + ONE;
        return computedCtargemaTP > protThrld_ ? computedCtargemaTP : protThrld_;
    }

    /**
     * @notice update exponential moving average of the value of a Pegged Token
     * @param i_ Pegged Token index
     * @param pACtp_ tp price [PREC]
     */
    function _updateTPema(uint256 i_, uint256 pACtp_) internal {
        EmaItem memory currentTPema = tpEma[i_];
        uint256 newEma = _calcNewEma(currentTPema, pACtp_);
        // save new ema value to storage
        tpEma[i_].ema = newEma;
        emit TPemaUpdated(i_, currentTPema.ema, newEma);
    }

    /**
     * @notice calculates CA target coverage, adjusted by all Pegged Token's to
     *  Collateral Asset last stored moving average price
     * @dev WARN: if EMA are not up to date, the resulting coverage might not reflect real spot value
     *      qAC = (nTP + tpGain) / pACtp
     *      ctargemaCA = ∑(ctargemaTP * qAC) / ∑(qAC)
     * @param pACtps_ All tps prices [PREC]
     * @return ctargemaCA [PREC]
     */
    function _calcCtargemaCA(uint256[] memory pACtps_) internal view returns (uint256 ctargemaCA) {
        uint256 num;
        uint256 den;
        uint256 localProtThrld = protThrld;
        uint256 pegAmount = pegContainer.length;
        for (uint256 i = 0; i < pegAmount; i = unchecked_inc(i)) {
            uint256 pACtp = pACtps_[i];
            (uint256 tpGain, ) = _getPnLTP(i, pACtp);
            // [PREC] = [N] * [PREC] * [PREC]  / [PREC]
            uint256 qAC = _divPrec((pegContainer[i].nTP + tpGain) * PRECISION, pACtp);
            // [PREC]^2 = [PREC] * [PREC]
            num += _getCtargemaTP(i, pACtp, localProtThrld) * qAC;
            // [PREC] = [PREC]
            den += qAC;
        }
        // we must return a default value when all nTP are 0
        // slither-disable-next-line incorrect-equality
        if (den == 0) {
            unchecked {
                return (localProtThrld * 2);
            }
        }
        // [PREC] = ([PREC]^2) / [PREC]
        ctargemaCA = num / den;
    }

    // ------- Public Functions -------

    /**
     * @notice calculates target coverage adjusted by all Pegged Token's to Collateral Asset rate moving average
     * @dev qAC = nTP / pACtp
     *      ctargemaCA = ∑(ctargemaTP * qAC) / ∑(qAC)
     * @return ctargemaCA [PREC]
     */
    function getCtargemaCA() external view returns (uint256 ctargemaCA) {
        return _calcCtargemaCA(_getPACtps());
    }

    /**
     * @notice calculates target coverage adjusted by all Pegged Token's to Collateral Asset rate moving average
     * @dev qAC = nTP / pACtp
     *      ctargemaCA = ∑(ctargemaTP * qAC) / ∑(qAC)
     * @param pACtps_ All tps prices [PREC]
     * @return ctargemaCA [PREC]
     */
    function calcCtargemaCA(uint256[] memory pACtps_) external view returns (uint256 ctargemaCA) {
        return _calcCtargemaCA(pACtps_);
    }

    /**
     * @notice calculates target coverage adjusted by the moving average of the value of a Pegged Token
     * @param tp_ Pegged Token address
     * @return ctargemaTP [PREC]
     */
    function getCtargemaTP(address tp_) external view returns (uint256 ctargemaTP) {
        uint256 i = _tpi(tp_);
        return _getCtargemaTP(i, _getPACtp(i), protThrld);
    }

    /**
     * @notice calculates target coverage adjusted by the moving average of the value of a Pegged Token
     * @param tp_ Pegged Token address
     * @param pACtp_ tp price [PREC]
     * @return ctargemaTP [PREC]
     */
    function calcCtargemaTP(address tp_, uint256 pACtp_) external view returns (uint256 ctargemaTP) {
        return _getCtargemaTP(_tpi(tp_), pACtp_, protThrld);
    }

    /**
     * @notice true if the necessary span has pass since last ema update
     */
    function shouldCalculateEma() public view returns (bool) {
        unchecked {
            return block.timestamp >= nextEmaCalculation;
        }
    }

    /**
     * @notice If time, calculates the EMA for all the Pegged Token prices.
     * @dev All price provider prices must be available, fails if not
     */
    function updateEmas() external {
        if (shouldCalculateEma()) {
            uint256[] memory pACtps = _getPACtps();
            for (uint256 i = 0; i < pACtps.length; i = unchecked_inc(i)) {
                _updateTPema(i, pACtps[i]);
            }
            _updateNextEmaCalculation(emaCalculationTimeSpan);
        }
    }

    /**
     * @param timeSpan_ Defines how many seconds should pass between EMA calculations
     * @dev nextEmaCalculation is not automatically updated, you have to wait until next
     *  EMA calculation to be made : nextEmaCalculation = block.timestamp + emaCalculationTimeSpan
     **/
    function setEmaCalculationTimeSpan(uint256 timeSpan_) external onlyAuthorizedChanger {
        emaCalculationTimeSpan = timeSpan_;
    }

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */

    // Purposely left unused to save some state space to allow for future upgrades
    // slither-disable-next-line unused-state
    uint256[50] private __gap;
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import { MocCore } from "./MocCore.sol";
import { MocQueue } from "../queue/MocQueue.sol";
import { MocQueueExecFees } from "../queue/MocQueueExecFees.sol";
import { IERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import { SafeERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";

/**
 * @title MocOperations
 * @notice All the Moc Protocol operations are grouped in this contract
 */
abstract contract MocOperations is MocCore {
    // ------- Custom Errors -------
    error OnlyQueue();

    // ------- Modifiers -------
    modifier onlyMocQueue() {
        if (msg.sender != mocQueue) revert OnlyQueue();
        _;
    }

    // ----------------- Abstract Functions ---------------------

    /**
     * @notice get the amount of coinbase sent to be used as execution fee
     * @dev this function must be overridden by the AC implementation
     * @param qACTotal_ provided Collateral Asset amount
     * @param operType_ Operation Type
     * @return qACmax maximum amount of Collateral Asset that can be spent on the Operation
     * @return execFee amount of coinbase to be payed as execution Fee
     */
    function _getExecFeeSent(
        uint256 qACTotal_,
        MocQueueExecFees.OperType operType_
    ) internal virtual returns (uint256 qACmax, uint256 execFee);

    /**
     * @notice while executing a pending Operation, if it fails we need to unlock user's funds
     * @param owner_ funds owner, address to be returned to
     * @param qACToUnlock_ AC amount to be unlocked
     */
    function unlockACInPending(address owner_, uint256 qACToUnlock_) external onlyMocQueue {
        unchecked {
            qACLockedInPending -= qACToUnlock_;
        }
        acTransfer(owner_, qACToUnlock_);
    }

    // ----------------- Internal Functions ---------------------

    /**
     * @notice sends the fee to MocMultiCollateralGuard for later execution
     * @param qACTotal_ provided Collateral Asset amount
     * @param operType_ Operation Type
     * @return qACmax maximum amount of Collateral Asset that can be spent on the Operation
     */
    function _transferExecFee(
        uint256 qACTotal_,
        MocQueueExecFees.OperType operType_
    ) internal returns (uint256 qACmax) {
        uint256 execFee;
        (qACmax, execFee) = _getExecFeeSent(qACTotal_, operType_);
        (bool success, ) = payable(address(_getMocMultiCollateralGuard())).call{ value: execFee }("");
        if (!success) revert TransferFailed();
    }

    /**
     * @notice while registering a pending Operation, we need to lock user's funds until it's executed
     * @param qACToLock_ AC amount to be locked
     */
    function _lockACInPending(uint256 qACToLock_) internal virtual {
        qACLockedInPending += qACToLock_;
    }

    /**
     * @notice while registering a pending Operation, we need to lock user's tokens until it's executed
     * @param qTCToLock_ TC amount to be locked
     */
    function _lockTCInPending(uint256 qTCToLock_) internal {
        SafeERC20Upgradeable.safeTransferFrom(tcToken, msg.sender, address(this), qTCToLock_);
    }

    /**
     * @notice while registering a pending Operation, we need to lock user's tokens until it's executed
     * @dev Validates that the TP token is a registered Pegged Token before locking to prevent
     *  attacker-controlled tokens from entering the queue.
     * @param tpToken TP token to lock
     * @param qTPToLock_ TP amount to be locked
     */
    function _lockTPInPending(IERC20Upgradeable tpToken, uint256 qTPToLock_) internal {
        // Reverts with InvalidAddress if `tpToken` is not a registered Pegged Token
        _tpi(address(tpToken));
        SafeERC20Upgradeable.safeTransferFrom(tpToken, msg.sender, address(this), qTPToLock_);
    }

    /**
     * @notice caller sends Collateral Asset and recipient receives Collateral Token
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not
     *   Requires prior sender approval of Collateral Asset to this contract
     * @param qTC_ amount of Collateral Token to mint
     * @param qACmax_ maximum amount of Collateral Asset that can be spent
     * @param recipient_ address who receives the Collateral Token
     * @param vendor_ address who receives a markup
     * @return operId Identifier to track the Operation lifecycle
     */
    function _mintTCtoViaVendor(
        uint256 qTC_,
        uint256 qACmax_,
        address recipient_,
        address vendor_
    ) internal notLiquidated notPaused checkRecipient(msg.sender, recipient_) returns (uint256 operId) {
        uint256 qACmax = _transferExecFee(qACmax_, MocQueueExecFees.OperType.mintTC);
        MintTCParams memory params = MintTCParams({
            qTC: qTC_,
            qACmax: qACmax,
            sender: msg.sender,
            recipient: recipient_,
            vendor: vendor_
        });
        operId = MocQueue(mocQueue).queueMintTC(params);
        _lockACInPending(qACmax);
    }

    /**
     * @notice caller sends Collateral Token and recipient receives Collateral Asset
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not
     * @param qTC_ amount of Collateral Token to redeem
     * @param qACmin_ minimum amount of Collateral Asset that `recipient_` expects to receive
     * @param recipient_ address who receives the Collateral Asset
     * @param vendor_ address who receives a markup
     * @return operId Identifier to track the Operation lifecycle
     */
    function _redeemTCtoViaVendor(
        uint256 qTC_,
        uint256 qACmin_,
        address recipient_,
        address vendor_
    ) internal notLiquidated notPaused checkRecipient(msg.sender, recipient_) returns (uint256 operId) {
        _transferExecFee(msg.value, MocQueueExecFees.OperType.redeemTC);
        RedeemTCParams memory params = RedeemTCParams({
            qTC: qTC_,
            qACmin: qACmin_,
            sender: msg.sender,
            recipient: recipient_,
            vendor: vendor_
        });
        operId = MocQueue(mocQueue).queueRedeemTC(params);
        _lockTCInPending(qTC_);
    }

    /**
     * @notice caller sends Collateral Asset and recipient receives Pegged Token
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not
     *   Requires prior sender approval of Collateral Asset to this contract
     * @param tp_ Pegged Token address to mint
     * @param qTP_ amount of Pegged Token to mint
     * @param qACmax_ maximum amount of Collateral Asset that can be spent
     * @param recipient_ address who receives the Pegged Token
     * @param vendor_ address who receives a markup
     * @return operId Identifier to track the Operation lifecycle
     */
    function _mintTPtoViaVendor(
        address tp_,
        uint256 qTP_,
        uint256 qACmax_,
        address recipient_,
        address vendor_
    ) internal notLiquidated notPaused checkRecipient(msg.sender, recipient_) returns (uint256 operId) {
        uint256 qACmax = _transferExecFee(qACmax_, MocQueueExecFees.OperType.mintTP);
        MintTPParams memory params = MintTPParams({
            tp: tp_,
            qTP: qTP_,
            qACmax: qACmax,
            sender: msg.sender,
            recipient: recipient_,
            vendor: vendor_
        });
        operId = MocQueue(mocQueue).queueMintTP(params);
        _lockACInPending(qACmax);
    }

    /**
     * @notice caller sends Pegged Token and recipient receives Collateral Asset
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not
     * @param tp_ Pegged Token address to redeem
     * @param qTP_ amount of Pegged Token to redeem
     * @param qACmin_ minimum amount of Collateral Asset that `recipient_` expects to receive
     * @param recipient_ address who receives the Collateral Asset
     * @param vendor_ address who receives a markup
     * @return operId Identifier to track the Operation lifecycle
     */
    function _redeemTPtoViaVendor(
        address tp_,
        uint256 qTP_,
        uint256 qACmin_,
        address recipient_,
        address vendor_
    ) internal notLiquidated notPaused checkRecipient(msg.sender, recipient_) returns (uint256 operId) {
        _transferExecFee(msg.value, MocQueueExecFees.OperType.redeemTP);
        RedeemTPParams memory params = RedeemTPParams({
            tp: tp_,
            qTP: qTP_,
            qACmin: qACmin_,
            sender: msg.sender,
            recipient: recipient_,
            vendor: vendor_
        });
        operId = MocQueue(mocQueue).queueRedeemTP(params);
        _lockTPInPending(IERC20Upgradeable(tp_), qTP_);
    }

    /**
     * @notice caller sends Collateral Asset and recipient receives Collateral Token and Pegged Token
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not
     *  Requires prior sender approval of Collateral Asset to this contract
     *  This operation is done without checking coverage
     *  Collateral Token and Pegged Token are minted in equivalent proportions so that its price
     *  and global coverage are not modified.
     *  Reverts if qAC sent are insufficient.
     * @param tp_ Pegged Token address
     * @param qTP_ amount of Pegged Token to mint
     * @param qACmax_ maximum amount of Collateral Asset that can be spent
     * @param recipient_ address who receives the Collateral Token and Pegged Token
     * @param vendor_ address who receives a markup
     * @return operId Identifier to track the Operation lifecycle
     */
    function _mintTCandTPtoViaVendor(
        address tp_,
        uint256 qTP_,
        uint256 qACmax_,
        address recipient_,
        address vendor_
    ) internal notLiquidated notPaused checkRecipient(msg.sender, recipient_) returns (uint256 operId) {
        uint256 qACmax = _transferExecFee(qACmax_, MocQueueExecFees.OperType.mintTCandTP);
        MintTCandTPParams memory params = MintTCandTPParams({
            tp: tp_,
            qTP: qTP_,
            qACmax: qACmax,
            sender: msg.sender,
            recipient: recipient_,
            vendor: vendor_
        });
        operId = MocQueue(mocQueue).queueMintTCandTP(params);
        _lockACInPending(qACmax);
    }

    /**
     * @notice Caller sends Collateral Token and Pegged Token and recipient receives Collateral Asset.
     *  `vendor_` receives a markup in Fee Token if possible or in Collateral Asset if not
     *  This operation is done without checking coverage
     *  Collateral Token and Pegged Token are redeemed in equivalent proportions so that their price
     *  and global coverage are not modified.
     *  Reverts if qTC sent are insufficient.
     * @param tp_ Pegged Token address
     * @param qTC_ Maximum amount of Collateral Token to redeem
     * @param qTP_ Amount of Pegged Token to redeem
     * @param qACmin_ Minimum amount of Collateral Asset that `recipient_` expects to receive
     * @param recipient_ Address who receives the Collateral Asset
     * @param vendor_ Address who receives a markup
     * @return operId Identifier to track the Operation lifecycle
     */
    function _redeemTCandTPtoViaVendor(
        address tp_,
        uint256 qTC_,
        uint256 qTP_,
        uint256 qACmin_,
        address recipient_,
        address vendor_
    ) internal notLiquidated notPaused checkRecipient(msg.sender, recipient_) returns (uint256 operId) {
        _transferExecFee(msg.value, MocQueueExecFees.OperType.redeemTCandTP);
        RedeemTCandTPParams memory params = RedeemTCandTPParams({
            tp: tp_,
            qTC: qTC_,
            qTP: qTP_,
            qACmin: qACmin_,
            sender: msg.sender,
            recipient: recipient_,
            vendor: vendor_
        });
        operId = MocQueue(mocQueue).queueRedeemTCandTP(params);
        _lockTCInPending(qTC_);
        _lockTPInPending(IERC20Upgradeable(tp_), qTP_);
    }

    /**
     * @notice caller sends a Pegged Token and recipient receives another one
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not
     * @param tpFrom_ owned Pegged Token address
     * @param tpTo_ target Pegged Token address
     * @param qTP_ amount of owned Pegged Token to swap
     * @param qTPmin_ minimum amount of target Pegged Token that `recipient_` expects to receive
     * @param qACmax_ maximum amount of Collateral Asset that can be spent in fees
     * @param recipient_ address who receives the target Pegged Token
     * @param vendor_ address who receives a markup
     * @return operId Identifier to track the Operation lifecycle
     */
    function _swapTPforTPtoViaVendor(
        address tpFrom_,
        address tpTo_,
        uint256 qTP_,
        uint256 qTPmin_,
        uint256 qACmax_,
        address recipient_,
        address vendor_
    ) internal notLiquidated notPaused checkRecipient(msg.sender, recipient_) returns (uint256 operId) {
        uint256 qACmax = _transferExecFee(qACmax_, MocQueueExecFees.OperType.swapTPforTP);
        SwapTPforTPParams memory params = SwapTPforTPParams({
            tpFrom: tpFrom_,
            tpTo: tpTo_,
            qTP: qTP_,
            qTPmin: qTPmin_,
            qACmax: qACmax,
            sender: msg.sender,
            recipient: recipient_,
            vendor: vendor_
        });
        operId = MocQueue(mocQueue).queueSwapTPforTP(params);
        _lockTPInPending(IERC20Upgradeable(tpFrom_), qTP_);
        _lockACInPending(qACmax);
    }

    /**
     * @notice caller sends a Pegged Token and recipient receives Collateral Token
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not
     * @param tp_ Pegged Token address
     * @param qTP_ amount of owned Pegged Token to swap
     * @param qTCmin_ minimum amount of Collateral Token that `recipient_` expects to receive
     * @param qACmax_ maximum amount of Collateral Asset that can be spent in fees
     * @param recipient_ address who receives the Collateral Token
     * @param vendor_ address who receives a markup
     * @return operId Identifier to track the Operation lifecycle
     */
    function _swapTPforTCtoViaVendor(
        address tp_,
        uint256 qTP_,
        uint256 qTCmin_,
        uint256 qACmax_,
        address recipient_,
        address vendor_
    ) internal notLiquidated notPaused checkRecipient(msg.sender, recipient_) returns (uint256 operId) {
        uint256 qACmax = _transferExecFee(qACmax_, MocQueueExecFees.OperType.swapTPforTC);
        SwapTPforTCParams memory params = SwapTPforTCParams({
            tp: tp_,
            qTP: qTP_,
            qTCmin: qTCmin_,
            qACmax: qACmax,
            sender: msg.sender,
            recipient: recipient_,
            vendor: vendor_
        });
        operId = MocQueue(mocQueue).queueSwapTPforTC(params);
        _lockTPInPending(IERC20Upgradeable(tp_), qTP_);
        _lockACInPending(qACmax);
    }

    /**
     * @notice Caller sends a Collateral Token and recipient receives Pegged Token.
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not.
     * @param tp_ Pegged Token address
     * @param qTC_ Amount of owned Collateral Token to swap
     * @param qTPmin_ Minimum amount of Pegged Token that `recipient_` expects to receive
     * @param qACmax_ Maximum amount of Collateral Asset that can be spent in fees
     * @param recipient_ Address who receives the Pegged Token
     * @param vendor_ Address who receives a markup
     * @return operId Identifier to track the Operation lifecycle
     */
    function _swapTCforTPtoViaVendor(
        address tp_,
        uint256 qTC_,
        uint256 qTPmin_,
        uint256 qACmax_,
        address recipient_,
        address vendor_
    ) internal notLiquidated notPaused checkRecipient(msg.sender, recipient_) returns (uint256 operId) {
        uint256 qACmax = _transferExecFee(qACmax_, MocQueueExecFees.OperType.swapTCforTP);
        SwapTCforTPParams memory params = SwapTCforTPParams({
            tp: tp_,
            qTC: qTC_,
            qTPmin: qTPmin_,
            qACmax: qACmax,
            sender: msg.sender,
            recipient: recipient_,
            vendor: vendor_
        });
        operId = MocQueue(mocQueue).queueSwapTCforTP(params);
        _lockTCInPending(qTC_);
        _lockACInPending(qACmax);
    }

    // ------- External functions -------

    /**
     * @notice caller sends Collateral Token and recipient receives Collateral Asset
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not
     * @param qTC_ amount of Collateral Token to redeem
     * @param qACmin_ minimum amount of Collateral Asset that `recipient_` expects to receive
     * @param recipient_ address who receives the Collateral Asset
     * @param vendor_ address who receives a markup, `0x0` if not using a vendor
     * @return operId Identifier to track the Operation lifecycle
     */
    function redeemTC(
        uint256 qTC_,
        uint256 qACmin_,
        address recipient_,
        address vendor_
    ) external payable returns (uint256 operId) {
        return _redeemTCtoViaVendor(qTC_, qACmin_, recipient_, vendor_);
    }

    /**
     * @notice caller sends Pegged Token and recipient receives Collateral Asset
     *  `vendor_` receives a markup in Fee Token if possible or in qAC if not
     * @param tp_ Pegged Token address to redeem
     * @param qTP_ amount of Pegged Token to redeem
     * @param qACmin_ minimum amount of Collateral Asset that `recipient_` expects to receive
     * @param recipient_ address who receives the Collateral Asset
     * @param vendor_ address who receives a markup, `0x0` if not using a vendor
     * @return operId Identifier to track the Operation lifecycle
     */
    function redeemTP(
        address tp_,
        uint256 qTP_,
        uint256 qACmin_,
        address recipient_,
        address vendor_
    ) external payable returns (uint256 operId) {
        return _redeemTPtoViaVendor(tp_, qTP_, qACmin_, recipient_, vendor_);
    }

    /**
     * @notice Caller sends Collateral Token and Pegged Token and recipient receives Collateral Asset.
     *  `vendor_` receives a markup in Fee Token if possible or in Collateral Asset if not
     *  This operation is done without checking coverage
     *  Collateral Token and Pegged Token are redeemed in equivalent proportions so that their price
     *  and global coverage are not modified.
     *  Reverts if qTC sent are insufficient.
     * @param tp_ Pegged Token address
     * @param qTC_ Maximum amount of Collateral Token to redeem
     * @param qTP_ Amount of Pegged Token to redeem
     * @param qACmin_ Minimum amount of Collateral Asset that `recipient_` expects to receive
     * @param recipient_ Address who receives the Collateral Asset
     * @param vendor_ address who receives a markup, `0x0` if not using a vendor
     * @return operId Identifier to track the Operation lifecycle
     */
    function redeemTCandTP(
        address tp_,
        uint256 qTC_,
        uint256 qTP_,
        uint256 qACmin_,
        address recipient_,
        address vendor_
    ) external payable returns (uint256 operId) {
        return _redeemTCandTPtoViaVendor(tp_, qTC_, qTP_, qACmin_, recipient_, vendor_);
    }

    // ------- External Only Queue Functions -------

    /**
     * @notice executes Operation based on params, only mocQueue allowed
     * see MocCore _mintTCto for details
     */
    function execMintTC(
        MintTCParams calldata params_
    ) external onlyMocQueue returns (uint256 qACtotalNeeded, FeeCalcs memory feeCalcs) {
        return _mintTCto(params_);
    }

    /**
     * @notice executes Operation based on params, only mocQueue allowed
     * see MocCore _redeemTCto for details
     */
    function execRedeemTC(
        RedeemTCParams calldata params_
    ) external onlyMocQueue returns (uint256 qACtoRedeem, FeeCalcs memory feeCalcs) {
        return _redeemTCto(params_);
    }

    /**
     * @notice executes Operation based on params, only mocQueue allowed
     * see MocCore _mintTPto for details
     */
    function execMintTP(
        MintTPParams calldata params_
    ) external onlyMocQueue returns (uint256 qACtotalNeeded, FeeCalcs memory feeCalcs) {
        return _mintTPto(params_);
    }

    /**
     * @notice executes Operation based on params, only mocQueue allowed
     * see MocCore _redeemTPto for details
     */
    function execRedeemTP(
        RedeemTPParams calldata params_
    ) external onlyMocQueue returns (uint256 qACtoRedeem, FeeCalcs memory feeCalcs) {
        return _redeemTPto(params_);
    }

    /**
     * @notice executes Operation based on params, only mocQueue allowed
     * see MocCore _mintTCandTPto for details
     */
    function execMintTCandTP(
        MintTCandTPParams calldata params_
    )
        external
        onlyMocQueue
        returns (
            uint256 qACtoMintTC,
            uint256 qACtoMintTP,
            uint256 qACtoSpent,
            uint256 qTCMinted,
            FeeCalcs memory feeCalcs
        )
    {
        return _mintTCandTPto(params_);
    }

    /**
     * @notice executes Operation based on params, only mocQueue allowed
     * see MocCore _redeemTCandTPto for details
     */
    function execRedeemTCandTP(
        RedeemTCandTPParams calldata params_
    )
        external
        onlyMocQueue
        returns (
            uint256 qACtoRedeemTC,
            uint256 qACtoRedeemTP,
            uint256 qACtoReceive,
            uint256 qTCRedeemed,
            FeeCalcs memory feeCalcs
        )
    {
        (qACtoRedeemTC, qACtoRedeemTP, qACtoReceive, qTCRedeemed, feeCalcs) = _redeemTCandTPto(params_);
        // return the unused locked TCs
        unchecked {
            uint256 qTCDif = params_.qTC - qTCRedeemed;
            SafeERC20Upgradeable.safeTransfer(tcToken, params_.sender, qTCDif);
        }
    }

    /**
     * @notice executes Operation based on params, only mocQueue allowed
     * see MocCore _swapTCforTPto for details
     */
    function execSwapTCforTP(
        SwapTCforTPParams calldata params_
    ) external onlyMocQueue returns (uint256 qTPMinted, FeeCalcs memory feeCalcs) {
        return _swapTCforTPto(params_);
    }

    /**
     * @notice executes Operation based on params, only mocQueue allowed
     * see MocCore _swapTPforTCto for details
     */
    function execSwapTPforTC(
        SwapTPforTCParams calldata params_
    ) external onlyMocQueue returns (uint256 qTCMinted, FeeCalcs memory feeCalcs) {
        return _swapTPforTCto(params_);
    }

    /**
     * @notice executes Operation based on params, only mocQueue allowed
     * see MocCore _swapTPforTPto for details
     */
    function execSwapTPforTP(
        SwapTPforTPParams calldata params_
    ) external onlyMocQueue returns (uint256 qTPMinted, FeeCalcs memory feeCalcs) {
        return _swapTPforTPto(params_);
    }

    /**
     * @notice while executing a pending Operation, if it fails we need to unlock user's tokens
     * @param owner_ funds owner, address to be returned to
     * @param qTCToUnlock_ TC amount to be unlocked
     */
    function unlockTCInPending(address owner_, uint256 qTCToUnlock_) external onlyMocQueue {
        SafeERC20Upgradeable.safeTransfer(tcToken, owner_, qTCToUnlock_);
    }

    /**
     * @notice while executing a pending Operation, if it fails we need to unlock user's tokens
     * @param owner_ funds owner, address to be returned to
     * @param tpToken_ TP to be unlocked
     * @param qTPToUnlock_ TP amount to be unlocked
     */
    function unlockTPInPending(address owner_, IERC20Upgradeable tpToken_, uint256 qTPToUnlock_) external onlyMocQueue {
        SafeERC20Upgradeable.safeTransfer(tpToken_, owner_, qTPToUnlock_);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.24;

import { IGovernor } from "../interfaces/IGovernor.sol";
import { MocHelper } from "../utils/MocHelper.sol";
import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
  @title Governed
  @notice Base contract to be inherited by governed contracts
  @dev This contract is not usable on its own since it does not have any _productive useful_ behavior
  The only purpose of this contract is to define some useful modifiers and functions to be used on the
  governance aspect of the child contract
  */
abstract contract Governed is Initializable, MocHelper {
    /**
    @notice The address of the contract which governs this one
   */
    IGovernor public governor;

    error NotAuthorizedChanger();

    /**
    @notice Modifier that protects the function
    @dev You should use this modifier in any function that should be called through
    the governance system
   */
    modifier onlyAuthorizedChanger() {
        checkIfAuthorizedChanger();
        _;
    }

    /**
    @notice Initialize the contract with the basic settings
    @dev This initialize replaces the constructor but it is not called automatically.
    It is necessary because of the upgradeability of the contracts
    @param governorAddress_ Governor address
   */
    function __Governed_init(address governorAddress_) internal onlyInitializing {
        __Governed_init_unchained(governorAddress_);
    }

    function __Governed_init_unchained(address governorAddress_) internal onlyInitializing {
        governor = IGovernor(governorAddress_);
    }

    /**
    @notice Change the contract's governor. Should be called through the old governance system
    @param newGovernor_ New governor address
   */
    function changeGovernor(IGovernor newGovernor_) external onlyAuthorizedChanger {
        governor = newGovernor_;
    }

    /**
    @notice Checks if the msg sender is an authorized changer, reverts otherwise
   */
    function checkIfAuthorizedChanger() internal view {
        if (!governor.isAuthorizedChanger(msg.sender)) revert NotAuthorizedChanger();
    }

    /**
     * @dev This empty reserved space is put in place to allow future versions to add new
     * variables without shifting down storage in the inheritance chain.
     * See https://docs.openzeppelin.com/contracts/4.x/upgradeable#storage_gaps
     */

